  FT["PH-H3726"] = {"id":"PH-H3726","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4711_1966.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Makato市","en":"An Act Establishing a Teacher's College in the Municipality of Makato, Province of Aklan and Authorizing the Appropriation of Funds Therefor","orig":"An Act Establishing a Teacher's College in the Municipality of Makato, Province of Aklan and Authorizing the Appropriation of Funds Therefor","vi":"Đạo luật thành lập Cao đẳng Teacher's tại Đô thị Makato, Tỉnh Aklan, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติจัดตั้งวิทยาลัย Teacher's ในเทศบาล Makato จังหวัด Aklan และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang membentuk Sekolah Tinggi Teacher's di Kotamadya Makato, Provinsi Aklan, dan mengalokasikan dana untuk itu","ms":"Akta menubuhkan Kolej Teacher's di Perbandaran Makato, Wilayah Aklan, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 4711","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4711_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3726-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Director of Public Schools, a teachers college in the Municipality of Makato, Province of Aklan, to be known as Northern Panay Teachers College, which shall offer such collegiate courses in teacher education as the Director may determine."}},{"id":"PH-H3726-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of six hundred fifty thousand pesos or so much thereof as may be necessary is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of the said college for the fiscal year nineteen hundred sixty-seven. Thereafter, the sums necessary for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H3726-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53"};
  FT["PH-H3727"] = {"id":"PH-H3727","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4712_1966.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"修订《菲律宾关税与海关法典》若干条的法案","en":"An Act Amending Certain Sections of the Tariff and Customs Code of the Philippines","orig":"An Act Amending Certain Sections of the Tariff and Customs Code of the Philippines","vi":"Đạo luật sửa đổi một số điều của Bộ luật Thuế quan và Hải quan","th":"พระราชบัญญัติแก้ไขเพิ่มเติมบางมาตราแห่งประมวลกฎหมายภาษีศุลกากร","id":"Undang-Undang mengubah beberapa pasal Kitab Undang-Undang Tarif dan Bea Cukai","ms":"Akta meminda beberapa seksyen Kanun Tarif dan Kastam"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 4712","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4712_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3727-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Tariff and Customs Code of the Philippines is hereby amended by inserting between Sections thirty-five hundred and twelve and thirty-five hundred and fourteen thereof, the following new section:\n\"Sec. 3513. Reward to persons instrumental in the discovery and seizure of smuggled goods. To encourage the public and law-enforcement personnel to extend full cooperation and do their utmost in stamping out smuggling, a cash reward equipment to twenty per centum of the fair market value of the smuggled and confiscated goods shall be given to the officers and men and informers who are instrumental in the discovery and seizure of such goods in accordance with the rules and regulations to be issued by the Secretary of Finance.\n\"The provisions of this section, and not those of Republic Act Numbered Twenty-three hundred and thirty-eight, shall govern the giving of reward in cases covered by the former.\""}},{"id":"PH-H3727-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section thirty-six hundred one of the same Code is hereby amended to read as follows:\n\"Sec. 3601. Unlawful Importation. Any person who shall fraudulently import or bring into the Philippines, or assist in so doing, any article, contrary to law, or shall receive, conceal, buy, sell, or in any manner facilitate the transportation, concealment, or sale of such article after importation, knowing the same to have been imported contrary to law, shall be guilty of smuggling and shall be punished with:\n\"1. A fine of not less than fifty pesos more than two hundred pesos and imprisonment of not less than five days nor more than twenty days, if the appraised value, to be determined in the manner prescribed under the Tariff and Customs Code, including duties and taxes, of the article unlawfully imported does not exceed twenty-five pesos;\n\"2. A fine of not less than eight hundred pesos nor more than five thousand pesos and imprisonment of not less than six months and one day nor more than four years, if the appraised value, to be determined in the manner prescribed under the Tariff and Customs Code, including duties and taxes, of the article unlawfully imported exceeds twenty-five pesos but does not exceed fifty thousand pesos;\n\"3. A fine of not less than six thousand pesos nor more than eight thousand pesos and imprisonment of not less than five years and one day nor more than eight years, if the appraised value, to be determined in the manner prescribed under the Tariff and Customs Code, including duties and taxes, of the article unlawfully imported is more than fifty thousand pesos but does not exceed one hundred fifty thousand pesos.\n\"4. A fine of not less than eight thousand pesos nor more than ten thousand pesos and imprisonment of not less than eight years and one day nor more than twelve years, if the appraised value, to be determined in the manner prescribed under the Tariff and Customs Code, including duties and taxes, of the article unlawfully imported exceeds one hundred fifty thousand pesos.\n\"5. The penalty of prision mayor shall be imposed when the crime of serious physical injuries shall have been committed and the penalty of reclusion perpetua to death shall be imposed when the crime of homicide shall have been committed by reason or on the occasion of the unlawful importation.\n\"In applying the above scale of penalties, if the offender is an alien and the prescribed penalty is not death, he shall be deported after serving the sentence without further proceeding for deportation. If the offender is a government official or employee, the penalty shall be the maximum as hereinabove prescribed and the offender shall suffer an additional penalty of perpetual disqualification from public office, to vote and to participate in any public election.\n\"When, upon trial for a violation of this section, the defendant is shown to have had possession of the article in question, possession shall be deemed sufficient evidence to authorize conviction, unless the defendant shall explain the possession to the satisfaction of the court: Provided , however , That payment of the tax due after apprehension shall not constitute a valid defense in any prosecution under this section.\""}},{"id":"PH-H3727-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section thirty-six hundred two of the same code is hereby amended to read as follows:\n\"Sec. 3602. Various fraudulent practices against customs revenue. Any person who makes or attempts to make any entry of imported or exported article by means of any false or fraudulent invoice, declaration, affidavit, letter, paper, or by any means of any false statement, written or verbal, or by any means of any false or fraudulent practice whatsoever, or knowingly effects any entry of goods, wares or merchandise, at less than true weight or measures thereof or upon a false classification as to quality or value, or by the payment of less than the amount legally due, or knowingly and willfully files any false or fraudulent entry or claim for the payment of drawback or refund of duties upon the exportation of merchandise, or makes or files any affidavit, abstract, record, certificate or other document, with a view to securing the payment to himself or others of any drawback, allowance, or refund of duties on the exportation of merchandise, greater than that legally due thereon, or who shall be guilty of any willful act or omission, shall, for each offense, be punished in accordance with the penalties prescribed in the preceding section.\""}},{"id":"PH-H3727-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"With respect to the application of the penalties the degree of participation of the offender, whether as principal, accomplice or accessory, and the appreciation of mitigating, aggravating, or alternative circumstances, the provisions of the Revised Penal Code shall govern."}},{"id":"PH-H3727-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Sections thirty-six hundred three, thirty-six hundred four, thirty-six hundred five, thirty-six hundred six, thirty-six hundred seven, thirty-six hundred eight, thirty-six hundred nine, and thirty-six hundred ten of the same Code are hereby amended to read as follows:\n\"Sec. 3603. Failure to Report Fraud. Any master, pilot in command or other officer, owner or agent of any vessel or aircraft trading with or within the Philippines and any employees of the Bureau of Customs, who, having cognizance of any fraud upon the customs revenue, shall fail to report all information relative thereto to the Collector, as by law required, shall be punished by a fine of not more than five thousand pesos and imprisonment for not more than one year. If the offender is an alien, he shall be deported after serving the sentence. If the offender is public official of employee, he shall suffer additional penalty of perpetual disqualification to hold public office, to vote and to participate in any election.\n\"Sec. 3604. Statutory offenses of officials and employees. Every official, agent or employee of the Bureau of Customs or of any other agency of the government charged with the enforcement of the provisions of this Code, who is guilty of any delinquency hereinbelow indicated shall be punished with a fine of not less than five thousand pesos nor more than fifty thousand pesos and imprisonment for not less than one year nor more than ten years and perpetual disqualification to hold public office, to vote, and to participate in any public election:\n\"a. Those guilty of extortion or willful oppression under color of law.\n\"b. Those who knowingly demand other or greater sums than are authorized by law or receive any fee, compensation, or reward, except as by law prescribed, for the performance of any duty.\n\"c. Those who willfully neglect to give receipts, as by law required, of any sum collected in the performance of duty, or who willfully neglect to perform any of the duties enjoined by law.\n\"d. Those who conspire or collude with another or others the defraud the customs revenue or otherwise violate the law.\n\"e. Those who willfully make opportunity for any person to defraud the customs revenue or who do or fail to do any act with intent to enable any person to defraud said revenue.\n\"f. Those who negligently or designedly permit the violation of the law by any other person.\n\"g. Those who make or sign any false entry or entries in any book, or make or sign any false certificate or return in any case where the law requires the making by them of such entry, certificate or return.\n\"h. Those who, having knowledge or information of a violation of the tariff and customs law or any fraud committed on the revenue collectible by the Bureau of Customs, fail to report such knowledge or information to their superior official or to report as otherwise required by law.\n\"i. Those who, without the authority of law, demand or accept or attempt to collect directly or indirectly as payment or otherwise, any sum of money or other thing of value for the compromise, adjustment, or settlement of any charge or complaint for any violation or alleged violation of law.\n\"Sec. 3605. Concealment or Destruction of Evidence of Fraud. Any person who willfully conceals or destroys, any invoice, book or paper relating to any article liable to duty, after an inspection thereof has been demanded by the Collector of any collection district, or at any time conceals or destroys any such invoice, book or paper for the purpose of suppressing any evidence of fraud therein contained, shall be punished with a fine of not more than five thousand pesos and imprisonment for not more than two years.\n\"Sec. 3606. Affixing Seals. Any person who, without authority, affixes, or attaches a customs seal, fastening, or mark, or any seal, fastening, or mark purporting to be a customs seal, fastening or mark to any vessel, vehicle on land, sea or air, warehouse, or package, shall be punished with a fine not more than twenty thousand pesos or imprisonment of not more than five years, or both. If the offender is an alien, he shall be deported after serving the sentence; and if he is a public official or employee, he shall suffer an additional penalty of perpetual disqualification to hold public office, to vote and to participate in any election.\n\"Sec. 3607. Removal, breakage, alteration of marks. Any person who without authority, willfully removes, breaks, injuries, or defaces or alters any customs seal or other fastening or mark placed upon any vessel, vehicle on land, sea or air warehouse or package containing merchandise or baggage in bond or in customs custody, shall be punished with the penalty prescribed in Section thirty-six hundred six hereof.\n\"Sec. 3608. Removing or repacking goods in warehouse. Any person who fraudulently conceals, removes, or repacks merchandise in any warehouse or fraudulently alters, defaces or obliterates any marks or numbers placed upon packages deposited in such warehouse, or shall aid or abet in any such acts or omission, shall be punished with the penalties prescribed in Section thirty-six hundred six hereof.\n\"Merchandise so concealed, removed, or repacked, or packages upon which any marks or numbers have been so altered, defaced or obliterated, or the value thereof, shall be forfeited to the government.\n\"Sec. 3609. Removing goods from customs custody. Any person who maliciously enters any warehouse, or any vehicle laden with or containing merchandise with intent unlawfully to remove therefrom any merchandise or baggage in such vessel, vehicle or warehouse or otherwise in customs custody or control, or any person who receives or transports any merchandise or baggage unlawfully removed from any such vessel, vehicle or warehouse, or shall aid or abet such removal, shall suffer the penalties provided in Section thirty-six hundred eight hereof.\n\"Sec. 3610. Violations of Tariff and Customs Laws and Regulations in General. Any person who violates a provision of this Code or regulations pursuant thereto, for which delinquency no specific penalty is provided, shall be punished by a fine of not more than one thousand pesos or by imprisonment for not more than one year, or both. If the offender is an alien, he shall be deported after serving the sentence; and if the offender is a public official or employee, he shall suffer disqualification to hold public office, to vote and participate in any public election for ten years.\""}},{"id":"PH-H3727-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966"}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Certain Sections of the Tariff and Customs Code of the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3728"] = {"id":"PH-H3728","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4713_1966.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"对《国家国内税收法典》的修改","en":"An Act Amending Certain Sections of Commonwealth Act Numbered Four Hundred Sixty-Six, as Amended, Otherwise Known as the National Internal Revenue Code","orig":"An Act Amending Certain Sections of Commonwealth Act Numbered Four Hundred Sixty-Six, as Amended, Otherwise Known as the National Internal Revenue Code","vi":"Đạo luật sửa đổi một số điều của Đạo luật Thịnh vượng chung số 466 (Bộ luật Thuế nội địa) như đã được sửa đổi","th":"พระราชบัญญัติแก้ไขเพิ่มเติมบางมาตราแห่งพระราชบัญญัติเครือรัฐที่ 466 (ประมวลรัษฎากร) ซึ่งแก้ไขเพิ่มเติมแล้ว","id":"Undang-Undang mengubah beberapa pasal Undang-Undang Persemakmuran No. 466 (Kitab Undang-Undang Pajak Dalam Negeri) sebagaimana diubah","ms":"Akta meminda beberapa seksyen Akta Komanwel No. 466 (Kanun Hasil Dalam Negeri) sebagaimana dipinda"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 4713","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4713_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3728-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one hundred seventy-four of Commonwealth Act Numbered Four hundred sixty-six, otherwise known as the National Internal Revenue Code, is hereby further amended to read as follows:\n\"Sec. 174. Unlawful possession or removal of articles subject to specific tax without payment of tax. Any person who owns and/or is found in possession of imported articles subject to specific tax, the tax on which had not been paid in accordance with law or any person who owns and/or is found in possession of imported tax exempt articles other than those to whom they are legally issued shall be punished by:\n\"1. A fine of not less than fifty pesos nor more than two hundred pesos and imprisonment of not less than five days nor more than thirty days, if the appraised value, to be determined in the manner prescribed in the Tariff and Customs Code, including duties and taxes, of the article does not exceed five hundred pesos.\n\"2. A fine of not less than six hundred pesos nor more than five thousand pesos and imprisonment of not less than six months and one day nor more than four years, if the appraised value, to be determined in the manner prescribed in the Tariff and Customs Code, including duties and taxes, of the article exceeds five hundred pesos but does not exceed fifty thousand pesos.\n\"3. A fine of not less than five thousand pesos nor more than eight thousand pesos and imprisonment of not less than four years and one day nor more than eight years, if the appraised value to be determined in the manner prescribed in the Tariff and Customs Code, including duties and taxes, of the article is more than fifty thousand pesos but does not exceed one hundred fifty thousand pesos.\n\"4. A fine of not less than eight thousand pesos nor more than ten thousand pesos and imprisonment of not less than eight years and one day nor more than twelve years, if the appraised value, to be determined in the manner prescribed in the Tariff and Customs Code, including duties and taxes, of the article exceeds one hundred fifty thousand pesos.\n\"In applying the above scale of penalties, if the offender is an alien, he shall be deported after serving the sentence without further proceedings for deportation. If the offender is a government official or employee, the penalty shall be the maximum as hereinabove prescribed and, the offender shall suffer an additional penalty of perpetual disqualification for public office, to vote and to participate in any election.\n\"Any person who is found in possession of locally manufactured articles subject to specific tax, the tax on which has not been paid in accordance with law, or any person who is found in possession of such articles which are exempt from specific tax other than those to whom the same is lawfully issued shall be punished with a fine of not less than ten times the amount of the specific tax due on the articles found but not less than two hundred pesos nor more than five thousand pesos and imprisonment of from four months and one day to four years and two months. Any manufacturer, owner, or person in charge of any article subject to a specific tax who removed or allows or procures the unlawful removal of any such article from the place of manufacture or bonded warehouse, upon which article the specific tax has not been paid in the time and manner required, and any person who knowingly aids or abets in the removal of such articles as aforesaid, or conceals the same after illegal removal, shall for the first offense be punished with a fine of not less than ten times the amount of the specific tax due on the articles, but not less than five hundred pesos nor more than ten thousand pesos and imprisonment of not less than six months and one day but not more than six years.\n\"Every manufacturer so offending shall, before continuing or resuming business, execute a bond in double the amount of his original bond and containing the same conditions.\n\"The mere unexplained possession of articles subject to specific tax, the tax on which has not been paid in accordance with law, shall be punished under this section: Provided , however , That payment of the tax due after apprehension shall not constitute a valid defense in any prosecution for violation of this section.\n\"Any ordinance that provides a different penalty for acts punishable under this section is hereby repealed.\""}},{"id":"PH-H3728-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section one hundred seventy-five of the same Code, as amended, is hereby further amended to read as follows:\n\"Sec. 175. Punishment for subsequent offenses. In case of reincidence, the penalty to be imposed for unlawful possession of imported articles shall be the maximum of the penalty prescribed under the first paragraph of Section one hundred seventy-four for the offense constituting the reincidence, and the penalty to be imposed for unlawful possession of locally manufactured articles shall be a fine of not less than ten times the amount of the specific tax due on the articles possessed but not less than two hundred pesos nor more than five thousand pesos and by imprisonment for not less than six months and one day but not more than five years and two months. The penalty for unlawful removal shall be a fine ten times the amount of the specific tax due on the articles removed but not less than one thousand pesos and imprisonment for not less than eight years but not more than twelve years. If the offense be committed by the owner or the manufacturer, or with his connivance, the factory and the ground upon which it stands, including the machinery and apparatus used in and about the business, shall be forfeited.\""}},{"id":"PH-H3728-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"With respect to the application of the penalties, the degree of participation of the offender, whether as principal, accomplice or accessory, and the appreciation of mitigating, aggravating, or alternative circumstances, the provisions of the Revised Penal Code shall govern."}},{"id":"PH-H3728-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section three hundred forty-five of the same Code is hereby amended to read as follows:\n\"Sec. 345. Statutory offenses of officials and employees. Every official, agent or employee of the Bureau of Internal Revenue or of any other agency of the government charged with the enforcement of the provisions of this Code, who is guilty of any delinquency hereinbelow specified or who falls within any of the classes hereinbelow indicated shall be punished with a fine of not less than five thousand pesos nor more than fifty thousand pesos and imprisonment for not less than one year nor more than ten years:\n\"a. Those guilty of extortion or willful oppression under color of law.\n\"b. Those who knowingly demand other or greater sums than are authorized by law or receive any fees, compensation or reward, except as by law prescribed, for the performance of any duty.\n\"c. Those who willfully neglect to give receipts, as by law required, for any sums collected in the performance of duty, or who willfully neglect to perform any of the duties enjoined by law.\n\"d. Those who conspire or collude with another or others to defraud the revenues or otherwise violate the law.\n\"e. Those who willfully make opportunity for any person to defraud the revenues, or who do or omit to do any act with intent to enable any other person to defraud the revenues.\n\"f. Those who negligently or designedly permit the violation of the law by any other person.\n\"g. Those who make or sign any false entry or entries in any book, or make or sign any false certificate or return in any case where the law requires the making by them of such entry, certificate or return.\n\"h. Those who, having knowledge or information of a violation of this Code or any fraud committed on the revenues collectible by the Bureau of Internal Revenue, fail to report such knowledge or information to their superior officer or to report as otherwise required by law.\n\"i. Those who, without the authority of law, demand or accept or attempt to collect directly or indirectly as payment or otherwise, any sum of money or other thing of value for the compromise, adjustment, or settlement of any charge or complaint for any violation or alleged violation of law.\""}},{"id":"PH-H3728-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Section three hundred forty-six of the same Code is hereby amended to read as follows:\n\"Sec. 346. Reward to persons instrumental in the discovery and seizure of smuggled goods. To encourage the public and law-enforcement personnel to extend full cooperation and do their utmost in stamping out smuggling, a cash reward equipment to twenty per centum of the fair market value of the smuggled and confiscated goods shall be given to the officers, and men and informers who are instrumental in the discovery and seizure of such goods in accordance with the rules and regulations to be issued by the Secretary of Finance.\n\"The provisions of this section, and not those of Republic Act Numbered Twenty-three hundred and thirty-eight, shall govern the giving of reward in cases covered by the former.\""}},{"id":"PH-H3728-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966"}}],"pack":"ph-p53"};
  FT["PH-H3729"] = {"id":"PH-H3729","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4714_1966.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"规定为新怡诗夏省4 Additional Assistant 省立 Fiscals，为此修订《行政法典》第1674条（经修正）的法案","en":"An Act Providing Four Additional Assistant Provincial Fiscals for the Province of Nueva Ecija, Amending for the Purpose Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended","orig":"An Act Providing Four Additional Assistant Provincial Fiscals for the Province of Nueva Ecija, Amending for the Purpose Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 4714","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4714_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3729-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The provisions of Section sixteen hundred seventy-four of the Administrative Code, as amended, relative to the number of assistant provincial fiscals in the Province of Nueva Ecija, is further amended to read as follows:\n\"Nueva Ecija, ten assistant provincial fiscals;\""}},{"id":"PH-H3729-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing Four Additional Assistant Provincial Fiscals for the Province of Nueva Ecija, Amending for the Purpose Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3730"] = {"id":"PH-H3730","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4715_1966.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"在宿务省若干市镇划出林地（高地）用于重新造林开发、授权拨款并为其他目的","en":"An Act Setting Aside Timberland (Upland) Areas Within Certain Municipalities in the Province of Cebu for Reforestation Development Purposes, Authorizing the Appropriation of Funds Therefor, and for Other Purposes","orig":"An Act Setting Aside Timberland (Upland) Areas Within Certain Municipalities in the Province of Cebu for Reforestation Development Purposes, Authorizing the Appropriation of Funds Therefor, and for Other Purposes"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 4715","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4715_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3730-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Any provision of law to the contrary notwithstanding, the Secretary of Agriculture and Natural Resources is hereby authorized to set aside timberland (upland) areas which are more or less contiguous and within the Municipalities of Sibonga, Argao, Alcantara, Moalboal, Dalaguete, Badian and Alcoy, all in the Province of Cebu, and to constitute a separate reforestation development area to be known as Southern Cebu Reforestation Development Project, which shall be directly under the Administrator of Reforestation and shall be headed by a Reforestation Development Project Manager, with offices in the Municipality of Argao."}},{"id":"PH-H3730-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Subject to private rights acquired prior to the approval of this Act, the Bureau of Forestry and the Reforestation Administration, under the direction of the Secretary of Agriculture and Natural Resources, shall jointly conduct classification and planting surveys, inspection and delimitation of the timberland areas, which shall be transferred for administration and management to Southern Cebu Reforestation Development Project."}},{"id":"PH-H3730-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Agriculture and Natural Resources is hereby authorized further, to appropriate out of any unallotted balance from the Reforestation Special Funds and/or any savings therefrom, the necessary amounts to carry out immediately the provisions of this Act: Provided, That any appropriation needed thereafter for the operation and maintenance of said project shall be included in the annual General Appropriations Act."}},{"id":"PH-H3730-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Reforestation Administration shall implement and carry out the provisions of this Act pending the installation of the offices of the Reforestation Development Project; and the Administrator of Reforestation shall prepare a staffing pattern for the effective administration and management of said Reforestation Development Project.\nThe Reforestation Development Project Manager, who shall have the rank of a Forestry Projects Coordinator, shall be appointed in accordance with existing laws, and shall have authority to promulgate rules and regulations to carry into effect the provisions of this Act, subject to the approval of the Secretary of Agriculture and Natural Resources, upon recommendation of the Administrator of Reforestation."}},{"id":"PH-H3730-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Setting Aside Timberland (Upland) Areas Within Certain Municipalities in the Province of Cebu for Reforestation Development Purposes, Authorizing the Appropriation of Funds Therefor, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3731"] = {"id":"PH-H3731","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4716_1966.html","fetchedAt":"2026-10-06","articleCount":7,"structureMode":"ARTICLE","title":{"zh":"授予 Angeles Carriedo vda. De Lat 等三人在达沃市与达沃省建设、运营和维护制冰厂与冷藏库并销售冰和供应冷藏的特许权法案","en":"An Act Granting to Angeles Carriedo vda. De Lat, Carolina Lat Perez De Tagle and Pedro C. Lat, Jr., a Franchise to Construct, Operate and Maintain Ice Plants and Cold Storages in the City and Province of Davao, and to Sell Ice and Supply Cold Storage in Davao City and Province of Davao or its Subdivisions Thereof","orig":"An Act Granting to Angeles Carriedo vda. De Lat, Carolina Lat Perez De Tagle and Pedro C. Lat, Jr., a Franchise to Construct, Operate and Maintain Ice Plants and Cold Storages in the City and Province of Davao, and to Sell Ice and Supply Cold Storage in Davao City and Province of Davao or its Subdivisions Thereof"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 4716","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 7 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4716_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3731-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the conditions imposed by this Act, there is hereby granted to Angeles Carriedo Vda. de Lat, Carolina Lat Perez de Tagle and Pedro C. Lat, Jr., a franchise to construct, operate and maintain ice plants and cold storages in the City and Province of Davao or its subdivisions, for the purpose of manufacturing and distributing ice and supplying cold storage services in Davao City and Province of Davao or its subdivisions thereof, and to charge and collect a schedule of prices and rates for ice and cold storage so furnished, which schedule of prices and rates shall at all times be subject to regulations by the Public Service Commission."}},{"id":"PH-H3731-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The grantees shall manufacture and supply ice up to the limit of the capacity of their plants."}},{"id":"PH-H3731-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This franchise shall continue for a period of twenty-five years from the date said plants and cold storages shall be placed in operation and/or shall commence the manufacture and distribution of ice in the City and Province of Davao or its subdivisions thereof and is made subject to the express condition that the same shall be null and void unless the construction of said plants and cold storages be commenced within four years from the date of the approval of this Act and completed within six years from said date, except when prevented by act of God or force majeure, martial law, riot, civil commotion, usurpation by military power or any other cause beyond the control of the grantees."}},{"id":"PH-H3731-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This franchise is granted subject to the provisions of the Constitution and of Commonwealth Act Numbered One hundred forty-six, as amended, only insofar as rates are concerned, and with the understanding and upon the condition that it shall be subject to amendment, alteration or repeal by the Congress of the Philippines when and if public interest so require."}},{"id":"PH-H3731-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The books, records and accounts of the grantee shall always be open to the inspection by the Auditor General or his representatives, and it shall be the duty of the grantees to submit to the Auditor General quarterly reports in duplicate, showing the gross receipts for the quarter past, who shall keep the same on file."}},{"id":"PH-H3731-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"In the event of any competing individual, association of persons, or corporation receiving from the Congress of the Philippines a similar franchise in which there shall be any term or terms more favorable than those herein granted, or tending to place the herein grantees at any disadvantage, then such term or terms shall ipso facto become a part of the terms hereof and shall operate equally in favor of the grantees as in the case of said competing individual, association of persons, or corporations."}},{"id":"PH-H3731-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting to Angeles Carriedo vda. De Lat, Carolina Lat Perez De Tagle and Pedro C. Lat, Jr., a Franchise to Construct, Operate and Maintain Ice Plants and Cold Storages in the City and Province of Davao, and to Sell Ice and Supply Cold Storage in Davao City and Province of Davao or its Subdivisions Thereof","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3732"] = {"id":"PH-H3732","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4717_1966.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"设立Mandaon市","en":"An Act Converting Masbate National Agricultural School in the Municipality of Mandaon, Province of Masbate, into a College to be Known as Masbate Agricultural College, and Authorizing the Appropriation of the Necessary Funds Therefor","orig":"An Act Converting Masbate National Agricultural School in the Municipality of Mandaon, Province of Masbate, into a College to be Known as Masbate Agricultural College, and Authorizing the Appropriation of the Necessary Funds Therefor","vi":"Đạo luật chuyển đổi Masbate National Agricultural School thành Masbate Agricultural College","th":"พระราชบัญญัติเปลี่ยนสถานะ Masbate National Agricultural School เป็น Masbate Agricultural College","id":"Undang-Undang mengubah Masbate National Agricultural School menjadi Masbate Agricultural College","ms":"Akta menukar Masbate National Agricultural School kepada Masbate Agricultural College"},"level":"law","status":"active","topics":["education","environment"],"docNumber":"Republic Act No. 4717","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4717_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3732-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Masbate National Agricultural School located in the Municipality of Mandaon, Province of Masbate, is hereby converted into a college, to be known as Masbate Agricultural College."}},{"id":"PH-H3732-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Masbate Agricultural College shall offer in addition to the secondary agricultural curriculum the following collegiate courses:\na. Four-year Teacher Education leading to the degree of Bachelor of Science in Agricultural Education.\nb. Four-year Technical Agriculture leading to the degree of Bachelor of Science in Agriculture.\nc. Two-year Technical Agriculture leading to the title of Associate in Agriculture."}},{"id":"PH-H3732-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Masbate Agricultural College shall be headed by a superintendent of agricultural instruction and shall be under the Bureau of Vocational Education. The superintendent shall have the direct administration and supervision over all the other agricultural schools in the Province of Masbate under the Bureau of Vocational Education."}},{"id":"PH-H3732-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Secretary of Education is hereby empowered to reorganize said school accordingly."}},{"id":"PH-H3732-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The sum of three hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the operation and maintenance of the said college, in addition to the present national appropriation of the said school, for the fiscal year nineteen hundred sixty-seven. Thereafter, the necessary sum for said purpose shall be included in the annual General Appropriations Act."}},{"id":"PH-H3732-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53"};
  FT["PH-H3733"] = {"id":"PH-H3733","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4718_1966.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第4041号共和国法第6条的法案","en":"An Act Amending Section Six of Republic Act Numbered Forty Hundred Forty-One","orig":"An Act Amending Section Six of Republic Act Numbered Forty Hundred Forty-One","vi":"Đạo luật sửa đổi Điều 6 của Đạo luật Cộng hòa số 4041","th":"พระราชบัญญัติแก้ไขเพิ่มเติมมาตรา 6 แห่งพระราชบัญญัติแห่งสาธารณรัฐที่ 4041","id":"Undang-Undang mengubah Pasal 6 Undang-Undang Republik No. 4041","ms":"Akta meminda Seksyen 6 Akta Republik No. 4041"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4718","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4718_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3733-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section six of Republic Act Numbered Forty hundred forty-one is amended to read as follows:\n\"Sec. 6. To provide funds for dairy research and training of manpower, there is hereby appropriated annually the sum of one million pesos out of any funds in the National Treasury not otherwise appropriated, for the use of the dairy training and research institute, under the supervision and control of the University of the Philippines: Provided, That any income derived from the activities of the Institute shall be available for expenditure by it until expended.\""}},{"id":"PH-H3733-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Section Six of Republic Act Numbered Forty Hundred Forty-One","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3734"] = {"id":"PH-H3734","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4719_1966.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第4341号共和国法（即《授权为菲律宾大学内规划学院的建筑、设施与运营费用拨款并为其他目的》）第2条的法案","en":"An Act Amending Section Two of Republic Act Numbered Four Thousand Three Hundred Forty-One, Entitled \"An Act Authorizing the Appropriation of Funds for Buildings, Facilities and Operating Expenses of the Institute of Planning Within the University of the Philippines, and for Other Purposes\"","orig":"An Act Amending Section Two of Republic Act Numbered Four Thousand Three Hundred Forty-One, Entitled \"An Act Authorizing the Appropriation of Funds for Buildings, Facilities and Operating Expenses of the Institute of Planning Within the University of the Philippines, and for Other Purposes\"","vi":"Đạo luật sửa đổi Điều 2 của Đạo luật Cộng hòa số 4341, và cho các mục đích khác","th":"พระราชบัญญัติแก้ไขเพิ่มเติมมาตรา 2 แห่งพระราชบัญญัติแห่งสาธารณรัฐที่ 4341 และเพื่อวัตถุประสงค์อื่น","id":"Undang-Undang mengubah Pasal 2 Undang-Undang Republik No. 4341, dan untuk tujuan lain","ms":"Akta meminda Seksyen 2 Akta Republik No. 4341, dan untuk tujuan lain"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 4719","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4719_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3734-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section two of Republic Act Numbered Four thousand three hundred forty-one is hereby amended to read as follows:\n\"Sec. 2. Pursuant to this policy, the University of the Philippines is hereby authorized to establish an Institute of Planning, for which there is hereby authorized to be appropriated four hundred thousand pesos, out of the general funds of the National Treasury not otherwise appropriated, for the construction of buildings and the purchase of equipment and facilities necessary for the establishment of the Institute: Provided, However, That an additional amount of three hundred and fifty thousand pesos is hereby appropriated for the operating expenses of the Institute for fiscal year nineteen hundred and sixty-six to nineteen hundred and sixty-seven: And Provided, further, That at least the amount of three hundred fifty thousand pesos shall be appropriated annually thereafter, out of any funds in the National Treasury not otherwise appropriated, beginning with the next succeeding fiscal year for operational expenses of the Institute.\""}},{"id":"PH-H3734-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Section Two of Republic Act Numbered Four Thousand Three Hundred Forty-One, Entitled \"An Act Authorizing the Appropriation of Funds for Buildings, Facilities and Operating Expenses of the Institute of Planning Within the University of the Philippines, and for Other Purposes\"","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3735"] = {"id":"PH-H3735","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4720_1966.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立菲律宾蕉麻公司的法案","en":"An Act to Establish the Abaca Corporation of the Philippines","orig":"An Act Amending Certain Sections of Republic Act Numbered Twelve Hundred Ninety-Five, Entitled \"An Act to Establish the Abaca Corporation of the Philippines\"","vi":"Đạo luật thành lập Tổng công ty Abaca Philippines","th":"พระราชบัญญัติจัดตั้งบรรษัท Abaca Philippines","id":"Undang-Undang membentuk Korporasi Abaca Philippines","ms":"Akta menubuhkan Perbadanan Abaca Philippines"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4720","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4720_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3735-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section two of Republic Act Numbered Twelve hundred ninety-five is hereby amended to read as follows:\n\"Sec. 2. Purposes and objectives.— The Abaca Corporation of the Philippines shall have the following objectives:\n\"(a) To insure a permanent, sufficient and balanced production of abaca, maguey and other fibers for the requirements of the local industry and for exportation.\n\"(b) To check all speculation tending to promote a decrease in the prices of abaca, maguey and other fibers and to stabilize said prices at a level sufficient to cover the cost of production plus a reasonable profit.\n\"(c) To assist in preventing a short as well as an excess production of abaca, maguey and other fibers and in either case serve as a regulating organ in order to avoid a disorganization of this activity of the national economy and its consequences, such as suspensions of work, unemployment and other social calamities.\n\"(d) To promote the effective merchandising of abaca, maguey and other fibers in the domestic and foreign markets so that those engaged in the said industries will be placed on a basis of economic security.\n\"(e) To establish warehousing and marketing facilities in suitable centers and supervise the selling and buying of abaca, maguey and other fibers.\n\"(f) To promote the prompt, extensive and thorough industrialization of the abaca, maguey and other fibers industries.\n\"In achieving the above-named purposes and objectives of this Act, the Abaca Corporation shall limit its activities or intervention simply in aid of private capital or enterprise already dedicated or ready to be dedicated in any manner directly or indirectly to the promotion of the abaca, maguey and other fibers industries in the Philippines: Provided, However, That if no private capital shall be interested in any of the proposed activities of the Corporation, then it may directly initiate, promote and develop such activities.\""}},{"id":"PH-H3735-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section three of the same Act is hereby amended to read as follows:\n\"Sec. 3. Specific and general powers.— For carrying out the purposes mentioned in the preceding section, subject to the terms of the last paragraph thereof, the Abaca Corporation of the Philippines shall have authority:\n\"(a) To buy, sell, export, barter, and in any other manner deal in abaca, maguey and other fibers.\n\"(b) To buy, sell, assign, own, operate, rent or leave subject to existing law, merchant vessels, rails, railroad lines, and any other means of transportation, stripping machines, decorticators, presses, warehouses, buildings, and any other equipment and material for stripping, decorticating, warehousing and, in general, for everything connected with the proper handling of abaca, maguey and other fibers.\n\"(c) To act as agent, broker, commission merchant or representative of the producers, merchants, pressmen or other dealers in abaca, maguey and other fibers and the products derived therefrom.\n\"(d) To grant loans to abaca, maguey and other fibers planters, cooperatives or centrals guaranteed by a mortgage or pledge on abaca and maguey crops, fibers or other securities: Provided, However, That no loan shall be granted, which is in excess of eighty per cent of the market value of the securities: And Provided, further, That interest thereon shall not be in excess of four per cent per annum.\n\"(e) To invest the funds of the Corporation in the form of ordinary or preferred shares, in any private corporation established for the purpose of raising, developing, managing or administering abaca, maguey and other fiber plantations or establishing industrial plants using abaca, maguey and other fibers or its by-products as their prime raw materials, or warehouses for the storage of abaca, maguey and other fibers, its by-products, derivative or resulting manufactured products, or cooperatives founded in aid of the abaca, maguey, and other fibers industries: Provided, However, That no investment in excess of one million pesos shall be granted without the approval of the Department of Agriculture and Natural Resources or its successors.\n\"(f) To borrow or otherwise raise funds for carrying out the objects of this corporation, whenever the needs of this industry require it, with the consent of the President of the Philippines.\n\"(g) To enter into, make and execute contracts of any kind as may be necessary or incidental to the attainment of its purposes, with any person, firm or public or private corporation, with the Governments of the Philippines or the United States or any state, territory or possession thereof, or with any foreign government.\n\"(h) In general, to do everything directly or indirectly necessary or incidental to, or in furtherance of the purposes of the Corporation.\n\"(i) In the transaction of its business, to perform all acts which a co-partnership or natural person is authorized to perform under the laws now existing or which may be enacted hereafter.\n\"(j) Generally, to exercise such incidental powers as may be necessary to carry out the purposes and objectives of this Act within the limitations prescribed by the same.\""}},{"id":"PH-H3735-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Sections seven and eight of the same Act are hereby amended to read as follows:\n\"Sec. 7. Capitalization.— The capital stock of the Abaca Corporation of the Philippines shall be forty million pesos, divided into four hundred thousand shares of stock, having a par value of one hundred pesos each, and no stock of said corporation shall be issued at less than par or except for cash.\n\"The entire authorized capital of forty million pesos shall be subscribed for and paid by the Republic of the Philippines upon the organization of said Corporation in the manner provided in the following section.\"\n\"Sec. 8. Payment of Subscription to the Capital.— The amount of forty million pesos required to pay for the entire authorized capitalization of the Abaca Corporation of the Philippines herein recited shall be raised by means of the sale or disposition of bonds under Republic Act Numbered One thousand, and for that purpose it is hereby declared that the organization of the Abaca Corporation of the Philippines is one of the economic projects contemplated under said Act to be financed by the sale or disposition of bonds therein specifically authorized to be sold; or, by borrowings which the Government of the Republic of the Philippines may be able to secure thru the Central Bank; or out of funds in the National Treasury not otherwise appropriated of which the amount of forty million pesos is hereby appropriated: Provided, However, That Four million pesos be devoted to the development of maguey and other fibers.\n\"There shall be added to the capital of the Abaca Corporation of the Philippines all the funds, assets and properties still available belonging to the defunct National Abaca Fibers Corporation. In the event that there is an urgent or immediate need for funds to carry out the trading and industrialization program of the Abaca Corporation and the funds herein appropriated are insufficient for such purpose, the abacorp may borrow the needed amount to be guaranteed by the Central Bank of the Philippines from any of the Government financial institution, such as the Philippine National Bank, Development Bank of the Philippines and the Government Service Insurance System.\""}},{"id":"PH-H3735-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Establish the Abaca Corporation of the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3736"] = {"id":"PH-H3736","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4721_1966.html","fetchedAt":"2026-10-06","articleCount":11,"structureMode":"ARTICLE","title":{"zh":"延长 Abaca 发展计划期限、将其活动扩大至其他纤维并维持其自有资金的法案","en":"An Act Extending the Life of the Abaca Development Program, Expanding its Activities to Cover Other Fibers, and Maintaining its Own Funds","orig":"An Act Extending the Life of the Abaca Development Program, Expanding its Activities to Cover Other Fibers, and Maintaining its Own Funds"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4721","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 11 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4721_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3736-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"This Act shall be known as the Abaca and Other Fibers Development Program Act."}},{"id":"PH-H3736-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"It is hereby declared to be a national policy to rehabilitate and expand the abaca and other fibers industry of the country to maintain its world supremacy and the world demand for abaca and other Philippine fibers and their by-products, and to provide adequate measures to ensure permanent stability in the production and consumption of abaca and other fibers."}},{"id":"PH-H3736-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Abaca and Other Fibers Development Program envisioned in this Act shall be under the direct control and supervision of the Secretary of Agriculture and Natural Resources, through a Board composed of the Director of the Bureau of Plant Industry, Director of the Bureau of Fiber Inspection Service, Commissioner of the Agricultural Productivity Commission, one representative each of the three abaca producing regions, namely Bicol, Visayas and Mindanao, and a representative of the Philippine Association of Abaca Producers and Exporters to be appointed by the President of the Philippines for a term of one year with the consent of the Commission on Appointments of the Congress of the Philippines. Each member shall receive a per diem of fifty pesos per meeting actually attended: Provided, That no member shall earn more than two hundred pesos in per diems, allowances and other forms of compensation every month."}},{"id":"PH-H3736-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Program shall cover the following phases considered necessary to attain the primary objectives to bring at least to pre-war level the production of abaca and other fibers, to reduce their cost of production in order to complete successfully with other hard fibers in the world markets, to achieve the desired level of abaca and other Philippine fibers exports, and finally, to maintain a well-balanced production and demand of abaca and other fibers:\n1. Production and distribution of planting materials to be disposed at nominal cost, for the rehabilitation of depleted plantations and expansion to newly opened areas;\n2. Improvement and operation of fibers extraction methods to reduce cost of production and improve the quality of the fibers;\n3. Development, establishment, promotion and operation of new industries using abaca and other fibers as raw materials: Provided, That no industry shall be established that will compete with existing industries and once an industry is made self-sustaining and profitable the same shall be turned over to the private enterprises, preferably cooperatives, upon payment of the cost of the machineries and equipment including all taxes, customs duties and other charges assessable and due at the time of the importation of such machineries and equipment, if not exempted under existing tax laws and tariff regulations;\n4. Abaca and other fibers scientific, agricultural, industrial and commercial research;\n5. Abaca and other fibers local and foreign trade promotion; and\n6. General administration."}},{"id":"PH-H3736-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The balance of appropriations provided for in Republic Act Numbered Three thousand forty-five shall continue to be expended to carry out the provisions of this Act."}},{"id":"PH-H3736-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Any amount earned in the operation of any of the projects under the Abaca and Other Fibers Development Program shall be credited to the name of the Program and constituted as a revolving fund to be used as determined by the Program through the resolution of the Board."}},{"id":"PH-H3736-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The budget and the production plan for each year shall be prepared by the Program and submitted to the Board for approval within thirty days before the end of each fiscal year."}},{"id":"PH-H3736-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The Abaca and Other Fibers Development Program shall have an auditor who shall be assisted by his staff to be appointed by the Auditor General, whose salaries and all other expenses of maintaining the auditor’s office shall be paid by the Program."}},{"id":"PH-H3736-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The general manager of the Abaca and Other Fibers Development Program shall tender a yearly report through the Secretary of Agriculture and Natural Resources to the President of the Philippines, the President of the Senate and the Speaker of the House of Representatives on the operation of the Program, furnishing copies thereof the Committee on Agriculture of both Chambers of Congress, not later than thirty days after the end of each fiscal year."}},{"id":"PH-H3736-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"All laws or parts thereof, inconsistent with the provisions of this Act are hereby repealed."}},{"id":"PH-H3736-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"This Act shall take effect upon its approval and shall continue to be in effect for a period of one year from the approval hereof.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Extending the Life of the Abaca Development Program, Expanding its Activities to Cover Other Fibers, and Maintaining its Own Funds","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3737"] = {"id":"PH-H3737","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4722_1966.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将宿务省第三与第四国会选区划为独立工程区并为其他目的法案","en":"An Act Constituting the Third and Fourth Congressional Districts of the Province of Cebu into a Separate Engineering District, and for Other Purposes","orig":"An Act Constituting the Third and Fourth Congressional Districts of the Province of Cebu into a Separate Engineering District, and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4722","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4722_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3737-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Any provision of law to the contrary notwithstanding, the Third and Fourth Congressional District of the Province of Cebu are hereby constituted into a separate engineering district, to be known as the Fifth Engineering District of the Province of Cebu, with principal offices at the Municipality of Argao, same province."}},{"id":"PH-H3737-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Public Works and Communications is hereby authorized to appropriate the necessary sums, out of any unallotted funds and/or savings under the department, to carry into effect the provisions of this Act and to transfer the necessary personnel, records, property, equipment, and other supplies and materials, to carry out the provisions of this Act. Thereafter, the necessary sums for the purpose shall be included in the annual General Appropriations Act."}},{"id":"PH-H3737-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Constituting the Third and Fourth Congressional Districts of the Province of Cebu into a Separate Engineering District, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3738"] = {"id":"PH-H3738","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4723_1966.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"重视中小学课程中的音乐教学并为此拨款的法案","en":"An Act Giving Importance to the Teaching of Music in the Curricula of Elementary and Secondary Schools, and Appropriating Funds Therefor","orig":"An Act Giving Importance to the Teaching of Music in the Curricula of Elementary and Secondary Schools, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["trade","education"],"docNumber":"Republic Act No. 4723","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4723_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3738-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Commencing with the school year nineteen hundred sixty-six—sixty-seven, music shall be taught together with arts as a separate subject area, with music allotted three days a week in all the grades in elementary schools, whether public or private; and shall be taught together with arts, physical education and health as a separate subject field, with music allotted at least one day a week in all the years in general or vocational secondary schools, whether public or private."}},{"id":"PH-H3738-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Education shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H3738-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of five hundred thousand pesos is hereby appropriated, out of any funds in the National Treasury not otherwise appropriated, to carry out the purpose of this Act during the fiscal year nineteen hundred sixty-six—sixty-seven. Thereafter, such sums as may be necessary for the same purpose shall be included in the annual General Appropriations Act."}},{"id":"PH-H3738-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Giving Importance to the Teaching of Music in the Curricula of Elementary and Secondary Schools, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3739"] = {"id":"PH-H3739","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4724_1966.html","fetchedAt":"2026-10-06","articleCount":11,"structureMode":"ARTICLE","title":{"zh":"通过设立金属工业发展中心发展菲律宾金属工业、为此提供资金并为其他目的法案","en":"An Act to Develop the Metals Industry of the Philippines by Establishing the Metals Industry Development Center, Providing Funds Therefor, and for Other Purposes","orig":"An Act to Develop the Metals Industry of the Philippines by Establishing the Metals Industry Development Center, Providing Funds Therefor, and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4724","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 11 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4724_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3739-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Declaration of Policy.— It is hereby declared a national policy to develop and expand the metals industry of the country by maintaining close coordination with the private sector in putting up a non-profit research organization to provide both the government and the private sector with professional management and technical expertise on such vital activities for the development of the industry as training of engineers and technicians, information exchange, trade accreditation service, quality control and testing of metal products, research and business economics advisory services."}},{"id":"PH-H3739-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Definition of Terms.— As used in this Act, the following shall be understood to mean: (a) The term \"metals industry\" shall refer to the manufacture from ore materials of products of all precious, base and rare metals and their alloys, including all processes from smelting in direct or indirect reduction furnaces to the final finished product state, either separately or part of an integrated process, namely: the production of bullion, pig ingots, billets, pellets, blooms, skelps, slabs or bars, and rolling and/or processing into basic forms such as sheets, plates, strips, tubes, conduits, pipes, rails, rods, tin-plates and the like, and the rough castings, forgings, and extrusions, and the final processing, manufacture, fabrication, and/or assembly into finished metal products such as power generating machinery, agricultural machinery and implements, office machinery, metal working machinery, mining, construction, and all other industrial machinery, and machine parts and accessories; electric machinery, apparatus and appliances such as generators, transformer, motors and the like, and their metal parts and accessories; transport equipment such as railway locomotives and cars, passenger road motor vehicles, motorcycles, trucks, lorries, bicycles and other cycles, aircraft, ships and boats and their metal parts and accessories; and various metal manufactures such as railway construction accessories, wires, tubes and fittings, firearms, wires netting and the like, nails, bolts, and similar articles, needles and pins, safes, hand tools and implements, tools, dies and molds, household utensils, forks and spoons and cutlery, hardwares and metals, metal containers for transport and storage, and other miscellaneous manufactured articles of base, precious and rare metals and their alloys.\n(b) \"Allied industries\" shall refer to such industries as the coal and coke and the refractory industries, the principal manufactured products of which are consumed by the metals industries in the processing of metallic raw materials into finished or semi-finished products."}},{"id":"PH-H3739-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Fund to carry out provisions of this Act.— Pursuant to the national policy enunciated in Section one of this Act, there is hereby established a special fund, to be known as the Metals Industry Development Fund, consisting of government contribution in the amount of seven million five hundred thousand pesos, the private sector contribution as provided in section 7 hereof, and the reasonable fees and charges that may be collected for services rendered by the Metals Industry Development Center. For this purpose, the sum of one million five hundred thousand pesos is hereby authorized to be appropriated upon the approval of this Act out of the funds of the national treasury not otherwise appropriated and one million pesos annually thereafter for a period of six years as the government contribution to the said fund: Provided, That any unexpended balance thereof shall not revert to the general fund."}},{"id":"PH-H3739-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Establishment of Metals Industry Development Center.— There is hereby established a Metals Industry Development Center, organized jointly by and with the support of the government and private sectors as a non-profit institution, to undertake the following activities:\na. Business economics advisory services:\n(1) To provide management services to industrial firms to help increase their operational and financial efficiency;\n(2) To render consultation services in the preparation of feasibility studies for new projects for the metals and allied industry;\n(3) To provide a periodic analysis of the economic status of the industry and its component sectors as a guide for policy determination by the government and as an individual framework for financial institutions;\n(4) To serve as liaison between the private sector and the government agencies implementing industrial policies to provide close rapport required for a successful development for the metal and allied industries; and\n(5) To provide computer services, including the preparation of computer programs for operations research type of applications to the metals industry.\nb. Training, information exchange, and accreditation service:\n(1) To operate an information exchange center to gather and disseminate information on recent economic and technological developments, both local and foreign, that are of interest to the industry;\n(2) To assemble and maintain an up-to-date library on metals economics and technology;\n(3) To collect information and statistics for preparation of comprehensive and up-to-date industry studies;\n(4) To maintain, an effective training program for engineers, technicians and craftsmen to cope with the immediate manpower requirements of metal plants and metal fabrication industries;\n(5) To correlate all studies made on the various sectors of the metals and allied industries as a basis for constructing a development program and a framework for investment to induce to rapid and systematic growth of the industry;\n(6) To design, develop, and implement a system of accreditation for skilled laborers, technicians and engineers who have attained a degree of experience or proficiency in the various fields of specialization in the metals industry;\nc. Control and testing of metal products:\n(1) To institute appropriate standards for the metals industry as a protection for the consumer and to enable local producers to attain quality that will equal if not surpass international standards;\n(2) To study, recommend and private upon request suitable production methods that private industry may adopt to improve quality and to standardize products to comply with the close tolerance requirements of mass production and modern engineering products;\n(3) To provide umpire services in arbitration cases between suppliers and customers dealing with metals or intermediate and finished products of the metals industry;\nd. Metals research and development:\n(1) To establish a metals research and development laboratory to provide ready answers to common problems encountered by the metals industry;\n(2) To provide valuable working experience and opportunities for professional development to creative Filipino engineers at both the professional and student levels in the fields of metal technology;\n(3) To develop and introduce methods and processes based on the maximum utilization of indigenous raw materials to lower cost of manufacturing common type of metal products;\n(4) To encourage the development of the tributary industries with emphasis on those which may use locally available materials, such as coal chemicals and refractories;\n(5) To undertake fully or lend support to other engineering firms which lack the physical facilities for performing developmental or evaluation tests to improve existing plant methods or to introduce new ones;"}},{"id":"PH-H3739-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Board of Trustees.— The metals industry development center shall, during the first seven years from the approval of this Act, be administered by a board of trustees composed of the chairman of the National Science Development Board, a representative of the National Economic Council, the Director of Mines, the general manager of the National Shipyards and Steel Corporation and three representatives from the private sector representing the metals industry, who shall be appointed by the President of the Philippines, upon recommendation of the particular sector of the industry which they represent, for a term of seven years with the consent of the Commission on Appointments.\nDuring the first four years of its organization, the chairman of the National Science Development Board shall be the chairman of the board. The Vice-Chairman shall be a representative of the private sector who shall be chosen by them among themselves: Provided, That during the fifth to the seventh year, the chairmanship shall come from the private sector chosen in the manner provided above and the vice-chairman shall be the chairman of the National Science Development Board: Provided, further, That after the seven years the board shall be automatically dissolved and the private sector shall have the discretion to reorganize a new board with the chairman of the National Science Development Board being retained as an ex-officio member and: Provided finally, That the members of the board shall not receive any compensation except a per diem of fifty pesos for every session of the board which they attended but not to exceed two hundred pesos each month."}},{"id":"PH-H3739-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Powers and Duties of the Board.— The board of trustees shall exercise the following powers and duties:\n(a) To formulate plans and programs and promulgate such policies, procedures, rules and regulations as may be necessary for the effective operation of the metals industry development center;\n(b) To receive, administer, dispose of and disburse the funds of the center;\n(c) To receive in trust legacies, gifts and donations of whatever kind given to the center;\n(d) To appoint the technical and administrative personnel of the center and fix their compensation, terms of office and other conditions of employment;\n(e) To create donor positions which shall accommodate exceptionally qualified research engineers or scientists in metallurgy from both government and private sector and visiting research scientists;\n(f) To enter into contracts for and in behalf of the center; and\n(g) To exercise such other powers and functions as may be necessary to carry out the provisions of this Act."}},{"id":"PH-H3739-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Responsibilities of the private sector.— To be entitled to the benefits provided for under Section three of this Act, the private sector have the following responsibilities:\na. To provide an initial contribution in the amount of one hundred thousand pesos upon the approval of this Act and, annually thereafter for a period of six years, the amount of one hundred fifty thousand pesos for the capital and operational requirements of the research institution contemplated under this Act; and\nb. To assume full responsibility of carrying on the operation of the research institution after the government assistance shall have phased out."}},{"id":"PH-H3739-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Ownership of property.— All properties, equipment and facilities acquired through the Metals Industry Development Fund shall be owned by the research institution to be established under this Act: Provided, However, That if the said institution is dissolved within seven years from the approval of this Act, the ownership of all such properties, equipment and facilities shall revert to the National Science Development Board."}},{"id":"PH-H3739-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Repealing clause.— All laws, executive orders, rules and regulations, or parts thereof, inconsistent with this Act are hereby repealed or modified in conformity herewith."}},{"id":"PH-H3739-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Separability clause.— The provisions of this Act are separable and in the event that any one or more of such provisions are declared unconstitutional the validity of the other provisions shall not be impaired."}},{"id":"PH-H3739-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Effectivity.— This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Develop the Metals Industry of the Philippines by Establishing the Metals Industry Development Center, Providing Funds Therefor, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3740"] = {"id":"PH-H3740","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4725_1966.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"修订第4206号共和国法（题为“禁止向公立初等与中级学校学童收取捐款”）的法案","en":"An Act to Amend Republic Act Numbered Four Thousand Two Hundred Six Entitled \"An Act Prohibiting the Collection of Contributions from School Children of Public Primary and Intermediate Schools\"","orig":"An Act to Amend Republic Act Numbered Four Thousand Two Hundred Six Entitled \"An Act Prohibiting the Collection of Contributions from School Children of Public Primary and Intermediate Schools\"","vi":"Đạo luật sửa đổi Đạo luật Cộng hòa số 4206","th":"พระราชบัญญัติแก้ไขเพิ่มเติมพระราชบัญญัติแห่งสาธารณรัฐที่ 4206","id":"Undang-Undang mengubah Undang-Undang Republik No. 4206","ms":"Akta meminda Akta Republik No. 4206"},"level":"law","status":"active","topics":["civil","education"],"docNumber":"Republic Act No. 4725","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4725_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3740-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section 1 of the Republic Act Numbered Four thousand two hundred six is hereby amended to read as follows:\n\"Sec. 1. The collection of contributions for the Anti-Tuberculosis, Parent-Teacher Associations, School Athletic Meets, Medical and Dental Services or for any other project or purpose, whether voluntary or otherwise, from school children and teachers of public primary, intermediate and high schools is hereby prohibited: Provided, However, That this prohibition shall not cover membership fees of school children in the Red Cross, the girl scouts of the Philippines and the boy scouts of the Philippines.\""}},{"id":"PH-H3740-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The title of Republic Act Numbered four thousand two hundred six is hereby amended to read as follows:\n\"An Act Prohibiting the Collection of Contributions from School Children of Public Primary, Intermediate and High Schools\""}},{"id":"PH-H3740-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Republic Act Numbered Four Thousand Two Hundred Six Entitled \"An Act Prohibiting the Collection of Contributions from School Children of Public Primary and Intermediate Schools\"","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3741"] = {"id":"PH-H3741","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4726_1966.html","fetchedAt":"2026-10-06","articleCount":27,"structureMode":"ARTICLE","title":{"zh":"界定共管公寓、规定其设立要件并规范其相关事项的法案","en":"An Act to Define Condominium, Establish Requirements for its Creation, and Govern its Incidents","orig":"An Act to Define Condominium, Establish Requirements for its Creation, and Govern its Incidents"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4726","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 27 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4726_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3741-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The short title of this Act shall be \"The Condominium Act\" ."}},{"id":"PH-H3741-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"A condominium is an interest in real property consisting of separate interest in a unit in a residential, industrial or commercial building and an undivided interest in common, directly or indirectly, in the land on which it is located and in other common areas of the building. A condominium may include, in addition, a separate interest in other portions of such real property. Title to the common areas, including the land, or the appurtenant interests in such areas, may be held by a corporation specially formed for the purpose (hereinafter known as the \"condominium corporation\") in which the holders of separate interest shall automatically be members or shareholders, to the exclusion of others, in proportion to the appurtenant interest of their respective units in the common areas.\nThe real right in condominium may be ownership or any other interest in real property recognized by law, on property in the Civil Code and other pertinent laws."}},{"id":"PH-H3741-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"As used in this Act, unless the context otherwise requires:\n(a) \"Condominium\" means a condominium as defined in the next preceding section.\n(b) \"Unit\" means a part of the condominium project intended for any type of independent use or ownership, including one or more rooms or spaces located in one or more floors (or part or parts of floors) in a building or buildings and such accessories as may be appended thereto.\n(c) \"Project\" means the entire parcel of real property divided or to be divided in condominiums, including all structures thereon,\n(d) \"Common areas\" means the entire project excepting all units separately granted or held or reserved.\n(e) \"To divide\" real property means to divide the ownership thereof or other interest therein by conveying one or more condominiums therein but less than the whole thereof."}},{"id":"PH-H3741-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The provisions of this Act shall apply to property divided or to be divided into condominiums only if there shall be recorded in the Register of Deeds of the province or city in which the property lies and duly annotated in the corresponding certificate of title of the land, if the latter had been patented or registered under either the Land Registration or Cadastral Acts, an enabling or master deed which shall contain, among others, the following:\n(a) Description of the land on which the building or buildings and improvements are or are to be located;\n(b) Description of the building or buildings, stating the number of stories and basements, the number of units and their accessories, if any;\n(c) Description of the common areas and facilities;\n(d) A statement of the exact nature of the interest acquired or to be acquired by the purchaser in the separate units and in the common areas of the condominium project. Where title to or the appurtenant interests in the common areas is or is to be held by a condominium corporation, a statement to this effect shall be included;\n(e) Statement of the purposes for which the building or buildings and each of the units are intended or restricted as to use;\n(f) A certificate of the registered owner of the property, if he is other than those executing the master deed, as well as of all registered holders of any lien or encumbrance on the property, that they consent to the registration of the deed;\n(g) The following plans shall be appended to the deed as integral parts thereof:\n(1) A survey plan of the land included in the project, unless a survey plan of the same property had previously bee filed in said office;\n(2) A diagrammatic floor plan of the building or buildings in the project, in sufficient detail to identify each unit, its relative location and approximate dimensions;\n(h) Any reasonable restriction not contrary to law, morals or public policy regarding the right of any condominium owner to alienate or dispose of his condominium.\nThe enabling or master deed may be amended or revoked upon registration of an instrument executed by the registered owner or owners of the property and consented to by all registered holders of any lien or encumbrance on the land or building or portion thereof. The term \"registered owner\" shall include the registered owners of condominiums in the project. Until registration of a revocation, the provisions of this Act shall continue to apply to such property."}},{"id":"PH-H3741-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Any transfer or conveyance of a unit or an apartment, office or store or other space therein, shall include the transfer or conveyance of the undivided interests in the common areas or, in a proper case, the membership or shareholdings in the condominium corporation: Provided , however , That where the common areas in the condominium project are owned by the owners of separate units as co-owners thereof, no condominium unit therein shall be conveyed or transferred to persons other than Filipino citizens, or corporations at least sixty percent of the capital stock of which belong to Filipino citizens, except in cases of hereditary succession. Where the common areas in a condominium project are held by a corporation, no transfer or conveyance of a unit shall be valid if the concomitant transfer of the appurtenant membership or stockholding in the corporation will cause the alien interest in such corporation to exceed the limits imposed by existing laws."}},{"id":"PH-H3741-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Unless otherwise expressly provided in the enabling or master deed or the declaration of restrictions, the incidents of a condominium grant are as follows:\n(a) The boundary of the unit granted are the interior surfaces of the perimeter walls, floors, ceilings, windows and doors thereof. The following are not part of the unit bearing walls, columns, floors, roofs, foundations and other common structural elements of the building; lobbies, stairways, hallways, and other areas of common use, elevator equipment and shafts, central heating, central refrigeration and central air-conditioning equipment, reservoirs, tanks, pumps and other central services and facilities, pipes, ducts, flues, chutes, conduits, wires and other utility installations, wherever located, except the outlets thereof when located within the unit.\n(b) There shall pass with the unit, as an appurtenance thereof, an exclusive easement for the use of the air space encompassed by the boundaries of the unit as it exists at any particular time and as the unit may lawfully be altered or reconstructed from time to time. Such easement shall be automatically terminated in any air space upon destruction of the unit as to render it untenantable.\n(c) Unless otherwise, provided, the common areas are held in common by the holders of units, in equal shares, one for each unit.\n(d) A non-exclusive easement for ingress, egress and support through the common areas is appurtenant to each unit and the common areas are subject to such easements.\n(e) Each condominium owner shall have the exclusive right to paint, repaint, tile, wax, paper or otherwise refinish and decorate the inner surfaces of the walls, ceilings, floors, windows and doors bounding his own unit.\n(f) Each condominium owner shall have the exclusive right to mortgage, pledge or encumber his condominium and to have the same appraised independently of the other condominiums but any obligation incurred by such condominium owner is personal to him.\n(g) Each condominium owner has also the absolute right to sell or dispose of his condominium unless the master deed contains a requirement that the property be first offered to the condominium owners within a reasonable period of time before the same is offered to outside parties;"}},{"id":"PH-H3741-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Except as provided in the following section, the common areas shall remain undivided, and there shall be no judicial partition thereof."}},{"id":"PH-H3741-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Where several persons own condominiums in a condominium project, an action may be brought by one or more such persons for partition thereof by sale of the entire project, as if the owners of all of the condominiums in such project were co-owners of the entire project in the same proportion as their interests in the common areas: Provided , however , That a partition shall be made only upon a showing:\n(a) That three years after damage or destruction to the project which renders material part thereof unit for its use prior thereto, the project has not been rebuilt or repaired substantially to its state prior to its damage or destruction, or\n(b) That damage or destruction to the project has rendered one-half or more of the units therein untenantable and that condominium owners holding in aggregate more than thirty percent interest in the common areas are opposed to repair or restoration of the project; or\n(c) That the project has been in existence in excess of fifty years, that it is obsolete and uneconomic, and that condominium owners holding in aggregate more than fifty percent interest in the common areas are opposed to repair or restoration or remodeling or modernizing of the project; or\n(d) That the project or a material part thereof has been condemned or expropriated and that the project is no longer viable, or that the condominium owners holding in aggregate more than seventy percent interest in the common areas are opposed to continuation of the condominium regime after expropriation or condemnation of a material portion thereof; or\n(e) That the conditions for such partition by sale set forth in the declaration of restrictions, duly registered in accordance with the terms of this Act, have been met."}},{"id":"PH-H3741-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The owner of a project shall, prior to the conveyance of any condominium therein, register a declaration of restrictions relating to such project, which restrictions shall constitute a lien upon each condominium in the project, and shall insure to and bind all condominium owners in the project. Such liens, unless otherwise provided, may be enforced by any condominium owner in the project or by the management body of such project. The Register of Deeds shall enter and annotate the declaration of restrictions upon the certificate of title covering the land included within the project, if the land is patented or registered under the Land Registration or Cadastral Acts.\nThe declaration of restrictions shall provide for the management of the project by anyone of the following management bodies: a condominium corporation, an association of the condominium owners, a board of governors elected by condominium owners, or a management agent elected by the owners or by the board named in the declaration. It shall also provide for voting majorities quorums, notices, meeting date, and other rules governing such body or bodies.\nSuch declaration of restrictions, among other things, may also provide:\n(a) As to any such management body;\n(1) For the powers thereof, including power to enforce the provisions of the declarations of restrictions;\n(2) For maintenance of insurance policies, insuring condominium owners against loss by fire, casualty, liability, workmen's compensation and other insurable risks, and for bonding of the members of any management body;\n(3) Provisions for maintenance, utility, gardening and other services benefiting the common areas, for the employment of personnel necessary for the operation of the building, and legal, accounting and other professional and technical services;\n(4) For purchase of materials, supplies and the like needed by the common areas;\n(5) For payment of taxes and special assessments which would be a lien upon the entire project or common areas, and for discharge of any lien or encumbrance levied against the entire project or the common areas;\n(6) For reconstruction of any portion or portions of any damage to or destruction of the project;\n(7) The manner for delegation of its powers;\n(8) For entry by its officers and agents into any unit when necessary in connection with the maintenance or construction for which such body is responsible;\n(9) For a power of attorney to the management body to sell the entire project for the benefit of all of the owners thereof when partition of the project may be authorized under Section 8 of this Act, which said power shall be binding upon all of the condominium owners regardless of whether they assume the obligations of the restrictions or not.\n(b) The manner and procedure for amending such restrictions: Provided , That the vote of not less than a majority in interest of the owners is obtained.\n(c) For independent audit of the accounts of the management body;\n(d) For reasonable assessments to meet authorized expenditures, each condominium unit to be assessed separately for its share of such expenses in proportion (unless otherwise provided) to its owners fractional interest in any common areas;\n(e) For the subordination of the liens securing such assessments to other liens either generally or specifically described;\n(f) For conditions, other than those provided for in Sections eight and thirteen of this Act, upon which partition of the project and dissolution of the condominium corporation may be made. Such right to partition or dissolution may be conditioned upon failure of the condominium owners to rebuild within a certain period or upon specified inadequacy of insurance proceeds, or upon specified percentage of damage to the building, or upon a decision of an arbitrator, or upon any other reasonable condition."}},{"id":"PH-H3741-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Whenever the common areas in a condominium project are held by a condominium corporation, such corporation shall constitute the management body of the project. The corporate purposes of such a corporation shall be limited to the holding of the common areas, either in ownership or any other interest in real property recognized by law, to the management of the project, and to such other purposes as may be necessary, incidental or convenient to the accomplishment of said purposes. The articles of incorporation or by-laws of the corporation shall not contain any provision contrary to or inconsistent with the provisions of this Act, the enabling or master deed, or the declaration of restrictions of the project. Membership in a condominium corporation, regardless of whether it is a stock or non-stock corporation, shall not be transferable separately from the condominium unit of which it is an appurtenance. When a member or stockholder ceases to own a unit in the project in which the condominium corporation owns or holds the common areas, he shall automatically cease to be a member or stockholder of the condominium corporation."}},{"id":"PH-H3741-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The term of a condominium corporation shall be co-terminus with the duration of the condominium project, the provisions of the Corporation Law to the contrary notwithstanding."}},{"id":"PH-H3741-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"In case of involuntary dissolution of a condominium corporation for any of the causes provided by law, the common areas owned or held by the corporation shall, by way of liquidation, be transferred pro-indiviso and in proportion to their interest in the corporation to the members or stockholders thereof, subject to the superior rights of the corporation creditors. Such transfer or conveyance shall be deemed to be a full liquidation of the interest of such members or stockholders in the corporation. After such transfer or conveyance, the provisions of this Act governing undivided co-ownership of, or undivided interest in, the common areas in condominium projects shall fully apply."}},{"id":"PH-H3741-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Until the enabling or the master deed of the project in which the condominium corporation owns or holds the common area is revoked, the corporation shall not be voluntarily dissolved through an action for dissolution under Rule 104 of the Rules of Court except upon a showing:\n(a) That three years after damage or destruction to the project in which the corporation owns or holds the common areas, which damage or destruction renders a material part thereof unfit for its use prior thereto, the project has not been rebuilt or repaired substantially to its state prior to its damage or destruction; or\n(b) That damage or destruction to the project has rendered one-half or more of the units therein untenantable and that more than thirty percent of the members of the corporation, if non-stock, or the shareholders representing more than thirty percent of the capital stock entitled to vote, if a stock corporation, are opposed to the repair or reconstruction of the project, or\n(c) That the project has been in existence in excess of fifty years, that it is obsolete and uneconomical, and that more than fifty percent of the members of the corporation, if non-stock, or the stockholders representing more than fifty percent of the capital stock entitled to vote, if a stock corporation, are opposed to the repair or restoration or remodeling or modernizing of the project; or\n(d) That the project or a material part thereof has been condemned or expropriated and that the project is no longer viable, or that the members holding in aggregate more than seventy percent interest in the corporation, if non-stock, or the stockholders representing more than seventy percent of the capital stock entitled to vote, if a stock corporation, are opposed to the continuation of the condominium regime after expropriation or condemnation of a material portion thereof; or\n(e) That the conditions for such a dissolution set forth in the declaration of restrictions of the project in which the corporation owns of holds the common areas, have been met."}},{"id":"PH-H3741-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"The condominium corporation may also be dissolved by the affirmative vote of all the stockholders or members thereof at a general or special meeting duly called for the purpose: Provided , That all the requirements of Section sixty-two of the Corporation Law are complied with."}},{"id":"PH-H3741-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Unless otherwise provided for in the declaration of restrictions upon voluntary dissolution of a condominium corporation in accordance with the provisions of Sections thirteen and fourteen of this Act, the corporation shall be deemed to hold a power of attorney from all the members or stockholders to sell and dispose of their separate interests in the project and liquidation of the corporation shall be effected by a sale of the entire project as if the corporation owned the whole thereof, subject to the rights of the corporate and of individual condominium creditors."}},{"id":"PH-H3741-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"A condominium corporation shall not, during its existence, sell, exchange, lease or otherwise dispose of the common areas owned or held by it in the condominium project unless authorized by the affirmative vote of all the stockholders or members."}},{"id":"PH-H3741-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Any provision of the Corporation Law to the contrary notwithstanding, the by-laws of a condominium corporation shall provide that a stockholder or member shall not be entitled to demand payment of his shares or interest in those cases where such right is granted under the Corporation Law unless he consents to sell his separate interest in the project to the corporation or to any purchaser of the corporation's choice who shall also buy from the corporation the dissenting member or stockholder's interest. In case of disagreement as to price, the procedure set forth in the appropriate provision of the Corporation Law for valuation of shares shall be followed. The corporation shall have two years within which to pay for the shares or furnish a purchaser of its choice from the time of award. All expenses incurred in the liquidation of the interest of the dissenting member or stockholder shall be borne by him."}},{"id":"PH-H3741-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Upon registration of an instrument conveying a condominium, the Register of Deeds shall, upon payment of the proper fees, enter and annotate the conveyance on the certificate of title covering the land included within the project and the transferee shall be entitled to the issuance of a \"condominium owner's\" copy of the pertinent portion of such certificate of title. Said \"condominium owner's\" copy need not reproduce the ownership status or series of transactions in force or annotated with respect to other condominiums in the project. A copy of the description of the land, a brief description of the condominium conveyed, name and personal circumstances of the condominium owner would be sufficient for purposes of the \"condominium owner's\" copy of the certificate of title. No conveyance of condominiums or part thereof, subsequent to the original conveyance thereof from the owner of the project, shall be registered unless accompanied by a certificate of the management body of the project that such conveyance is in accordance with the provisions of the declaration of restrictions of such project.\nIn cases of condominium projects registered under the provisions of the Spanish Mortgage Law or Act 3344, as amended, the registration of the deed of conveyance of a condominium shall be sufficient if the Register of Deeds shall keep the original or signed copy thereof, together with the certificate of the management body of the project, and return a copy of the deed of conveyance to the condominium owner duly acknowledge and stamped by the Register of Deeds in the same manner as in the case of registration of conveyances of real property under said laws."}},{"id":"PH-H3741-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Where the enabling or master deed provides that the land included within a condominium project are to be owned in common by the condominium owners therein, the Register of Deeds may, at the request of all the condominium owners and upon surrender of all their \"condominium owner's\" copies, cancel the certificates of title of the property and issue a new one in the name of said condominium owners as pro-indiviso co-owners thereof."}},{"id":"PH-H3741-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"An assessment upon any condominium made in accordance with a duly registered declaration of restrictions shall be an obligation of the owner thereof at the time the assessment is made. The amount of any such assessment plus any other charges thereon, such as interest, costs (including attorney's fees) and penalties, as such may be provided for in the declaration of restrictions, shall be and become a lien upon the condominium assessed when the management body causes a notice of assessment to be registered with the Register of Deeds of the city or province where such condominium project is located. The notice shall state the amount of such assessment and such other charges thereon a may be authorized by the declaration of restrictions, a description of the condominium, unit against which same has been assessed, and the name of the registered owner thereof. Such notice shall be signed by an authorized representative of the management body or as otherwise provided in the declaration of restrictions. Upon payment of said assessment and charges or other satisfaction thereof, the management body shall cause to be registered a release of the lien.\nSuch lien shall be superior to all other liens registered subsequent to the registration of said notice of assessment except real property tax liens and except that the declaration of restrictions may provide for the subordination thereof to any other liens and encumbrances.\nSuch liens may be enforced in the same manner provided for by law for the judicial or extra-judicial foreclosure of mortgages of real property. Unless otherwise provided for in the declaration of restrictions, the management body shall have power to bid at foreclosure sale. The condominium owner shall have the same right of redemption as in cases of judicial or extra-judicial foreclosure of mortgages."}},{"id":"PH-H3741-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"No labor performed or services or materials furnished with the consent of or at the request of a condominium owner or his agent or his contractor or subcontractor, shall be the basis of a lien against the condominium of any other condominium owner, unless such other owners have expressly consented to or requested the performance of such labor or furnishing of such materials or services. Such express consent shall be deemed to have been given by the owner of any condominium in the case of emergency repairs of his condominium unit. Labor performed or services or materials furnished for the common areas, if duly authorized by the management body provided for in a declaration of restrictions governing the property, shall be deemed to be performed or furnished with the express consent of each condominium owner. The owner of any condominium may remove his condominium from a lien against two or more condominiums or any part thereof by payment to the holder of the lien of the fraction of the total sum secured by such lien which is attributable to his condominium unit."}},{"id":"PH-H3741-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Unless otherwise provided for by the declaration of restrictions, the management body, provided for herein, may acquire and hold, for the benefit of the condominium owners, tangible and intangible personal property and may dispose of the same by sale or otherwise; and the beneficial interest in such personal property shall be owned by the condominium owners in the same proportion as their respective interests in the common areas. A transfer of a condominium shall transfer to the transferee ownership of the transferor's beneficial interest in such personal property."}},{"id":"PH-H3741-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Where, in an action for partition of a condominium project or for the dissolution of condominium corporation on the ground that the project or a material part thereof has been condemned or expropriated, the Court finds that the conditions provided for in this Act or in the declaration of restrictions have not been met, the Court may decree a reorganization of the project, declaring which portion or portions of the project shall continue as a condominium project, the owners thereof, and the respective rights of said remaining owners and the just compensation, if any, that a condominium owner may be entitled to due to deprivation of his property. Upon receipt of a copy of the decree, the Register of Deeds shall enter and annotate the same on the pertinent certificate of title."}},{"id":"PH-H3741-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"Any deed, declaration or plan for a condominium project shall be liberally construed to facilitate the operation of the project, and its provisions shall be presumed to be independent and severable."}},{"id":"PH-H3741-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"Whenever real property has been divided into condominiums, each condominium separately owned shall be separately assessed, for purposes of real property taxation and other tax purposes to the owners thereof and the tax on each such condominium shall constitute a lien solely thereon."}},{"id":"PH-H3741-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"All Acts or parts of Acts in conflict or inconsistent with this Act are hereby amended insofar as condominium and its incidents are concerned."}},{"id":"PH-H3741-A27","no":27,"noLabel":{"en":"Section 27."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966"}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Define Condominium, Establish Requirements for its Creation, and Govern its Incidents","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3742"] = {"id":"PH-H3742","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4727_1966.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第1566号共和国法（即《规定在外国购置供菲律宾政府外交与领事机构及其他机关使用的建筑与场地，并为政府利益出售或出租该等建筑、场地及类似财产》）第7条的法案","en":"An Act Amending Section Seven of Republic Act Numbered One Thousand Five Hundred Sixty-Six, Entitled \"An Act Providing for the Acquisition of Buildings and Grounds in Foreign Countries for the Use of Diplomatic and Consular Establishments and Other Agencies of the Philippine Government and for the Sale or Lease in the Government Interest of Such Buildings and Grounds and Like Properties\"","orig":"An Act Amending Section Seven of Republic Act Numbered One Thousand Five Hundred Sixty-Six, Entitled \"An Act Providing for the Acquisition of Buildings and Grounds in Foreign Countries for the Use of Diplomatic and Consular Establishments and Other Agencies of the Philippine Government and for the Sale or Lease in the Government Interest of Such Buildings and Grounds and Like Properties\"","vi":"Đạo luật sửa đổi Điều 7 của Đạo luật Cộng hòa số 1566","th":"พระราชบัญญัติแก้ไขเพิ่มเติมมาตรา 7 แห่งพระราชบัญญัติแห่งสาธารณรัฐที่ 1566","id":"Undang-Undang mengubah Pasal 7 Undang-Undang Republik No. 1566","ms":"Akta meminda Seksyen 7 Akta Republik No. 1566"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4727","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4727_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3742-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section seven of Republic Act Numbered One thousand five hundred sixty-six is hereby amended to read as follows:\n\"Sec. 7. The Government service insurance system and the social security system are hereby authorized to extend to the national government loans, not exceeding ten million pesos for a term of not exceeding ten years at such rates of interest and under such terms and conditions as the board of trustees of government service insurance system and of the social security system may require, which loan, together with the proceeds of the sale of properties of the department of foreign affairs abroad, are hereby made available to the department for the acquisition by purchase or otherwise or by construction of sites and buildings and for altering and furnishing such buildings for the use of the diplomatic and consular establishments and other agencies abroad of the Government of the Philippines in accordance with the provisions of section one of this act. Such sums, as may be necessary for the repayment of the loan, including the interest thereon, are hereby automatically appropriated annually out of the receipts from fees for certification of consular invoices. The Secretary of Foreign Affairs shall report annually all such transactions as well as any transaction made pursuant to Section five to the Congress with the budget estimates of the Department of Foreign Affairs."}},{"id":"PH-H3742-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Section Seven of Republic Act Numbered One Thousand Five Hundred Sixty-Six, Entitled \"An Act Providing for the Acquisition of Buildings and Grounds in Foreign Countries for the Use of Diplomatic and Consular Establishments and Other Agencies of the Philippine Government and for the Sale or Lease in the Government Interest of Such Buildings and Grounds and Like Properties\"","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3743"] = {"id":"PH-H3743","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4728_1966.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"对《 司法法 1948》的修改","en":"The Judiciary Act of 1948","orig":"An Act to Amend Sections Sixty-One and Sixty-Two of Republic Act Numbered Two Hundred Ninety-Six, as Amended, Otherwise Known as \"The Judiciary Act of 1948\" and for Other Purposes","vi":"Đạo luật Tư pháp năm 1948","th":"พระราชบัญญัติตุลาการ ค.ศ. 1948","id":"Undang-Undang Kehakiman Tahun 1948","ms":"Akta Kehakiman 1948"},"level":"law","status":"active","topics":["judiciary"],"docNumber":"Republic Act No. 4728","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4728_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3743-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Sections sixty-one and sixty-two of Republic Act Numbered Two hundred ninety-six, as amended, are hereby further amended to read as follows:\n\"Sec. 61. Authority of Court of First Instance of the Sixth Judicial District over administration of its own affairs.— The Court of First Instance of the Sixth Judicial District shall have the administrative control of all matters affecting the internal operations of the twenty-five branches of the court. This administrative control shall be exercised by the court itself through the clerk of court, or in his absence or incapacity, the assistant clerk of court. In administrative matters, the clerk of court shall be under the direction of the court itself. The personnel of the office of the clerk of court of the Court of First Instance of the Sixth Judicial District shall consist of the clerk of court, the assistant clerk of court, the twenty-five branch clerks of court, the special clerk of court and such deputy clerks, officers and employees as may be provided by law. The subordinate employees of said office shall be appointed by the Secretary of Justice upon recommendation of the Chief of the Office, the clerk of Court. The said clerk of Court and all the employees of his office shall belong, for all purposes, to the Court of First Instance of the Sixth Judicial District.\"\n\"Sec. 62. Appointment and qualifications of clerks.— The clerk of Court, the assistant clerk of Court, the twenty-five branch clerks of Court and the special clerk of Court of the Sixth Judicial District shall be appointed by the President of the Philippines upon recommendation of the Secretary of Justice, with the consent of the Commission on Appointments. No person shall be eligible for appointment to any of these positions unless he is duly authorized to practice law in the Philippines: Provided, However, That this requirement shall not affect persons who, at the date of the approval of this Act, are holding the position of clerk of court, assistant clerk of court, branch clerk of court or deputy clerk of court assigned to a branch and performing the work of a branch clerk of court, or special clerk of court: Provided, further, That the present clerk of court, the assistant clerk of court, the twenty-five branch clerks of court assigned to the twenty-five branches thereof, and the special clerk of court shall continue as such in office without the necessity of reappointment. The clerk of court shall receive an annual salary of thirteen thousand two hundred pesos, the assistant clerk of court shall receive an annual salary of ten thousand eight hundred pesos, the branch clerks of court and the special clerk of court shall each receive an annual salary of nine thousand six hundred pesos.\""}},{"id":"PH-H3743-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53"};
  FT["PH-H3744"] = {"id":"PH-H3744","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4729_1966.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"规制买卖","en":"An Act to Regulate the Sale, Dispensation, and/or Distribution of Contraceptive Drugs and Devices","orig":"An Act to Regulate the Sale, Dispensation, and/or Distribution of Contraceptive Drugs and Devices"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 4729","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4729_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3744-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"It shall be unlawful for any person, partnership, or corporation, to sell, dispense or otherwise distribute whether for or without consideration, any contraceptive drug or device, unless such sale, dispensation or distribution is by a duly licensed drug store or pharmaceutical company and with the prescription of a qualified medical practitioner."}},{"id":"PH-H3744-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"For the purpose of this Act:\n(a) \"Contraceptive drug\" is any medicine, drug, chemical, or portion which is used exclusively for the purpose of preventing fertilization of the female ovum: and\n(b) \"Contraceptive device\" is any instrument, device, material, or agent introduced into the female reproductive system for the primary purpose of preventing conception."}},{"id":"PH-H3744-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Any person, partnership, or corporation, violating the provisions of this Act shall be punished with a fine of not more than five hundred pesos or an imprisonment of not less than six months or more than one year or both in the discretion of the Court.\nThis Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53"};
  FT["PH-H3745"] = {"id":"PH-H3745","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4730_1966.html","fetchedAt":"2026-10-06","articleCount":20,"structureMode":"ARTICLE","title":{"zh":"修订第 3588 号共和国法，规定选举登记官核准的选民永久登记的验证程序并规定登记委员会，以及为其他目的法案","en":"An Act to Amend Republic Act Numbered Three Thousand Five Hundred Eighty-Eight, Providing for a Procedure for Validating the Permanent Registration of Voters Approved by Election Registrars and to Provide for Registration Boards, and for Other Purposes","orig":"An Act to Amend Republic Act Numbered Three Thousand Five Hundred Eighty-Eight, Providing for a Procedure for Validating the Permanent Registration of Voters Approved by Election Registrars and to Provide for Registration Boards, and for Other Purposes","vi":"Đạo luật sửa đổi Đạo luật Cộng hòa số 3588, và cho các mục đích khác","th":"พระราชบัญญัติแก้ไขเพิ่มเติมพระราชบัญญัติแห่งสาธารณรัฐที่ 3588 และเพื่อวัตถุประสงค์อื่น","id":"Undang-Undang mengubah Undang-Undang Republik No. 3588, dan untuk tujuan lain","ms":"Akta meminda Akta Republik No. 3588, dan untuk tujuan lain"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 4730","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 20 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4730_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3745-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section 2 of Republic Act Numbered Three thousand five hundred eighty-eight is hereby amended to read as follows:\n\"Sec. 2. Who may be registered in the Permanent List of Voters. All persons possessing all the qualifications prescribed for a voter and none of the disqualifications have the right and duty to be registered in the permanent list of voters of the city, municipality or municipal district wherein they are domiciled and to be included in the precinct book of voters of their corresponding precinct.\n\"Any person who may not have on the date of his registration any of the qualifications required may also be registered upon proof that on the date of the election he shall have such qualification.\""}},{"id":"PH-H3745-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section 3 of the same Act is hereby amended to read as follows:\n\"Sec. 3. Election Registrar. There shall be in each city, municipality and municipal district at least one election registrar and a clerk appointed by the Commission on Elections. Every election registrar shall be appointed to a specific city, municipality or municipal district; and once appointed may not be transferred or removed to another city, municipality or municipal district without cause or his consent. The salaries for the positions of election registrar and clerk in the city, municipality and municipal district shall be at such rate as may be determined by the position classification to be made by the Commission on Elections: Provided , however , That in the city, municipality and municipal district having four thousand registered voters or less, the Commission on Elections may at its discretion appoint an election registrar, attach it to another political subdivision for purposes of registration, or appoint the city, municipal or municipal district treasurer as election register with additional compensation to be fixed by the Commission on Elections but not to exceed fifty per cent of his salary as treasurer.\n\"The city, municipal or municipal district council, as the case may be, shall provide a place for the office of the registrar.\""}},{"id":"PH-H3745-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The same Act is further amended by inserting the following new sections between Sections 4 and 5, to be numbered as Sections 5, 6 and 7, respectively:\n\"Sec. 5. Election Registration Board. There shall be in each city, municipality and municipal district as many election registration boards as there are election registrars appointed therein, each such election registration board to be composed of the election registrar as chairman and two members to be appointed by the Commission on Elections upon proposal by the two political parties which polled the largest and the next largest number of votes in the next preceding presidential election, and shall hold office until relieved by the Commission on Elections for cause or upon the petition of the authorized representative of the party upon whose nomination the appointment was made.\n\"The board shall meet every Monday during regular office hours, to discharge the functions herein conferred upon it: Provided , That the Commission on Elections may require any particular board or boards to meet more or less often as the exigencies of its duties may require.\n\"Sec. 6. Qualifications of Election Registration Board Members. No person shall be appointed or act as member of an election registration board unless he is a qualified elector, of good reputation, has not been convicted of any election offense or of any other crime punishable by more than six months of imprisonment or has no complaint or information pending against him for any election offense.\n\"Sec. 7. Ineligibility of Public Officers and Employees. Except for notaries public, no person holding a public office or position or who is a candidate for an elective office may be appointed member of the election registration board."}},{"id":"PH-H3745-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section 5 of the same Act is hereby renumbered as Section 8 and amended to read as follows:\n\"Sec. 8. Registration of Voters. On any date, within sixty days after having acquired the qualifications of a voter, but not later than sixty days before the day of any regular election and not later than thirty days before the day of any special election, a qualified voter shall personally appear before the election registrar of his city, municipality or municipal district wherein he is domiciled and file with him a sworn application for registration in triplicate.\n\"To facilitate filing of applications for registration the election registrar may hold office in any district, barrio or sitio within his jurisdiction, without any traveling allowance, subject to the rules and regulations promulgated by the Commission on Elections. Any person who fails to register within sixty days after having acquired the qualifications of a voter or is registered after said period shall not be qualified to vote in the election immediately following his registration. For purposes of the nineteen hundred sixty-seven elections, however, any person who is a qualified voter may register any time before the sixty-day period preceding the date of said election.\""}},{"id":"PH-H3745-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Section 6 of the same Act is hereby renumbered as Section 9."}},{"id":"PH-H3745-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Section 7 of the same Act is hereby renumbered as Section 10 and amended to read as follows:\n\"Sec. 10. Approval or disapproval of application and petition for inclusion. Upon receipt of the sworn application for registration, the election registrar shall set it for hearing, notice of which shall be posted in the municipal building for at least three days before the hearing. On the date of the hearing, the election registrar shall receive whatever evidence that may be submitted for or against the application. He shall submit the application and the evidence to the election registration board at its next meeting; and the board shall, by majority vote, act upon the application; and should it fail to do so within two consecutive meetings, including the meeting at which the application has been submitted to it, the application shall be deemed to have been approved. Upon approval, the election registrar shall forthwith issue the corresponding identification card to the registered voter.\n\"If the election registration board disapproves the application, the applicant shall be furnished with a certificate of disapproval wherein the ground for the disapproval shall be stated. The applicant may at any time except forty-five days before a regular election or twenty-five days before a special election file with the Justice of the Peace Court or the Court of First Instance of the province a petition for his inclusion, which shall be decided within fifteen days after filing. If the decision is for the inclusion of a voter in the permanent list of voters, the election registrar shall activate the application for registration which has been previously denied, by placing said application in the corresponding precinct book of voters wherein the order of inclusion by the court shall be entered and shall mail or deliver to the voter his identification card. If the decision is adverse, the right of appeal as heretofore granted by existing laws shall be available.\""}},{"id":"PH-H3745-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Section 8 of the same Act is hereby renumbered as Section 11 and Section 9 renumbered as Section 12 and amended to read as follows:\n\"Sec. 12. Publication of application for registration. Within two days from approval or disapproval of any application for registration, the election registrar shall post a notice in the municipal building giving the name and address of the applicant and the date of the application and the action taken on the application and shall serve a copy thereof by registered special delivery mail or by personal delivery on the heads or representatives of national political parties in the city, municipality or municipal district.\""}},{"id":"PH-H3745-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Section 10 of the same Act is also renumbered as Section 13 and amended to read as follows:\n\"Sec. 13. Preparation of precinct book of voters. The election registration board shall prepare the precinct book of voters of each precinct which shall consist of all the original copies of the approved application of voters for registration arranged alphabetically belonging to the same precinct, in a suitable binder or device.\n\"Each precinct book of voters, before delivery to the board of inspectors shall be duly sealed and certified by the election registration board that the approved applications contained therein, stating the exact number, are complete for the precinct. The election registrar shall deliver this precinct book of voters to the chairman of the board of inspectors at the same time the board takes delivery of its official ballots, for the use of the board during the voting and which shall be returned to the election registrar for his custody at the same time the statement of election returns are delivered. Thirty days before a regular election and ten days before a special election, all precinct book of voters shall be sealed and shall not be available for examination by the public. All candidates and national political parties have the right, personally or by duly appointed watchers, and all members of the board of inspectors have the duty, to be present at the sealing of the precinct books and to verify their contents before they are closed and sealed.\n\"Should it be determined during such verification, that a precinct book contains fictitious applications, or applications that have not been approved, or have been canceled, any candidate, representative of a national political party, member of the board of inspectors or elector may, within ten days after the books have been closed and sealed, apply to the Court of First Instance for an order to exclude the same, and the matter shall proceed as provided in Section 123 of the Revised Election Code. It shall be prima facie evidence that the applications sough to be excluded are fictitious or have not been approved if they are not included in anyone of the notices or lists required by sections ten, twelve and twenty-three of Republic Act Numbered Three thousand five hundred eighty-eight, as renumbered by this amendatory Act.\n\"Should it be determined during the process of verification before sealing, that the precinct book fails to include any voter's application that has been duly approved under section ten of Republic Act Numbered Three thousand five hundred eighty-eight as renumbered and has not been properly canceled under sections eighteen, nineteen and twenty hereof, as renumbered or transferred to another precinct under section twenty-one hereof, the elector concerned, or any candidate, or representative of any political party or member of the board of inspectors may apply to the court at any time for an order directing that his application for registration be included in the book. He shall attach to his motion a certified copy of the voter's identification card or of the notice of approval of his voter's application or of the notice of action taken on his application required by section twelve of Republic Act No. Three thousand five hundred eighty-eight, as renumbered by this amendatory Act together with proof that he has applied, without success, to the election registrar and that he has served a copy thereof on the election registrar.\n\"After the precinct books have been closed and sealed, only those voters whose applications are included therein shall be allowed to vote, except as may be ordered by the competent court.\n\"The proceeding provided for in this Act for inclusion or exclusion of voters shall be in addition to and shall not affect any action for the criminal liability of any person responsible for the violation of the provisions of this Act.\""}},{"id":"PH-H3745-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Sections 11, 12 and 13 of the same Act are also renumbered as Sections 14, 15 and 16, respectively."}},{"id":"PH-H3745-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Section 14 of the same Act is hereby renumbered as Section 17 and the first paragraph thereof also amended to read as follows:\n\"Sec. 17. Voter's Identification. The voters identification card shall serve and be considered as document for the identification of each registered voter: Provided , however , That no voter shall required to present his identification card on election day unless his identity is challenged as provided in Section 134 of the Revised Election Code And provided, further, That his failure or inability to produce his identification card upon being challenged, shall not preclude him from voting if his identity be shown from the photograph or fingerprints in his approved application in the precinct book or if he is identified under oath by a member of the board of inspectors or by a duly accredited watcher.\""}},{"id":"PH-H3745-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Section 15 of the same Act is hereby renumbered as Section 18 and amended as follows:\n\"Sec. 18. Petition for exclusion of voters and decision thereon. Any elector, representative of a political party or the election registrar of the city, municipality or municipal district may at any time except forty-five days before a regular election and twenty-five days before a special election file with the Justice of the Peace Court or the Court of First Instance of the province a sworn petition for exclusive from the permanent list of voters of any voter on the ground that he is disqualified, disabled or illegally registered, which petition shall be decided within fifteen days after filing. The right of appeal as provided for in existing laws shall be available to any interested party.\n\"The election registration board upon receipt of the final decision ordering exclusion of a voter shall remove his application from the corresponding precinct book of voters and place said application in the inactive file, wherein the order of exclusion by the Court shall be entered.\n\"The election registration board shall submit monthly reports or as often as the Commission on Elections may order, of all cancellations made by it pursuant to court orders, so the corresponding action can be taken on the copies of the application in the Provincial Central File and the Commission on Elections."}},{"id":"PH-H3745-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Section 16 of the same Act is hereby renumbered as section 19 and amended to read as follows:\n\"Sec. 19. Cancellation due to death, conviction, and failure to vote in two successive preceding elections. The election registration board shall remove the voter's application for registration from the corresponding precinct book of voters of the following after entering therein the cause for cancellation and shall place them in the inactive file:\n\"(a) Those who have since died as certified to at the end of each months by the local civil registrar.\n\"(b) Those who have since been sentenced by final judgment to suffer an imprisonment of not less than one year or found guilty of having violated their allegiance to the Republic of the Philippines as certified to at the end of each month by the clerk of court, the clerk of the municipal court in chartered cities and the justice of the peace.\n\"(c) Those who did not vote in the two successive preceding regular elections as shown by the voting records of each voter after holding of an election.\n\"The election registrar in behalf of the election registration board shall notify by mail or by personal delivery the registered voter of his cancellation and the ground thereof and require the surrender of his voter's identification card. In cases of death, all notices and requirements shall be directed to the voter's next of kin.\n\"The names canceled shall be published on the bulletin board immediately stating the reason for the cancellation and shall be reported to the Commission on Elections and the Provincial Central File together with copies of the certified statements of the local civil registrar, the clerk of court, the clerk of the municipal court of chartered cities and the justice of the peace. The Provincial Central File and the Commission on Elections shall accordingly remove the application for registration of the voters and file them in the inactive file after entering in their respective application the cause for the cancellation of their registration.\""}},{"id":"PH-H3745-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Section 17 of the same Act is hereby renumbered as Section 20 and amended to read follows:\n\"Sec. 20. Cancellation of previous registration. Any registered voter who, after approval of his application for registration, has suffered any of the disqualifications set out in section ninety-nine of the Revised Election Code may request for the cancellation of his registration by personally filing a sworn application for said cancellation, setting forth the ground or grounds therefor, with the election registration board which shall proceed to verify the truth thereof and, once established, shall cancel the voter's registration and issue the certificate of cancellation to the voter.\n\"Any registered voter who has transferred and acquired a new domicile may request for the cancellation of his previous registration as stated in the first paragraph hereof or by sending by registered mail a sworn application for cancellation of registration in duplicate giving his old and new addresses and enclosing his voter's identification card, or by personally filing said sworn application with the election registration board of his new domicile, which upon receipt thereof shall transmit the same, together with the voter's identification card, to the election registration board of the voter's old domicile.\n\"The election registration board concerned shall upon receipt of the application for cancellation of registration remove his application for registration from the corresponding book of voters, which shall be placed in the inactive file, and issue the certificate of cancellation to the voter by registered mail or personally. The election registration board shall enter the corresponding notations in the application for registration of said request for cancellation.\n\"The election registrar shall preserve all applications for cancellations and shall report all cancellations made by him under this Section to the Commission on Elections and to the Provincial Central File for their corresponding action. The names of voters canceled shall be posted in the bulletin board for thirty days.\""}},{"id":"PH-H3745-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Section 18 of the same Act is hereby renumbered as Section 21 and amended to read as follows:\n\"Sec. 21. Change of Address of Voter in the Same City, Municipality or Municipal District. Any voter who has changed his address in the same city, municipality or municipal district where he is registered shall immediately notify his election registration board not later than forty-five days before any regular election day and thirty days before a special election day. If the change of address involves a change of precinct, the election registration board shall transfer his application of registration from the precinct book of voters of his old precinct to his new precinct. All changes of address shall be reported to the Commission on Elections and the Provincial Central File by the election registrar and he shall immediately notify the voter that his change of address has been noted in his application of registration, together with his precinct number, if new.\""}},{"id":"PH-H3745-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Section 19 of the same Act is hereby renumbered as Section 22 and amended to read as follows:\n\"Sec. 22. Adjustment of the Precinct Book of Voters in Case of Division or Merger of Precinct. When a precinct is divided into two, or more precincts or certain precincts are merged, the election registration board shall accordingly transfer the application for registration of the voters included in the precinct book of voters of the precinct or precincts affected to the corresponding precinct book of voters of the resulting new or adjusted precinct. All adjustments shall be reported to the Commission on Elections and the Provincial Central File for their corresponding action. Voters affected by the adjustment of precincts shall be notified by mail of their new precinct resulting from the adjustment.\""}},{"id":"PH-H3745-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Section 20 of the same Act is hereby renumbered as Section 23 and amended to read as follows:\n\"Sec. 23. Publication of the Precinct List of Voters. For the purpose of public information and reference only, thirty days before the day of a regular election and ten days before the day of special election, the election registration board shall furnish the candidates heads of the national political parties in the city, municipality or municipal district, the Provincial Central file and the Commission on Elections a copy of the certified list of the names and addresses of all the voters in each precinct of the city, municipality or municipal district. Changes in this list shall be distributed in the same manner as supplementary lists.\n\"The election registration board shall also furnish two certified copies of said precinct list to the poll clerk for posting in the polling place and for the use of the board of inspectors on election day. In the event that the precinct book of voters is lost or destroyed or otherwise unavailable, and there is no time to reconstitute the same by using the provincial or national central files, the two certified copies of the precinct list may be used in lieu of the precinct book of voters.\n\"The Commission on Elections shall promulgate rules and regulations governing such cases as well as procedures for the reconstitution of the lost precinct book of voters.\""}},{"id":"PH-H3745-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Sections 21, 22, 23 and 24 of the same Act are hereby renumbered as Sections 24, 25, 26 and 27, respectively."}},{"id":"PH-H3745-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"The same Act is also amended by inserting new sections between Sections 24 and 25 of the same Act to be renumbered as Sections 28, 29, 30 and 31 and which shall be read as follows:\n\"Sec. 28. Applications subject to validation. All applications for registration as voter approved by the election registrars under this Act, as amended, shall be validated following the procedure outlined hereinbelow, provided that, where the applicant personally accomplished only the original of the application, or where the photograph of the applicant is not attached to the application as provided for in sections eight and nine as now renumbered shall be deemed valid only if the following conditions are complied with: (1) that the information record of the voter entered in the duplicate and triplicate copies of the application tallies in all respects with the entries in the original application; and (2) that the photograph of the voter is affixed to the three copies of the application and the identification card not later than sixty days before the election immediately following the approval of this Act.\n\"Sec. 29. Procedure for validation. Within three months from the approval of this Act, the election registrar shall prepare a list of names and addresses of all voters whose applications for registration were approved by the election registrars as of September 10, 1965, in each precinct of the city, municipality or municipal district and thereafter he shall post the same in his office in the city, municipal or municipal district hall, and in three conspicuous public places in the city, municipality or municipal district for a period of three months. The election registrar shall submit periodically at each meeting of the election registration board herein created the applications of voters so listed and published as stated above and the board shall pass upon the applications submitted to it by the election registrar. Unanimous decision of the board to confirm validates the registration of voters. In case a member dissents, the voter affected shall be summoned to appear before the board. After hearing the voter the board shall decide by majority vote whether to confirm or not his registration.\n\"Without prejudice to the provisions of section eighteen as renumbered in this Act, any elector of the city, municipality or municipal district may, not later than six months from the approval hereof, object to the inclusion of a voter with a defective application in the permanent list of voters. The objection shall be under oath; shall state the ground or grounds therefor; and the election registrar shall attach the objection to the application together with proof of notice of the date of hearing to the challenger and the voter.\n\"All above-described applications not objected to within six months from the approval of this amendment shall be considered to have been properly filed and approved upon certification by the election registration board in compliance with the conditions mentioned in Section 28 hereof, and for this purpose, the election registrar, in behalf of the registration board, is authorized to make such corrections in the entries in the duplicate and triplicate copies of the application to make them conform with the original prepared by the applicant.\n\"Sec. 30. Power of the Commission on Elections to promulgate regulations. The Commission on Elections shall issue rules and regulations implementing the provisions hereof.\n\"Sec. 31. Penal Provisions. Notwithstanding the provisions of Sections 183 to 188 of the Revised Election Code, it shall be a serious election offense for any person \"(a) To deliver, hand over, entrust, or give directly or indirectly, his voter's identification card to another in consideration of money or other benefit or promise therefor; or take or accept such voter's identification card, directly or indirectly, by giving or causing the giving of money or other benefit or making or causing the making of a promise therefor;\n\"(b) To ask, demand, take, accept or possess, directly or indirectly, the voters identification card to another, in order to induce the latter to vote or withhold his vote, or to vote for or against any candidate or proposition in an election or plebiscite; and it shall be presumed prima facie that the asking, demanding, taking, accepting, or possessing is with such intent, if done within the period beginning thirty days before election day and ending thirty days after election day, unless the person who asks, demands, takes, accepts or possesses the voter's identification card of another and the latter are both members of the same family, living in the same house;\n\"(c) To falsify or forge a voter's identification card or alter it without authority, or knowingly to possess such falsified, forged or unlawfully altered voter's identification card;\n\"(d) To make any false or untruthful statement in a voter's application for registration:\n\"(e) To delay, hinder or obstruct any other person from registering as a voter or from taking any of the steps leading thereto;\n\"(f) To place, insert or otherwise include, as approved applications for registration, in the precinct book of voters or in the provincial or national central files of registered voters, the application of any fictitious voter or any application that has not been approved; or to remove, abstract or otherwise take out of the precinct book of voters or the provincial or national central files of registered voters, any voter's application duly approved, except upon lawful order of a competent court or after proper cancellation as provided in Sections 16 to 20 and 24 of this Act: Provided , That in addition to the acts and omissions enumerated above, it shall also be a serious election offense for an election registrar or any member of the election registration board or any person acting in their behalf:\n\"(i) To fail, without cause, to post or to give any of the notices or to make any of the reports required by this act as amended;\n\"(ii) To approve knowingly the application of a person who does not possess all the qualifications or possesses any of the disqualifications prescribed by law for voters; or to disapprove knowingly the application of a person who does possess all such qualifications and none of such disqualifications;\n\"(iii) To issue or cause the issuance of a voter's identification card or to cancel or cause the cancellation thereof in violation of the provisions of this Act;\n\"(iv) To take or carry outside of the city or municipality of which he is a registrar, any registration form already issued to said city or municipality, except as otherwise provided for in this Act or when directed by express order of the court, or of the Commission on Elections;\n\"(v) To render, make or submit any false or untruthful report on the progress of registration in his municipality or any precinct thereof."}},{"id":"PH-H3745-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Sections 25 and 26 of the same Act are hereby renumbered as Sections 32 and 33, respectively."}},{"id":"PH-H3745-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966"}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Republic Act Numbered Three Thousand Five Hundred Eighty-Eight, Providing for a Procedure for Validating the Permanent Registration of Voters Approved by Election Registrars and to Provide for Registration Boards, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3746"] = {"id":"PH-H3746","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4731_1966.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"在西明多洛省San Jose市镇设立国立农业与工业学校并授权为此拨款的法案","en":"An Act Providing for the Establishment of a National Agricultural and Industrial School in the Municipality of San Jose, Province of Occidental Mindoro, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Providing for the Establishment of a National Agricultural and Industrial School in the Municipality of San Jose, Province of Occidental Mindoro, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["education","environment"],"docNumber":"Republic Act No. 4731","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4731_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3746-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Director of Vocational Education, a national agricultural and industrial school in the Municipality of San Jose, Province of Occidental Mindoro, at a site to be selected by said Director and to be known as the National Agricultural and Industrial School of Southern Mindoro."}},{"id":"PH-H3746-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Upon the recommendation of the Director of Vocational Education, the President of the Philippines shall set aside and reserve such portions of the public lands located within the Municipality of San Jose, Province of Occidental Mindoro, as may be necessary and convenient for the establishment of the school and farm sites."}},{"id":"PH-H3746-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of one hundred and fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of the said school during the fiscal year nineteen hundred sixty-seven. Thereafter, the necessary sum for the operation and maintenance of said school shall be included in the annual General Appropriations Act."}},{"id":"PH-H3746-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Establishment of a National Agricultural and Industrial School in the Municipality of San Jose, Province of Occidental Mindoro, and Authorizing the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3747"] = {"id":"PH-H3747","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4732_1966.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"在西明多洛省设立Calintaan市镇的法案","en":"An Act Creating the Municipality of Calintaan in the Province of Mindoro Occidental","orig":"An Act Creating the Municipality of Calintaan in the Province of Mindoro Occidental","vi":"Đạo luật thành lập Thị trấn Calintaan tại Tỉnh Mindoro Occidental","th":"พระราชบัญญัติจัดตั้งเทศบาล Calintaan ในจังหวัด Mindoro Occidental","id":"Undang-Undang membentuk Kotamadya Calintaan di Provinsi Mindoro Occidental","ms":"Akta mewujudkan Perbandaran Calintaan di Wilayah Mindoro Occidental"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4732","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4732_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3747-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Barrios Concepcion, Iriron, Poypoy, Malpalon, Dagupan, Tanyag and Calintaan in the Municipality of Sablayan, Province of Mindoro Occidental, are separated from said municipality and are constituted into a distinct and independent municipality, to be known as the Municipality of Calintaan, same province. The seat of government shall be located at the present site of the barrio of Calintaan."}},{"id":"PH-H3747-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The first mayor, vice-mayor and councilors of the new municipality shall be elected in the next general election for local officials and shall have qualified."}},{"id":"PH-H3747-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the Municipality of Calintaan in the Province of Mindoro Occidental","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3748"] = {"id":"PH-H3748","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4763_1966.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将高山省帕拉卡莱斯市镇的基灵村划归同省波蒂亚市镇的法案","en":"An Act Transferring Barrio Kiling in the Municipality of Paracales, Mountain Province, to the Municipality of Potia, Same Province","orig":"An Act Transferring Barrio Kiling in the Municipality of Paracales, Mountain Province, to the Municipality of Potia, Same Province"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4763","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4763_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3748-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Barrio Kiling in the Municipality of Paracales, Mountain Province, is hereby transferred to the Municipality of Potia, same province."}},{"id":"PH-H3748-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Transferring Barrio Kiling in the Municipality of Paracales, Mountain Province, to the Municipality of Potia, Same Province","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3749"] = {"id":"PH-H3749","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4764_1966.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"在塔克洛班市设立总医院，名称为议长Daniel Z. Romualdez纪念市医院，并授权为此拨款的法案","en":"An Act Providing for the Establishment of a General Hospital at Tacloban City, to be Known as Speaker Daniel Z. Romualdez Memorial City Hospital, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Providing for the Establishment of a General Hospital at Tacloban City, to be Known as Speaker Daniel Z. Romualdez Memorial City Hospital, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 4764","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4764_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3749-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established under the direct supervision of the Director of Medical Services a general hospital at Tacloban City with a bed capacity of one hundred beds to be known as Speaker Daniel Z. Romualdez Memorial City Hospital.\nUpon the establishment of said hospital, the City of Tacloban shall be exempt from the payment of the proportionate share required under Republic Act Numbered Nineteen hundred thirty-nine, otherwise known as the Hospital Financing Act: Provided, However, That the City of Tacloban may extend financial aid to said hospital."}},{"id":"PH-H3749-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The architectural services and supervision in the construction of the hospital buildings thereof shall be undertaken by private parties through a licensed private architect."}},{"id":"PH-H3749-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of five hundred thousand pesos is hereby authorized to be appropriated out of any funds in the National Treasury not otherwise appropriated, for the construction and establishment, operation and maintenance of said hospital during the fiscal year nineteen hundred sixty-seven, including the purchase of a site. Thereafter, such sum as may be needed for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H3749-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Establishment of a General Hospital at Tacloban City, to be Known as Speaker Daniel Z. Romualdez Memorial City Hospital, and Authorizing the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3750"] = {"id":"PH-H3750","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4765_1966.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"规定在北伊罗戈省Currimao市镇设立渔业学校，名称为Currimao渔业学校，并授权为此拨款的法案","en":"An Act Providing for the Establishment of a School of Fisheries in the Municipality of Currimao, Province of Ilocos Norte, to be Known as the Currimao School of Fisheries, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Providing for the Establishment of a School of Fisheries in the Municipality of Currimao, Province of Ilocos Norte, to be Known as the Currimao School of Fisheries, and Authorizing the Appropriation of Funds Therefor","vi":"Đạo luật thành lập Trường Thủy sản tại Thị trấn Currimao, Tỉnh Ilocos Norte với tên gọi Trường Thủy sản Currimao, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติจัดตั้งโรงเรียนประมงในเทศบาล Currimao จังหวัด Ilocos Norte ในชื่อโรงเรียนประมง Currimao และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang membentuk Sekolah Perikanan di Kotamadya Currimao, Provinsi Ilocos Norte dengan nama Sekolah Perikanan Currimao, dan mengalokasikan dana untuk itu","ms":"Akta menubuhkan Sekolah Perikanan di Perbandaran Currimao, Wilayah Ilocos Norte dengan nama Sekolah Perikanan Currimao, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["environment","education"],"docNumber":"Republic Act No. 4765","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4765_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3750-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Director of Vocational Education, a school of fisheries in the Municipality of Currimao, Province of Ilocos Norte, to be known as the Currimao School of Fisheries."}},{"id":"PH-H3750-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said school during the fiscal year nineteen hundred sixty-seven Thereafter, such sums as may be needed for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H3750-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Establishment of a School of Fisheries in the Municipality of Currimao, Province of Ilocos Norte, to be Known as the Currimao School of Fisheries, and Authorizing the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3751"] = {"id":"PH-H3751","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4766_1966.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Batac市","en":"An Act Establishing a Fresh-Water Fish Nursery Station at Billoca Lake in the Municipality of Batac, Province of Ilocos Norte, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Establishing a Fresh-Water Fish Nursery Station at Billoca Lake in the Municipality of Batac, Province of Ilocos Norte, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4766","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4766_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3751-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established and maintained, under the supervision of the Commissioner of Fisheries, a fresh-water fish nursery station at Billoca Lake in the Municipality of Batac, Province of Ilocos Norte."}},{"id":"PH-H3751-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, to carry into effect the purposes of this Act during the fiscal year ending June thirtieth, nineteen hundred and sixty-seven. This amount shall be apportioned as follows:\na. Seventy thousand pesos for the procurement of the site and essential equipment and the installation of buildings and laboratories.\nb. Thirty thousand pesos for the maintenance of personnel for the nursery station.\nThereafter, the amount of not less than fifty thousand pesos needed for maintenance and operation shall be included in the General Appropriations Act each year."}},{"id":"PH-H3751-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53"};
  FT["PH-H3752"] = {"id":"PH-H3752","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4767_1966.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"宣布伊洛伊洛市内自Molo区至Arevalo区的海滨大道、其与海岸之间的公有土地及领水为城市公园，名称为Iloilo市公园的法案","en":"An Act Declaring the Boulevard, Public Lands Between it and the Shores and the Territorial Waters from the District of Molo to the District of Arevalo, Within the City of Iloilo, a City Park, to be Known as Iloilo City Park","orig":"An Act Declaring the Boulevard, Public Lands Between it and the Shores and the Territorial Waters from the District of Molo to the District of Arevalo, Within the City of Iloilo, a City Park, to be Known as Iloilo City Park"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4767","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4767_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3752-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Any provision of law to the contrary notwithstanding, the boulevard, and all public lands between it and the shores and the territorial water from the District of Molo to the District of Arevalo, all within the jurisdiction of the City of Iloilo, shall be declared a city park, to be known as Iloilo City Park. The Government of the City of Iloilo shall not sell, alienate or lease said property to any entity or private person."}},{"id":"PH-H3752-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Declaring the Boulevard, Public Lands Between it and the Shores and the Territorial Waters from the District of Molo to the District of Arevalo, Within the City of Iloilo, a City Park, to be Known as Iloilo City Park","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3753"] = {"id":"PH-H3753","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4768_1966.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"通过修订菲律宾关税与海关法典使Ozamis市分口岸成为入境口岸，并授权为此拨款的法案","en":"An Act Making the Ozamis City Subport a Port of Entry, by Amending the Tariff and Customs Code of the Philippines, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Making the Ozamis City Subport a Port of Entry, by Amending the Tariff and Customs Code of the Philippines, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 4768","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4768_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3753-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section seven hundred one of Republic Act Numbered Nineteen hundred thirty-seven, otherwise known as the Tariff and Customs Code of the Philippines, as amended by Republic Act Numbered Thirty-seven hundred fifty-seven, is further amended to read as follows:\n\"Sec. 701. Collection Districts and Ports of Entry thereof .— For administrative purposes, the Philippines shall be divided into as many collection districts as there are at present existing, the respective limits of which may be changed from time to time by the Commissioner, upon the approval of the department head. The principal ports of entry for the respective collection districts shall be Manila, Saul, Tabaco, Cebu, Pulupandan, Sia-in, Iloilo, Davao, Legaspi, Zamboanga, Jolo, Aparri, Jose Panganiban, Cayagan, Tacloban, San Fernando, Hinigaran, Dumaguete City, Maasin, Masao, Batangas and Ozamis City.\""}},{"id":"PH-H3753-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of five hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment and operation of the customs service at the port of Ozamis City."}},{"id":"PH-H3753-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Making the Ozamis City Subport a Port of Entry, by Amending the Tariff and Customs Code of the Philippines, and Authorizing the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3754"] = {"id":"PH-H3754","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4769_1966.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"为第十三司法区增设一名法官主持南莱特初审法院，常设于南莱特省San Juan市镇，为此修订经修正的1948年《司法法》第50条与第52条的法案","en":"An Act Providing for One Additional Judge for the Thirteenth Judicial District to Preside Over the Court of First Instance of Southern Leyte, with Permanent Station in the Municipality of San Juan, Province of Southern Leyte, Amending for the Purpose Sections Fifty and Fifty-Two of the Judiciary Act of 1948, as Amended","orig":"An Act Providing for One Additional Judge for the Thirteenth Judicial District to Preside Over the Court of First Instance of Southern Leyte, with Permanent Station in the Municipality of San Juan, Province of Southern Leyte, Amending for the Purpose Sections Fifty and Fifty-Two of the Judiciary Act of 1948, as Amended"},"level":"law","status":"active","topics":["judiciary"],"docNumber":"Republic Act No. 4769","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4769_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3754-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The thirteenth paragraph of Section fifty of Republic Act Numbered Two hundred ninety-six, known as \"The Judiciary Act of 1948,\" as amended, is further amended to read as follows:\n\"Eighteen judges shall be commissioned for the Thirteenth Judicial District. Eight judges shall preside over the Courts of First Instance of Samar and Calbayog City and shall be known as the judges of the first, second, third, fourth, fifth, sixth, seventh and eight branches thereof respectively; and ten judges shall preside over the Courts of First Instance of Leyte, Southern Leyte and the Cities of Ormoc and Tacloban, and shall be known as judges of the first, second, third, fourth, fifth, sixth, seventh, eighth, ninth and tenth branches thereof, respectively.\""}},{"id":"PH-H3754-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The twelfth subparagraph of the second paragraph of Section fifty-two of the same Act, as amended, is further amended to read as follows:\n\"For the Thirteenth Judicial District, one judge shall be stationed in the Municipality of Catbalogan, Province of Samar; one judge, in the Municipality of Borongan, same province; one judge, in the Municipality of Laoang, same province; one judge, in the Municipality of Catarman, same province; one judge, in the City of Calbayog; one judge, in the Municipality of Guiuan, Province of Samar; one judge, in the Municipality of Allen, same province and one judge, in the Municipality of Oras, same province; three judges shall be stationed in the City of Tacloban: one judge, in the Municipality of Maasin, Province of Southern Leyte; one judge in the Municipality of San Juan, same province; one judge, in the City of Ormoc, who shall hold court sessions in the Municipality of Palompon at least two months every year; one judge, in the Municipality of Guiuan, Province of Leyte; one judge, in the Municipality of Baybay, same province; one judge, in the Municipality of Burauen, same province; and one judge in the Municipality of Naval, Subprovince of Biliran.\""}},{"id":"PH-H3754-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"There is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, such sum as may be necessary to carry out the purpose of this act."}},{"id":"PH-H3754-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for One Additional Judge for the Thirteenth Judicial District to Preside Over the Court of First Instance of Southern Leyte, with Permanent Station in the Municipality of San Juan, Province of Southern Leyte, Amending for the Purpose Sections Fifty and Fifty-Two of the Judiciary Act of 1948, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3755"] = {"id":"PH-H3755","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4770_1966.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"为北伊罗戈省增设助理省检察官职位，为此修订《行政法典》第1674条（经修正）的法案","en":"An Act Creating Additional Positions of Assistant Provincial Fiscal in the Province of Ilocos Norte, Amending for This Purpose Section Sixteen Hundred and Seventy-Four of the Administrative Code, as Amended","orig":"An Act Creating Additional Positions of Assistant Provincial Fiscal in the Province of Ilocos Norte, Amending for This Purpose Section Sixteen Hundred and Seventy-Four of the Administrative Code, as Amended"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 4770","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4770_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3755-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section sixteen hundred and seventy-four of the Administrative Code, as amended, relative to the number of assistant provincial fiscals in the Province of Ilocos Norte, is further amended to read as follows:\n\"Ilocos Norte, eight assistant provincial fiscals, two of whom shall be assigned for the fourth branch of the Court of First Instance stationed in the Municipality of Batac, Province of Ilocos Norte.\""}},{"id":"PH-H3755-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating Additional Positions of Assistant Provincial Fiscal in the Province of Ilocos Norte, Amending for This Purpose Section Sixteen Hundred and Seventy-Four of the Administrative Code, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3756"] = {"id":"PH-H3756","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4771_1966.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"修订第605号共和国法（即《在马斯巴特省Milagros市镇设立、组建并维持一所国立农业学校并授权为此拨付特定款项法》）的标题、第1条与第3条的法案","en":"An Act Amending the Title, Section One and Section Three of Republic Act Numbered Six Hundred Five, Entitled \"An Act to Establish, Organize and Maintain One National Agricultural School in the Municipality of Milagros, Province of Masbate, and to Authorize the Appropriation of Certain Sums of Money for the Purpose\"","orig":"An Act Amending the Title, Section One and Section Three of Republic Act Numbered Six Hundred Five, Entitled \"An Act to Establish, Organize and Maintain One National Agricultural School in the Municipality of Milagros, Province of Masbate, and to Authorize the Appropriation of Certain Sums of Money for the Purpose\"","vi":"Đạo luật sửa đổi các Điều 1 và 3 của Đạo luật Cộng hòa số 605","th":"พระราชบัญญัติแก้ไขเพิ่มเติมมาตรา 1 และ 3 แห่งพระราชบัญญัติแห่งสาธารณรัฐที่ 605","id":"Undang-Undang mengubah Pasal 1 dan 3 Undang-Undang Republik No. 605","ms":"Akta meminda Seksyen 1 dan 3 Akta Republik No. 605"},"level":"law","status":"active","topics":["education","environment"],"docNumber":"Republic Act No. 4771","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4771_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3756-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The title of Republic Act Numbered Six hundred five is hereby amended to read as follows:\n\"An Act to established, organize and maintain one national agricultural school in the Municipality of Mandaon, Province of Masbate, and to authorize the appropriation of certain sums of money for the purpose.\""}},{"id":"PH-H3756-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section one of the same Act is amended to read as follows:\n\"Sec. 1. The Secretary of Education is hereby authorized to establish, organize and maintain one national agricultural school of the Central Luzon Agricultural School type in the Municipality of Mandaon, Province of Masbate, to be called Masbate Agricultural School.\""}},{"id":"PH-H3756-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section three of the same Act is amended to read as follows:\n\"Sec. 3. The Secretary of Education is hereby empowered to locate and acquire or cause to be located and acquired a suitable site for the purpose of this Act, which may be public or private lands situated within the Municipality of Mandaon, Province of Masbate.\""}},{"id":"PH-H3756-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending the Title, Section One and Section Three of Republic Act Numbered Six Hundred Five, Entitled \"An Act to Establish, Organize and Maintain One National Agricultural School in the Municipality of Milagros, Province of Masbate, and to Authorize the Appropriation of Certain Sums of Money for the Purpose\"","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3757"] = {"id":"PH-H3757","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4772_1966.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将莱特省塔克洛班机场更名为丹尼尔·Z·罗穆亚尔德斯议长机场的法案","en":"An Act Changing the Name of Tacloban Airport in the Province of Leyte to Speaker Daniel Z. Romualdez Airport","orig":"An Act Changing the Name of Tacloban Airport in the Province of Leyte to Speaker Daniel Z. Romualdez Airport","vi":"Đạo luật đổi tên Tacloban Airport tại Tỉnh Leyte thành Speaker Daniel Z. Romualdez Airport","th":"พระราชบัญญัติเปลี่ยนชื่อ Tacloban Airport ในจังหวัด Leyte เป็น Speaker Daniel Z. Romualdez Airport","id":"Undang-Undang mengubah nama Tacloban Airport di Provinsi Leyte menjadi Speaker Daniel Z. Romualdez Airport","ms":"Akta menukar nama Tacloban Airport di Wilayah Leyte menjadi Speaker Daniel Z. Romualdez Airport"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4772","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4772_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3757-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Tacloban Airport in the Province of Leyte is hereby changed to Speaker Daniel Z. Romualdez Airport."}},{"id":"PH-H3757-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of Tacloban Airport in the Province of Leyte to Speaker Daniel Z. Romualdez Airport","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3758"] = {"id":"PH-H3758","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4773_1966.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将萨马省Catbalogan市镇萨马省立医院床位增至100张并授权为此拨款的法案","en":"An Act Increasing the Bed Capacity of the Samar Provincial Hospital in the Municipality of Catbalogan, Province of Samar, to One Hundred Beds and Authorizing the Appropriation of Funds Therefor","orig":"An Act Increasing the Bed Capacity of the Samar Provincial Hospital in the Municipality of Catbalogan, Province of Samar, to One Hundred Beds and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 4773","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4773_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3758-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The bed capacity of Samar Provincial Hospital in the Municipality of Catbalogan, Province of Samar, is hereby increased to one hundred beds."}},{"id":"PH-H3758-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of two hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the operation and maintenance of said hospital during the fiscal year nineteen hundred sixty-seven. Thereafter, such sum as may be needed for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H3758-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Increasing the Bed Capacity of the Samar Provincial Hospital in the Municipality of Catbalogan, Province of Samar, to One Hundred Beds and Authorizing the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3759"] = {"id":"PH-H3759","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4774_1966.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating Five Million Pesos for Relief and Aid to the Fire Victims in Iloilo City and Roxas City","orig":"An Act Appropriating Five Million Pesos for Relief and Aid to the Fire Victims in Iloilo City and Roxas City"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4774","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4774_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3759-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby appropriated, out of any funds in the National Treasury not otherwise appropriated, the sum of five million pesos for relief and aid to the Filipino victims of the fire which occurred in Iloilo City on February seven and eight, nineteen hundred and sixty-six, said aid and relief to be administered and distributed by the city relief committee to be composed of the representative of the Social Welfare Administration as chairman, with the city engineer, city assessor, city treasurer, and representative of the Red Cross as members: Provided, However, That out of the amount herein appropriated, one million pesos shall be allocated and/or set aside for the relief and aid to Filipino victims of the fire which occurred in Roxas City in January, nineteen hundred and sixty-six."}},{"id":"PH-H3759-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53"};
  FT["PH-H3760"] = {"id":"PH-H3760","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4775_1966.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将朗布隆省纳入Panay Development Authority的服务区域，为此修订第3856号共和国法的法案","en":"An Act Including the Province of Romblon in the Region Served by Panay Development Authority, Amending for the Purpose Republic Act Numbered Thirty-Eight Hundred Fifty-Six","orig":"An Act Including the Province of Romblon in the Region Served by Panay Development Authority, Amending for the Purpose Republic Act Numbered Thirty-Eight Hundred Fifty-Six"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4775","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4775_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3760-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one of Republic Act Numbered Thirty-eight hundred fifty-six is amended to read as follows:\n\"Sec. 1. Declaration of Policy.— It is hereby declared to be the policy of Congress to adopt accelerated measures and to utilize to the maximum local resources and talents to bolster agro-industrial development through the leadership, guidance and support of the Government. To this end, cognizant of the necessity of grouping together regional areas having similar economic and geographical basis, the provinces grouped together as one region comprising the Island of Panay and the Province of Romblon, hereinafter referred to as the region, shall constitute a Regional Development Authority for the purpose of conducting economic surveys to determine its agricultural and industrial potentialities and mapping out and implementing plans and programs to effect the coordinated and integrated efforts of various government agencies, as well as private entities engaged in activities conducive to rapid regional agro-industrial development; of providing active leadership in the establishment of pioneering industrial, agricultural or similar enterprises and lending financial, managerial and/or technical assistance to existing or prospective ventures within the region.\""}},{"id":"PH-H3760-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section twelve of the same Act is amended to read as follows:\n\"Sec. 12. Board of Directors—Composition.— The corporate powers of the Authority shall be vested in and exercised by a Board of Directors herein referred to as the Board, which shall be composed of five members including its chairman, appointed by the President of the Philippines with the consent of the Commission on Appointments. The governors of the Provinces of Aklan, Capiz, Antique, Iloilo and Romblon shall be members ex-officio of the Board and as such shall take part in all its meetings, deliberations and discussions, but shall not have the right to vote, except as hereinafter provided.\""}},{"id":"PH-H3760-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Including the Province of Romblon in the Region Served by Panay Development Authority, Amending for the Purpose Republic Act Numbered Thirty-Eight Hundred Fifty-Six","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3761"] = {"id":"PH-H3761","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4776_1966.html","fetchedAt":"2026-10-06","articleCount":51,"structureMode":"ARTICLE","title":{"zh":"修订第 3068 号共和国法即经修订的 Tacloban 市宪章的某些条款并为其他目的法案","en":"An Act Amending Certain Provisions of Republic Act Numbered Thirty Hundred Sixty-Eight, Known as the Revised Charter of the City of Tacloban, and for Other Purposes","orig":"An Act Amending Certain Provisions of Republic Act Numbered Thirty Hundred Sixty-Eight, Known as the Revised Charter of the City of Tacloban, and for Other Purposes","vi":"Đạo luật sửa đổi một số điều khoản của Luật Cộng hòa số 3068, tức Hiến chương Thành phố Tacloban đã được sửa đổi","th":"พระราชบัญญัติแก้ไขบางมาตราแห่งรัฐบัญญัติฉบับที่ 3068 หรือกฎบัตรเมือง Tacloban ที่แก้ไขเพิ่มเติมแล้ว","id":"Undang-Undang mengubah beberapa ketentuan Undang-Undang Republik Nomor 3068, yaitu Piagam Kota Tacloban sebagaimana telah diubah","ms":"Akta meminda beberapa peruntukan Akta Republik Nombor 3068, iaitu Piagam Bandaraya Tacloban sebagaimana yang telah dipinda"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4776","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 51 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4776_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文条号不连续（自第 1 条起，止于第 52 条，缺 39）：经逐条比对原始页面，该处原文没有对应的 “Section N.” 抬头行，系来源页自身的编号跳跃或条文以“续段”形式并入前条，非抽取遗漏，故未擅自补号。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3761-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section five of Republic Act Numbered Thirty hundred sixty-eight is hereby amended to read as follows:\n\"Sec. 5. Territory of the City of Tacloban.— The City of Tacloban shall comprise the territorial jurisdiction of the former Municipality of Tacloban in the Province of Leyte, and shall be divided, for all administrative and other municipal purposes, into the city proper which shall be divided by ordinance into districts, and the rest of the territory of the city into barrios in accordance with Article IV hereof.\""}},{"id":"PH-H3761-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section six of the same Act is amended to read as follows:\n\"Sec. 6. Jurisdiction of the City.— The jurisdiction of the City of Tacloban for police purposes only shall be co-extensive with its territorial jurisdiction; and shall extend to the mid-channel of the San Juanico Strait and three miles from the shore into San Pedro Bay; however, for the purpose of effecting the arrest of a person who has committed an offense within the jurisdiction of the city, the police authorities of the city shall exercise concurrent jurisdiction with police forces of other municipalities where said offender may have fled or escaped; and for the purpose of protecting and insuring the purity of the water supply of the city, such police jurisdiction shall also extend over all territory within the drainage area of such water supply, or within one hundred meters of any reservoir, conduit, canal, aqueduct, or pumping station used in connection with the city water service. The city court of the city shall have concurrent jurisdiction with the municipal court of the respective municipalities to try crimes and misdemeanors committed within said drainage area, or within said spaces of one hundred meters. The court first taking jurisdiction of such an offense shall thereafter retain exclusive jurisdiction thereof. The police force of the several municipalities concerned shall have concurrent jurisdiction with the police force of the city for the maintenance of good order and the enforcement of ordinances throughout said zone, area and spaces. But any license that may be issued within said zone, area or space shall be granted by the proper authorities of the municipalities concerned and the fees arising therefrom shall accrue to the treasury of the said municipality concerned and not to that of the city.\""}},{"id":"PH-H3761-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section seven of the same Act is amended to read as follows:\n\"Sec. 7. The Mayor.— The Mayor shall be the chief executive of the city. He shall be elected at large by the qualified voters of the city. No person shall be eligible for the position of Mayor unless, at the time of his election, he is at least twenty-five years of age, a resident of the city for at least two years prior to his election, and a qualified voter therein. He shall hold office for four years unless sooner removed for just cause and with due process of law, and shall receive a salary of not less than fifteen thousand pesos per annum. The Municipal Board may appropriate such sum of money as may be necessary for the housing and representation allowance of the Mayor, not to exceed six thousand pesos annually or commute the same in addition to his salary.\""}},{"id":"PH-H3761-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Paragraphs one and three, Section eight of the same Act are amended to read as follows:\n\"Sec. 8. The Vice-Mayor.— There shall be elected a Vice-Mayor who shall perform the duties and exercise the powers of the Mayor, in the event of sickness, absence or other temporary incapacity of the Mayor. In the event of death, resignation or definite and permanent vacancy in the position of Mayor, the Vice-Mayor shall become the Mayor. The Vice-Mayor shall be elected in the same manner as the Mayor and shall, at the time of his election, possess the same qualifications as the Mayor.\n\"The Vice-Mayor shall perform such other duties as may be assigned to him by the Mayor or prescribed by law or ordinance. He shall receive a salary of not less than ten thousand two hundred pesos per annum.\""}},{"id":"PH-H3761-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Sub-paragraph (e), Section nine, of the same Act is amended to read as follows:\n\"(e) To see that the executive officers and employees of the city property discharge their respective duties. The Mayor may, in the interest of the service, transfer officers and employees not appointed by the President of the Philippines from one section, division, or service to another section, division, or service without changing the compensation they receive.\""}},{"id":"PH-H3761-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Section ten of the same Act is amended to read as follows:\n\"Sec. 10. Secretary to the Mayor.— The Mayor shall appoint one secretary, who shall have the rank of a department head and who shall have charge and custody of all records and documents of the city and of any office or department thereof for which provision is not otherwise made; shall keep the corporate seal and affix the same with his signature on all ordinances and resolutions signed by the Mayor and all other official documents and papers of the government of the city as may be required by law or ordinance; shall attest all executive orders, proclamations, ordinances and resolutions signed by the Mayor and shall perform such other duties as the Mayor may require of him; shall, upon request, furnish certified copies of all city records and documents in his charge which are not of confidential nature, and collect and receive such fees as may be prescribed by law or resolution of the Municipal Board. He shall also perform such duties as are required of the heads of departments of the city government under Section twenty-one hereof. The position of the secretary shall be regarded as within the unclassified civil service but may be filled in the manner in which classified positions are filled, and if so filled, the appointee shall be entitled to all the benefits and privileges of classified employees, except that he shall hold office only during the term of the appointing Mayor and until a successor in the office of the secretary is appointed and qualified, unless sooner separated. He shall receive a salary of not less than nine thousand six hundred pesos per annum.\""}},{"id":"PH-H3761-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The same Act is amended by inserting between Sections ten and eleven thereof a new section to be known as Section ten-A, to read as follows:\n\"Sec. 10-A. Assistant Secretary.— There shall be an assistant secretary to the Mayor who shall assist the secretary to the Mayor in the discharge of his official duties and perform such other duties as the Mayor may required of him.\n\"The position of the assistant secretary shall be regarded as within the unclassified civil service but may be filed in the manner in which classified positions are filled, and if so filled, the appointee shall be entitled to all the benefits and privileges of classified employees, except that he shall hold office only during the term of the appointing Mayor and until a successor in the office of assistant secretary is appointed and qualified, unless sooner separated.\n\"In the absence of the secretary, or in cases of illness or inability of the secretary to discharge his duties, the assistant secretary shall assume the powers and duties of the former. He shall receive a salary of not less than six thousand six hundred pesos per annum.\""}},{"id":"PH-H3761-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The third paragraph, Section eleven of the same Act is amended to read as follows:\n\"The members of the Municipal Board shall receive a salary of not less than seven thousand eight hundred pesos each per annum.\""}},{"id":"PH-H3761-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The last paragraph, Section thirteen of the same Act is amended to read as follows:\n\"The Secretary shall be in charge of the records of the Municipal Board. He shall keep a full record of the proceedings of the Board, and file all documents relating thereto; shall record in a book kept for that purpose; all ordinances, and all resolutions and motions directing the payment of money or creating liability, enacted or adopted by the Board, with the dates of passage of the same, and of the publication of ordinances; shall keep a seal, circular in form, with the inscription ‘Municipal Board—City of Tacloban’ in the center of which shall be placed the arms of the city, and affix the same, with his signature to all ordinances and other official acts of the Board, and shall present the same for signature to the Presiding Officer; shall cause each ordinance passed to be published as herein provided; shall, upon request, furnish certified copies of all records of public character in his charge under the seal of his office; and collect and receive therefor such fees as may be prescribed by resolution of the Board; and shall keep his office and all records therein which are not of a confidential nature, open to public inspection during usual business hours. The compensation of the Secretary shall be not less than nine thousand six hundred pesos per annum.\""}},{"id":"PH-H3761-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The first paragraph, Section fourteen of the same Act is amended to read as follows:\n\"Sec. 14. Legislative Procedure.— The Board shall hold two ordinary sessions for the transaction of business during each week on days which it shall fix by resolutions, and such extraordinary sessions, as may be called by the Mayor. It shall sit with open doors unless otherwise ordered by the affirmative vote of a majority of all the members. It shall keep a record of all its proceedings and determine its rules of procedure not herein set forth, as well as determine its officers except the presiding officer, the number thereof and the method of their election and their terms of office. A majority of all the members of the Board shall constitute a quorum for the transaction of business, but a smaller number may adjourn from day to day and may compel the immediate attendance of any member who is absent without good cause by issuing to the police of the city an order for his arrest and production at the session under such penalties as shall have been previously prescribed by ordinance. The affirmative vote of a majority of all the members shall be necessary for the passage of any ordinance, or of any resolution or motion directing the payment of money or creating liability, but other measures shall prevail upon the majority vote of the members present at any session duly called and held. The ayes and nays shall be taken and recorded upon the passage of all ordinances, upon all resolutions or motions directing the payment of money or creating liability, and, at the request of any member, upon any other resolution or motion. Each approved ordinance, resolution or motion shall be sealed with the seal of the Municipal Board, and recorded in a book kept for the purpose and shall, on the day following its passage, be posted by the secretary at the main entrance of the city hall and in at least two other public places, and shall take effect and be in force on and after the tenth day following its passage, unless otherwise stated in said ordinance, resolution or motion or vetoed by the Mayor as hereinafter provided. A vetoed ordinance, if repassed, shall take effect ten days after the veto is overridden by the required votes, unless otherwise stated in the ordinance, resolution or motion or again disapproved by the Mayor.\""}},{"id":"PH-H3761-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Sub-paragraphs (b), (s), and (u), Section fifteen of the same Act are amended to read as follows:\n\"(b) To fix the number and salaries of officials and employees of the city not otherwise provided for in this Act or other laws.\n\"(s) To permit, regulate and tax motor and other vehicles operating within the City of Tacloban, the provisions of any existing law to the contrary notwithstanding, and draft animals not paying any national tax: Provided, That all automobiles and trucks belonging to the National Government or to any provincial or municipal government shall be exempt from such tax.\n\"(u) To impose a sales tax of not exceeding two per centum of the gross value in money of all articles sold, bartered, exchanged, transferred, delivered or consigned within the City, regardless of the origin of said articles or goods.\""}},{"id":"PH-H3761-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The same Act is amended by adding sub-paragraph (uu) to Section fifteen hereof:\n\"(uu) The provisions of existing law to the contrary notwithstanding, to undertake the reclamation of any foreshore lands within the jurisdiction of the city, either by administration or by contract, and which reclaimed area may be leased, sold or bartered by the city subject to the provisions of existing laws and regulations on contracts.\""}},{"id":"PH-H3761-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Section seventeen of the same Act is amended to read as follows:\n\"Sec. 17. Creation of new barrios.— Upon petition of a majority of the voters in the areas affected, a new barrio may be created or the name of an existing one may be changed by the municipal board, in the latter case, upon recommendation of the barrio council.\n\"No barrio may be created if its population is less than five hundred.\n\"Barrios shall not be created or their boundaries altered nor their names changed except under the provisions hereof or by an Act of Congress.\""}},{"id":"PH-H3761-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"The same Act is amended by inserting between Sections seventeen and eighteen thereof new sections to be known as Sections seventeen-A, seventeen-B, seventeen-C, seventeen-D, seventeen-E, seventeen-F, seventeen-G and seventeen-H, to read as follows:\n\"Sec. 17-A. Barrio Assembly.— The barrio assembly shall consist of all persons who have been residents of the barrio for at least six months, are twenty-one years of age or over, citizens of the Republic of the Philippines and who are duly registered in the list of barrio assembly members kept by the barrio secretary.\n\"The barrio secretary shall keep a list wherein the names of all members of the barrio assembly shall be entered in alphabetical order, keeping a separate list for every group belonging to one alphabetical group and, in addition, the list shall indicate the age, status, occupation, and the name of the sitio where the member resides.\n\"The barrio secretary shall revise the list of barrio assembly members not later than the first Saturday of January of each year. The revision shall be made by deleting therefrom names of members who have died during the year as certified to by the local civil registrar, stating the date and place of death; names of members who have transferred residences upon application of the members transferring, stating the date of transfer and place transferred to, if known; and finally, by including therein the names of those who have acquired the qualifications to become members of the barrio assembly, stating therein the date of admission to the barrio assembly.\n\"Sec. 17-B. Powers of Barrio Assembly.— The powers of the barrio assembly shall be as follows:\n\"(a) To recommend to the barrio council the adoption of measures for the welfare of the barrio;\n\"(b) To decide on the holding of a plebiscite on matters that vitally affect the barrio; and \"(c) To hear the annual report of the barrio council concerning activities and finances of the assembly.\n\"Sec. 17-C. Election of Barrio Council.— On the second Sunday of January immediately following the regular elections for municipal and provincial officials, and on the days thereafter in the month of January, a regular election shall be held to elect a barrio captain and six councilmen for each barrio. The date of the election in the barrio shall be set by the Mayor, upon the written recommendation of the barrio council.\n\"In case of failure to hold the election on the date set, it may be held on any other day within the month of January to be determined by the Mayor: Provided, That if, for any reason, no election in any of the barrios is held within the month of January, the Mayor shall, upon resolution of the barrio council or written petition of at least fifty members of the barrio assembly, fix the date of the election which shall not be beyond forty days from receipt of said resolution or petition.\n\"In the case of a newly created barrio the election shall be held on a date to be fixed by the Mayor which shall be not more than forty days from the approval by the municipal board of the resolution creating said barrio.\n\"The elected officials of the newly created barrio shall assume office immediately by taking oath before any person authorized to administer it and shall hold office for the unexpired term or until their successors shall have been elected and qualified.\n\"Not later than the last Sunday of December of the year immediately preceding the local elections, the barrio council shall elect a board of election tellers for each regular precinct situated in said barrio, one of whom shall be a public school teacher who shall be the chairman, one belonging to the party who obtained the highest number of votes in the last presidential elections, and one from the party who received the second highest number of votes in the elections, to conduct the elections, count the votes, and proclaim the winners in their respective precincts. The barrio council shall also recommend the polling place and date of election to the Mayor and immediately after its approval by the Mayor, it shall cause the publication of the date and place of the election and the office to be filled.\n\"On the first Sunday of January of an election year in accordance with this section, there shall be a registration of new voters to be conducted by the board of election tellers of each precinct. Any voter may challenge the qualification of any person seeking to register, and said challenge shall be heard and decided by the board of election tellers on the same day. On the Tuesday immediately following the day of registration as herein provided for, the board of election tellers shall meet to prepare the list of qualified voters entitled to vote in the barrio election. Revision shall be made by copying all the names of the registered voters appearing in the list of voters used in the previous election, deleting therefrom all the names of registered voters who have died, transferred residences, as shown by the list of the members of the barrio assembly, furnished by the barrio secretary, and those who have become disqualified under the law. A copy of the aforesaid list shall be furnished the barrio secretary.\n\"Voting shall be by secret ballot. It shall be held in a place designated by the barrio council; voting shall be from seven o’clock in the morning to six o’clock in the afternoon, except when there are still voters within thirty meters of the polling place, in which case they shall be allowed to vote. The voters shall have the right to vote in the order of their entrance to the polling place, identifying themselves to the board of election tellers who will check their names against the list of voters prepared by them in accordance herewith.\n\"Each candidate shall be allowed to appoint one watcher, who, upon presentation of his appointment signed by the candidate to the board of election tellers, may be allowed inside the polling place during the election proceedings. No person shall be allowed to enter the voting booths except voters actually voting. Immediately after the close of voting and when all the voters entitled to vote have cast their votes, the board of election tellers shall immediately proceed to canvass the votes and those who obtained the highest number of votes for the position for which they are candidates shall be declared elected. In case of a tie, the same shall be decided by drawing lots immediately after the counting of the votes and the winner shall be declared elected.\n\"The board of election tellers shall prepare in quintuplicate the results of the election of the precinct, which election return shall contain the names of the candidates voted for in the said election, segregating therefrom the names of the winning candidates from those of the losing ones, the offices to which they have been voted for, the number of votes obtained by each, which number of votes shall be written in words and then in figures. The certificates above referred to shall be certified to and signed by all the members of the board of election tellers. The original shall be transmitted by personal service to the barrio secretary, one copy shall be deposited in the ballot box together with all other documents used in the election, one copy shall be sent to the city treasurer and the remaining two copies shall be for each of the two other members of the board of election tellers.\n\"On the day immediately following the elections, the barrio council, acting as a board of canvassers, shall canvass the results of the election in the barrio, which canvass shall be based upon the election returns submitted by the board of election tellers to the secretary and immediately thereafter proclaim the winning candidates. The members of the barrio council who are running for re-election are disqualified to act in the said board of canvassers and the Mayor is hereby empowered to appoint their substitutes who shall be chosen from the same political party to which the disqualified member belongs.\n\"The officials elected shall assume office immediately by taking oath before any person authorized to administer oaths and shall hold office for four years or until their successors shall have been elected and qualified.\n\"Sec. 17-D. Candidates— Their qualifications and failure to file certificates of candidacy.— Candidates shall file their certificates of candidacy with the barrio secretary not later than the first Sunday of the election year. Any five registered voters may also file the certificate of candidacy of any qualified person.\n\"Every citizen of the Philippines, twenty-one years of age or over, able to read and write, who has been a resident of the barrio during the six months immediately preceding the election, duly registered in the list of voters kept by the barrio secretary, who is not otherwise disqualified, may vote or be a candidate in the barrio elections.\n\"Any vote in favor of a person who has not filed a certificate of candidacy or in favor of a candidate for an office for which he did not present himself, shall be void and counted as a stray vote but shall not invalidate the whole ballot.\n\"Sec. 17-E. Qualification of voters.— Every citizen of the Philippines, twenty years of age or over, able to read and write, who has been a resident of the barrio during the six months immediately preceding the elections, duly registered in the list of voters kept by the barrio secretary, who is not otherwise disqualified, may vote in the barrio elections.\n\"The following are not qualified to vote:\n\"(a) Any person who has been sentenced by final judgment to suffer one year or more of imprisonment, within two years after serving his sentence.\n\"(b) Any person who has violated his allegiance to the Republic of the Philippines; and \"(c) Insane or feeble-minded persons.\n\"Sec. 17-F. Election Disputes.— All disputes as to procedure before and during the balloting shall be decided by the board of election tellers.\n\"All disputes over barrio elections shall be brought before the city court of the City of Tacloban; and in the determination and decision thereof the court shall follow as closely as possible the procedure prescribed for inferior courts in the Rules of Court. The decisions of the city court shall be appealable pursuant to the Rules of Court to the Court of First Instance whose decisions shall be final on questions of fact.\n\"Sec. 17-G. Rights of Succession.— When no special elections are held to fill a permanent vacancy in the office of barrio captain, arising from death, permanent incapacity, abandonment, or when there is failure to elect a qualified candidate, the councilman who obtained the largest number of votes in the barrio elections immediately preceding, shall assume the office of barrio captain; if, for some reason, the councilman who obtained the largest number of votes is incapacitated from assuming the office of barrio captain or refuses to assume such office, the councilman who obtained the next largest number of votes in the barrio elections immediately preceding, shall assume the office of the barrio captain, and so on until the permanent vacancy in the office of barrio captain is filled.\n\"There is abandonment of office of barrio captain if the incumbent fails or refuses, without lawful cause, to enter upon the discharge of his duties within a period of six months from the time he ceases or neglects to perform his official duties.\n\"Should the barrio captain-elect die before assumption of office or fail to qualify for any reason, the councilman who obtained the largest number of votes in the barrio elections immediately preceding shall assume office until a barrio captain qualifies. In case of a tie between the councilman who obtained the largest number of votes in the barrio elections immediately preceding, the barrio council will decide on who shall succeed. In the event that no special election is held and for some reason the senior councilman elect is incapacitated from assuming the office of barrio captain, the rule of succession described in the first paragraph of this section shall be followed.\n\"In the event that the barrio captain is temporarily incapacitated to perform the duties of his office on account of absence on leave, sickness or any other cause, the senior councilman shall perform the duties and exercise the powers of the barrio captain except, unless unanimously authorized by the barrio council, the power to appoint, suspend or dismiss employees. In the event that the senior councilman is temporarily incapacitated to perform the duties of the barrio captain or refuses to assume such office, the councilman who obtained the next largest number of votes among the incumbent councilmen in the barrio elections immediately preceding shall perform the duties and exercise the powers of the barrio captain except, unless unanimously authorized by the council, the power to appoint, suspend or dismiss employees.\n\"Sec. 17-H. The Commission on Elections shall have, in addition to the powers and functions conferred upon it by the Constitution, overall supervision over all elections of the members of the barrio council, with powers to promulgate necessary rules and regulations consistent with the provisions of this Article.\""}},{"id":"PH-H3761-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Section eighteen of the same Act is amended to read as follows:\n\"Sec. 18. Power of control and supervision by the Mayor.— The mayor shall exercise control and supervision over barrio officials and shall see to it that they perform and discharge their duties faithfully and in accordance with law. He shall receive and investigate complaints made under oath against barrio officers for neglect of duty, oppression, corruption and other forms of misconduct in office, and conviction by final judgment of any crime involving moral turpitude. For minor delinquency, he may reprimand the offender; and if a more severe punishment seems to be desirable, he shall submit written charges to the municipal board, furnishing a copy of such charges to the respondent either personally or by registered mail. Upon recommendation of the barrio council, the Mayor may suspend the officer pending action by the municipal board, if in his opinion the charge be one affecting the official integrity of the officer in question, but in no case shall the suspension last more than thirty days.\n\"Where suspension is thus effected, the written charges against the officer shall be filed within five days with the municipal board, which shall adopt the procedure specified in Sections twenty-one hundred eighty-nine to twenty-one hundred ninety of the Revised Administrative Code.\n\"The decision of the municipal board shall be final and shall not be appealable.\""}},{"id":"PH-H3761-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"The same Act is amended by inserting between Sections eighteen and nineteen thereof a new section to be known as Section eighteen-A to read as follows:\n\"Sec. 18-A. Applicability of Other Laws.— The provisions of Sections thirteen, fourteen, fifteen, sixteen, seventeen, eighteen, nineteen, twenty, twenty-one, twenty-two and twenty-three of Republic Act Numbered Thirty-five hundred and ninety, insofar as they are not inconsistent herewith, are hereby made applicable to all barrios in the city: Provided, That the barrio treasurer shall be appointed by the barrio captain upon the recommendation of the city treasurer and shall be bonded in accordance with existing laws in an amount to be determined by the barrio council but not exceeding ten thousand pesos.\""}},{"id":"PH-H3761-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Section twenty of the same Act is amended to read as follows:\n\"Sec. 20. City Departments.— There shall be the following city departments over which the Mayor shall have direct control and supervision, any existing law to the contrary notwithstanding:\n\"1. Department of Finance \"2. Department of Engineering and Public Works \"3. Law Department \"4. Department of Health \"5. Police Department \"6. Fire Department \"7. Department of Assessment \"8. Department of General Services \"The Municipal Board may, from time to time, make such readjustments of the duties of several departments as public interest may demand, and, with the approval of the President, may consolidate any department, division of office of the city with any other department, division or office.\n\"The municipal board may, by ordinance, create a department not herein otherwise provided for as public interest may demand, or add or increase the powers of any of the departments already provided for herein by creating a division or office thereof.\""}},{"id":"PH-H3761-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"The second paragraph of Section twenty-one of the same Act is amended to read as follows:\n\"In case of absence, sickness, suspension, or inability to act for any other reason, of the head of a department of the city or in case of temporary vacancy, the assistant of that department shall perform the duties of that department head concerned, and in case of absence, sickness, suspension or inability to act, or for any other reason, of the assistant department head, or in case of temporary vacancy, the officer next in charge of that department shall perform such duties, the provision of any existing law to the contrary notwithstanding.\""}},{"id":"PH-H3761-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Section twenty-two of the same Act is amended to read as follows:\n\"Sec. 22. Appointments, removal of officials and employees.— The President of the Philippines, with the consent of the Commission on Appointments, shall appoint the judge and auxiliary judge, the city treasurer, the city engineer, the city general services officer, the city fiscal and his assistants, the chief of police, the city health officer, the city assessor, the chief of the fire department, and the city superintendent of schools. Said officers shall not be suspended or removed except in the manner and for causes provided for by law.\n\"Subject to the provisions of the Civil Service Law, the Mayor shall appoint all other heads of such city departments as may be created and all other officers and employees paid out of city funds except the employees of the municipal board who shall be appointed by the presiding officer thereof, aside from those mentioned in this Act, without prior approval or concurrence of the department head concerned, of the National Government, subject to confirmation by the municipal board, and they shall be suspended and removed in accordance with law.\""}},{"id":"PH-H3761-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Section twenty-four of the same act is amended to read as follows:\n\"Sec. 24. The General Auditing Office.— The Auditor General shall receive and audit all accounts of the city, in accordance with the provisions of law relating to government accounts and accounting. The City Auditor shall be appointed by the Auditor General and shall receive a salary of not less than twelve thousand six hundred pesos per annum, one-half to be paid by the National Government and the other half by the city.\n\"He shall likewise perform the duties of auditing national funds disbursements of the city engineer’s office.\""}},{"id":"PH-H3761-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Section twenty-six of the same Act is amended to read as follows:\n\"Sec. 26. The City Register of Deeds.— There shall be a register of deeds for the City of Tacloban who shall be appointed by the President of the Philippines with the consent of the Commission on Appointments and who shall receive a salary at the rate prescribed by Republic Act Numbered One hundred sixty-four, as amended by Republic Act Numbered One thousand one hundred thirty-eight and which amount shall be paid by the National Government.\n\"The register of deeds for the City of Tacloban shall perform all the functions and duties prescribed by existing law for registers of deeds of chartered cities and provinces.\""}},{"id":"PH-H3761-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"The same Act is amended by inserting between Sections twenty-six and twenty-seven, new sections to be known as Sections twenty-six-A and twenty-six-B to read as follows:\n\"Sec. 26.-A. Qualification of City Register of Deeds.— No person shall be appointed to the office of city register of deeds unless he has been employed for over five years in some branch of the Government the functions of which include the registration of property, or unless he is authorized to practice law in Philippines, or is a graduate of a law school recognized by the government. This qualification shall, however, not be required in the case of officers designated temporarily to perform the duties of register of deeds.\n\"Sec. 26-B. The Register of Deeds.— The register of deeds for the Province of Leyte shall continue to act as ex-officio register of deeds of the City of Tacloban until such time as the register of deeds for the City of Tacloban is appointed and has assumed his duties as such.\""}},{"id":"PH-H3761-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Section twenty-seven of the same Act is amended to read as follows:\n\"Sec. 27. The City Treasurer shall purchase and supply in accordance with law, all supplies, equipment, materials and property of very kind including real estate for the use of the city and any of its departments or offices. Contracts for completed work of any kind for the use of the city or any of its departments or offices, involving both labor and materials, where the materials are furnished by the contractor shall be purchased directly and paid for by the city subject to the provisions of existing auditing rules and regulations."}},{"id":"PH-H3761-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"The first paragraph of Section twenty-nine of the same Act is amended to read as follows:\n\"Sec. 29. The City Treasurer—His powers and duties.— There shall be a city treasurer who shall have charge of the department of finance and shall act as chief fiscal officer and financial adviser of the city and custodian of its funds. He shall receive a salary of fifteen thousand two hundred pesos per annum regardless of the class of the city, unless a higher rate of compensation is provided by law for the proper class of the city based on its average annual income. He shall have the following general powers and duties:\n\"(a) He shall collect all taxes due the city, all licenses authorized by law or ordinances, all rents due for lands, markets and other property owned by the city, all further charges of whatever nature fixed by law or ordinance; and shall receive and issue receipts for all costs, fees, fines and forfeitures imposed by the city court.\n\"(b) He shall collect all miscellaneous charges made by the engineering department and by other departments of the city government, and all charges made by the city engineer for inspections, permits, licenses, and the installations, maintenance and services rendered in the operation of the private privy system.\n\"(c) He, as deputy of the Commissioner of Internal Revenue, shall collect by himself or his deputies, all taxes and charges imposed by the Government of the Republic of the Philippines upon persons or property in the city, depositing daily such collections in any depository bank of the government.\n\"(d) Unless otherwise specifically provided by law or resolution, he shall perform in and for the city the duties imposed by law or resolution upon provincial treasurers in general as well as other duties imposed upon him by law.\n\"(e) He shall purchase and issue all supplies, equipment or other property required by the city, as may be authorized, subject to the general provisions of law relating thereto.\n\"(f) He shall be accountable for all funds and property of the city and shall render such accounts in connection therewith as may be prescribed by the Auditor General.\n\"(g) He shall deposit all city funds and collections in any bank duly designated as Government depository in accordance with existing rules and regulations.\n\"(h) He shall disburse the funds of the city in accordance with duly authorized appropriations, upon properly executed vouchers bearing the certification as to the veracity and correctness of the claim of the chief of the department concerned and the approval of the mayor, and on or before the twentieth day of each month he shall furnish the Mayor and the Municipal Board, for their information, a statement of the appropriations, expenditures, and balances of all funds and accounts as of the last day of the month preceding.\""}},{"id":"PH-H3761-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"The same Act is amended by inserting between Sections twenty-nine and thirty thereof a new section to be known as Section twenty-nine-A to read as follows:\n\"Sec. 29.-A. The Assistant City Treasurer; Other Key Personnel.— There shall be an assistant city treasurer who shall act as city treasurer in the absence or incapacity of the city treasurer, and shall perform such duties as may be imposed upon him by the city treasurer or prescribed by law, ordinance, and regulations of the Department of Finance. He shall be appointed by the Mayor upon the recommendation of the city treasurer and subject to the approval of the proper Department Head and the attestation of the Commissioner of Civil Service. The assistant city treasurer shall receive a salary of nine thousand pesos per annum.\n\"Besides the assistant city treasurer who heads the administrative division of the city treasurer’s office, there shall be the following subordinate key personnel who shall be appointed by the Mayor upon recommendation of the city treasurer in accordance with the Civil Service Law and rules, and whose salaries shall be fixed for key personnel in the various offices of the local governments by administrative or executive order of the President and which administrative or executive order shall have the force of law in considering the salaries of the position therein enumerated, to wit: administrative deputy; senior deputy; junior deputy; market administrator as chief of the markets and slaughterhouse division; chiefs and assistant chiefs of the cash, accounting, city license and fees, property, land tax, and correspondence and records division; chiefs and assistant chiefs of sections under the various division.\""}},{"id":"PH-H3761-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"Section thirty of the same Act is amended to read as follows:\n\"Sec. 30. The City Engineer—His Powers and duties.— There shall be a city engineer who shall have charge of the department of engineering and public works. He shall receive a salary of not less than fifteen thousand two hundred pesos per annum. He shall have the following powers and duties:\n\"(a) He shall have charge of all the surveying and engineering works of the city; maintain and repair city streets and bridges and shall perform such services in connection with public improvements or any work entered upon or projected by the city, or any department thereof, which may require the skill and experience of a civil engineer.\n\"(b) He shall have charge of constructions, repair and maintenance of all public highways and bridges, and public works, both city and national, located within the territorial jurisdiction of the city, except those that pertain to the NAWASA and the National Irrigation Administration.\n\"(c) He shall ascertain, record and establish monuments of the city survey and from thence extend the surveys of the city, and locate, establish, and survey all city property and also private property abutting on the same, whenever directed by the Mayor.\n\"(d) He shall prepare and submit plans, maps, specifications and estimates for buildings, streets, bridges, docks and other public works, and supervise the construction and repair of the same.\n\"(e) He shall make such tests and inspections of engineering materials used in construction and repair, as may be necessary, to protect the city from the use of materials of a poor or dangerous quality.\n\"(f) He shall have the care of all public buildings, when erected, including markets and slaughterhouses and all buildings rented for city purposes, and of any system now or hereafter established by the city for lighting the streets, public places or public buildings.\n\"(g) He shall have the care and custody of all public docks, wharves, piers, levees and landing places owned by the city.\n\"(h) He shall prevent the encroachment of private buildings and fences on streets and public places of the city.\n\"(i) He shall have general supervision and inspection of all private docks, wharves, piers, levees, and landing places, and other property bordering on the harbor, river, esteros, and waterways of the city, and shall issue permits for the construction, repair and removal of the same, and enforce all ordinances relating to the same.\n\"(j) He shall have the care and custody of the public system of waterworks and all sources of water supply, and shall control, maintain and regulate the use of the same in accordance with the ordinance relating thereto; shall inspect and regulate the use of all private systems for supplying water to the city and its inhabitants, and all private sewers and their connections with the public sewer system.\n\"(k) He shall supervise the laying of the mains and connections for the purpose of supplying gas to the inhabitants of the city.\n\"(l) He shall inspect and report upon the conditions of public property and public works whenever required so by the Mayor.\n\"(m) He shall supervise and regulate the location and use of engines, boilers, forges and other manufacturing and heating appliances in accordance with law and ordinance relating thereto. He is authorized to charge fees, at rates to be fixed by the Municipal Board, for the sanitation and transportation services and supplies furnished by his department.\n\"(n) He shall inspect and supervise the construction, repair, removal and safety of private buildings, and regulate and enforce the numbering of houses, in accordance with the ordinance of the city.\n\"(o) With the previous approval of the Mayor in each case, he shall order the removal of buildings and structures erected in violation of the ordinances; shall order the removal of the materials employed in the construction or repair of any building or structure made in violation of said ordinances; and shall cause buildings and structures dangerous to the public to be made secure or torn down.\n\"(p) He shall file and preserve all maps, plans, notes, surveys, and other papers and documents pertaining to his office.\""}},{"id":"PH-H3761-A27","no":27,"noLabel":{"en":"Section 27."},"text":{"en":"Section thirty-one of the same Act is amended to read as follows:\n\"Sec. 31. The Assistant City Engineer.— There shall be an assistant city engineer who shall assist the city engineer in the discharge of his official duties. He shall be appointed by the Mayor, upon the recommendation of the city engineer and subject to the approval of the Secretary of Public Works and Communications. He shall receive a salary of not less than nine thousand pesos per annum. In the absence of the city engineer, the assistant city engineer shall assume his powers and duties.\""}},{"id":"PH-H3761-A28","no":28,"noLabel":{"en":"Section 28."},"text":{"en":"Section thirty-two of the same Act is amended to read as follows:\n\"Sec. 32. Execution of authorized public works and improvements.— All repair or construction of any work or public improvement, except parks, boulevards, streets or alleys, involving an estimated cost of fifteen thousand pesos or more shall be awarded by the Mayor upon the recommendation of the city engineer to the lowest responsible bidder after public advertisement by posting notices of the call for bids in conspicuous places in the City Hall and other public places, which shall not be less than ten days duration: Provided, However, That the city engineer may, upon approval of the Secretary of Public Works and Communications, execute by administration any such public works costing fifteen thousand pesos or more.\n\"In case of public works involving an expenditure of less than fifteen thousand pesos, it shall be discretionary with the city engineer either to proceed with the work himself or to let the contract to the lowest bidder after such publication and notices as shall be deemed appropriate or as may be, by regulations, prescribed.\""}},{"id":"PH-H3761-A29","no":29,"noLabel":{"en":"Section 29."},"text":{"en":"Section thirty-three of the same Act is amended to read as follows:\n\"Sec. 33. The City Fiscal and Assistant City Fiscals.— There shall be in the office of the city fiscal one chief to be known as the city fiscal, an assistant chief to be known as the first assistant city fiscal, two second assistant city fiscals who shall be the chiefs of divisions and three assistant city fiscals who shall discharge their duties under the general supervision of the city fiscal and the Secretary of Justice. To be eligible for appointment as city fiscal, one must be a citizen of the Philippines and must have practiced law in the Philippines for a period of not less than ten years or held, during a like period, an office in the Philippine Government requiring admission to the practice of law as an indispensable requisite. To be eligible for appointment as assistant fiscal one must be a citizen of the Philippines and must have practiced law in the Philippines for at least five years prior to his appointment or held during a like period an office in the Philippine Government requiring admission to the practice of law as an indispensable requisite.\n\"The city fiscal and his assistants shall receive the salaries hereinafter set forth:\n\"(a) City fiscal, fifteen thousand two hundred pesos per annum, of which seven thousand two hundred pesos shall be paid by the city government and eight thousand pesos shall be paid by the National Government.\n\"(b) First assistant city fiscal, eleven thousand five hundred pesos per annum, of which four thousand eight hundred pesos shall be paid by the city government and six thousand seven hundred pesos shall be paid by the National Government.\n\"(c) Two second assistant city fiscals who shall be chiefs of two divisions, ten thousand eight hundred pesos per annum each, of which four thousand two hundred pesos each shall be paid by the city government and six thousand six hundred pesos each shall be paid by the National Government.\n\"(d) Three assistant city fiscals, nine thousand six hundred pesos per annum each, of which three thousand six hundred pesos each shall be paid by the city government and six thousand pesos each shall be paid by the National Government.\""}},{"id":"PH-H3761-A30","no":30,"noLabel":{"en":"Section 30."},"text":{"en":"The same Act is amended by inserting between Sections thirty-four and thirty-five thereof a new section to be known as Section thirty-four-A to read as follows:\n\"Sec. 34-A. Organization of the office into two divisions.— To promote a more efficient performance of the functions and duties of the office, the city fiscal shall organize said office into two divisions as follows:\n\"(a) Preliminary Investigation Division, which shall have executive charge of the conduct of preliminary investigations of all crimes and violations of city ordinances.\n\"(b) Prosecution Division, which shall have exclusive charge of the prosecution of criminal cases.\n\"The city fiscal shall effect from time to time such changes in the organization of the said two divisions as the exigencies of the service demand. This organization shall be without prejudice to the power of the city fiscal to designate any single assistant fiscal or group of assistant fiscals to investigate and also prosecute the same case or cases.\""}},{"id":"PH-H3761-A31","no":31,"noLabel":{"en":"Section 31."},"text":{"en":"Section thirty-five of the same Act is amended to read as follows:\n\"Sec. 35. The City Health Officer—His powers and duties.— There shall be a city health officer who shall have charge of the Department of Health and who shall receive a salary of not less than twelve thousand six hundred pesos per annum. He shall have the following powers and duties:\n\"(a) He shall have general supervision over the health and sanitary conditions of the city, including the cleaning of crematories and cemeteries.\n\"(b) He shall execute and enforce all laws, ordinances and regulations relating to public health.\n\"(c) He shall recommend to the Municipal Board the passage of such ordinances as he may deem necessary for the preservation of public health.\n\"(d) He shall cause to be prosecuted all violations of sanitary laws, ordinances or regulations.\n\"(e) He shall make sanitary inspections and may be aided therein by such members of the police force of the city or the national police as shall be designated as sanitary police by the chief of police or national police officer and such sanitary inspectors as may be authorized by law.\n\"(f) He shall act as the local civil registrar ex-officio of the City of Tacloban and shall keep a civil register for the city and shall record therein all births, marriages and deaths with their respective dates. As such ex-officio he shall receive additional compensation not exceeding one thousand eight hundred pesos per annum payable from the funds of the city.\n\"(g) He shall have control and supervision over puericulture centers, and government hospitals of the city.\n\"(h) He shall perform such other duties, not repugnant to law or ordinance, with reference to the health and sanitation of the city, as the Director of Health Services shall direct. In case of epidemic or when the inhabitants of the city are menaced by any infectious or contagious disease, the Director of Disease Control shall assume full control of the health and sanitation services of the city until such condition shall have ceased to exist.\""}},{"id":"PH-H3761-A32","no":32,"noLabel":{"en":"Section 32."},"text":{"en":"Section thirty-six of the same Act is amended to read as follows:\n\"Sec. 36. The Assistant City Health Officer.— There shall be an assistant city health officer who shall act as city health officer in the absence or incapacity of the city health officer, and shall perform such other duties as may be imposed upon him by the city health officer or prescribed by law or ordinance. He shall be appointed by the Secretary of Health upon the recommendation of the city health officer and the city Mayor and shall receive a salary of not less than eight thousand seven hundred pesos per annum.\""}},{"id":"PH-H3761-A33","no":33,"noLabel":{"en":"Section 33."},"text":{"en":"The same Act is amended by inserting between Sections thirty-six and thirty-seven a new section to be known as Section thirty-six-A to read as follows:\n\"Sec. 36-A. The Sanitary Engineer.— There shall be a sanitary engineer who shall assist the city health officer and the assistant city health officer in the performance of their duties. He shall particularly screen all applications for building construction, public and private, and for the construction of the drainage and sewerage systems in the city. He shall advise the city health officer from time to time as regards the environmental sanitation of the city. He shall receive a salary of not exceeding seven thousand two hundred pesos per annum.\""}},{"id":"PH-H3761-A34","no":34,"noLabel":{"en":"Section 34."},"text":{"en":"Section thirty-seven of the same Act is amended to read as follows:\n\"Sec. 37. The Chief of Police—His powers and duties.— There shall be a chief of police who shall have charge of the police department and shall receive a salary of not less than ten thousand two hundred pesos per annum. He shall have the following powers and duties:\n\"(a) He may issue supplementary regulations not incompatible with law or general regulations promulgated by the proper department head of the National Government in accordance with law, for the government of the city police and detective force.\n\"(b) He shall quell riots, disorders, disturbances of the peace, and shall arrest and prosecute through the city fiscal, violators of any law or ordinance; shall exercise exclusive police supervision over all land and water within the police jurisdiction of the city; shall be charged with the protection of the rights of persons and property wherever found within the jurisdiction of the city, and shall arrest when necessary to prevent the escape of the offender, violators of any or ordinance, and all who obstruct or interfere with him in the discharge of his duty; shall have charge of the city prison; and shall be responsible for the safekeeping of all prisoners until they shall be released from custody, in accordance with law, or delivered to the warden of the proper prison or penitentiary.\n\"(c) He may take good and sufficient bail for the appearance before the judge of the municipal court of any person arrested for violation of any city ordinance: Provided, However, That he shall not exercise this power in cases of violations of any penal law, except when the fiscal of the city shall so recommend and fix the bail to be required of the persons arrested.\n\"(d) He shall have authority, within the police limits of the city, to serve and execute criminal processes of any court.\n\"(e) He shall be the deputy sheriff of the city, and as such, shall, personally or by representative, attend the sessions of the municipal court, and shall execute promptly and faithfully, all writs and processes of said court.\n\"(f) He shall exercise supervision over the police training school established in accordance with the rules and regulations of the police department.\n\"(g) He shall have such further powers and perform such further powers and duties as may be prescribed by law or ordinance.\n\"(h) He shall have the power to transfer any member of the police department from one division or section to another as the needs and exigencies of the service and public interest may require.\""}},{"id":"PH-H3761-A35","no":35,"noLabel":{"en":"Section 35."},"text":{"en":"Section thirty-eight of the same Act is amended to read as follows:\n\"Sec. 38. The assistant chief of police.— There shall be an assistant chief of police whose duties shall be to act as chief in the absence or incapacity of the chief of police, and, under the direction of the chief of police, to look after the discipline of the police force and perform such other duties as may be imposed upon him by the chief or prescribed by law or ordinance. He shall receive a salary of not less than seven thousand two hundred pesos per annum.\""}},{"id":"PH-H3761-A36","no":36,"noLabel":{"en":"Section 36."},"text":{"en":"The second paragraph of Section thirty-nine of the same Act is amended to read as follows:\n\"The chief of the secret service shall receive a salary of not less than seven thousand two hundred pesos per annum.\""}},{"id":"PH-H3761-A37","no":37,"noLabel":{"en":"Section 37."},"text":{"en":"Section forty of the same Act is amended to read as follows:\n\"Sec. 40. Peace officers—Their powers and duties.— The Mayor, the chief of police, the deputy chief of police, the chief of the secret service, and all officers and members of the city police and detective force shall be peace officers. Such peace officers are authorized to serve and execute all processes of the municipal court and court criminal processes of all other courts to whomsoever directed within the jurisdictional limits of the city or within the police limits as hereinbefore defined; within the same territory, to pursue and arrest, without warrant, any person found in suspicious places or under suspicious circumstances reasonably tending to show that such person has committed, or is about to commit, any crime or breach of the peace; to arrest or cause to be arrested, without warrant, any offender when the offense is committed in the presence of a peace officer or within his view; and in such pursuit or arrest, to enter any building, ship, boat or vessel or take into custody any person therein suspected of being concerned in such crime or breach of the peace, and any property suspected of having been stolen; and to exercise such other powers and perform such other duties as may be prescribed by law or ordinance. They shall detain an arrested person only in accordance with the provisions of existing laws relative to such detention. Whenever the Mayor shall deem it necessary to avert danger or to protect life and property, in case of riot, disturbance, or public calamity, or when he has reason to fear any serious violation of law and order, he may call upon the provincial commander or other members of the Armed Forces of the Philippines. Except upon the occurrence of any of such conditions, police jurisdiction and supervision and the preservation of peace and order shall pertain exclusively to the peace officers herein mentioned, and no other officers, members of the Armed Forces and Philippine Constabulary shall perform or undertake any police function within the jurisdiction of the city except those which are authorized by law to be done in the cases enumerated in the Rules of Court, any existing law to the contrary notwithstanding.\""}},{"id":"PH-H3761-A38","no":38,"noLabel":{"en":"Section 38."},"text":{"en":"The first paragraph of Section forty-one of the same Act is amended to read as follows:\n\"Sec. 41. Chief of Fire Department.— There shall be a chief of fire department who shall have the management and control of all matters relating to the administration, organization, government, discipline and disposition of the fire forces. He shall receive a salary of not less than nine thousand pesos per annum and shall have the following powers and duties.\n\"(a) He shall issue supplementary regulations not incompatible with law or general regulations issued by the proper department head of the National Government in accordance with law, for the governance of the fire force.\n\"(b) He shall have charge of the fire-engine houses, fire engines, hose trucks, hooks and ladders, trucks, and all other fire apparatus.\n\"(c) He shall have full police powers in the vicinity of fires.\n\"(d) He shall have authority to remove or demolish any building or other property whenever it shall become necessary to prevent the spread of fire or to protect adjacent property.\n\"(e) He shall investigate and report to the Mayor the origin and cause of all fires occurring within the city.\n\"(f) He shall inspect all buildings erected or under construction or repair within the city and determine whether they provide sufficient protection against fire and comply with the ordinances relating thereto.\n\"(g) He shall have charge of the city telegraph, telephone, and fire alarm service.\n\"(h) He shall have exclusive power, notwithstanding any law to the contrary, to supervise and regulate the stringing, grounding and installation of wires for all electrical connections with a view to avoiding conflagrations, interference with public traffic, or safety, or the necessary operation of the fire department.\n\"(i) He shall condemn all defective electrical installations and shall take the necessary steps to effect immediate corrective action, informing the Mayor of the action thus taken.\n\"(j) He shall supervise the manufacture, storage, and use of petroleum, gas, acetylene, gunpowder, and other highly combustible matter and explosives.\n\"(k) No permit for the construction or repair of buildings within the city shall be granted unless the plans relative thereto have been approved by the chief of the fire department. He shall have the power to alter or disapprove such plans as do not provide for adequate protection against the occurrence of fires.\n\"(l) He shall have such powers and perform such duties as may further be prescribed by law or ordinance.\n\"(m) He shall have the power to transfer any member of the fire department from one division or section to another as the needs and exigencies of the service and public interest may require.\"\nSection 39 . Section forty-two of the same Act is amended to read as follows:\n\"Sec. 42. Assistant Chief of the Fire Department.— There shall be an assistant chief of the fire department whose duties shall be to act as chief in the absence or incapacity of the chief of the fire department, and, under the direction of the chief of the fire department, to look after the discipline of the fire force and perform such other duties as may be imposed upon him by the chief or prescribed by law or ordinance. He shall be appointed by the Mayor, upon the recommendation of the chief of fire department and shall receive a salary of not less than seven thousand two hundred pesos per annum.\""}},{"id":"PH-H3761-A40","no":40,"noLabel":{"en":"Section 40."},"text":{"en":"Section forty-three of the same Act is amended to read as follows:\n\"Sec. 43. City Electrician.— There shall be a city electrician who shall, under the direction of the chief of the fire department, have charge of the enforcement of all laws, ordinances and regulations relating to electrical connections within the city, and shall perform such other duties as may be assigned to him by the chief of the fire department or prescribed by law or ordinance. He shall be appointed by the City Mayor and shall receive a salary of not less than five thousand four hundred pesos per annum.\""}},{"id":"PH-H3761-A41","no":41,"noLabel":{"en":"Section 41."},"text":{"en":"The first paragraph of Section forty-four of the same Act is amended to read as follows:\n\"Sec. 44. The City Assessor—His powers and duties.— There shall be a city assessor who shall have charge of the department of assessment and who shall receive a salary of fifteen thousand pesos per annum. The City Treasurer shall act as city assessor ex-officio with additional compensation of three thousand pesos per annum until the Municipal Board, by ordinance, provides otherwise, at which time the city assessor shall be appointed as heretofore provided. The City Assessor shall have the following powers and duties.\""}},{"id":"PH-H3761-A42","no":42,"noLabel":{"en":"Section 42."},"text":{"en":"The same Act is amended by inserting between Sections forty-four and forty-five a new section to be known as Section forty-four-A to read as follows:\n\"Sec. 44.-A. The Assistant City Assessor; Other Key Personnel.— There shall be an assistant city assessor who shall act as city assessor in the absence or incapacity of the city assessor, and shall perform such duties as may be imposed upon him by the city assessor or prescribed by law, ordinance, and regulations of the Department of Finance. He shall be appointed by the Mayor upon the recommendation of the city assessor and subject to the approval of the proper Department Head and the attestation of the Commissioner of Civil Service, and shall receive a salary of nine thousand pesos per annum.\n\"Besides the assistant city assessor, who heads the administrative division of the city assessor’s office there shall be the following subordinate key personnel who shall be appointed by the Mayor upon recommendation of the city assessor in accordance with the Civil Service Law and rules and whose salaries shall be the rates of compensation fixed for key personnel in the various offices of the local governments by administrative or executive order of the President of the Philippines, and which administrative or executive order shall have the force of law in considering the salaries of the positions therein enumerated, to wit: chief deputy assessor; senior deputy assessor; junior deputy assessor; chiefs and assistant chiefs of the land appraisal, building appraisal, surveying and tax mapping, and research and statistics divisions: chiefs and assistant chiefs of sections under the various divisions.\""}},{"id":"PH-H3761-A43","no":43,"noLabel":{"en":"Section 43."},"text":{"en":"Section forty-eight of the same Act is amended to read as follows:\n\"Sec. 48. Action in case estate has escaped taxation.— If it shall come to the knowledge of the city assessor that any taxable real estate in the city has escaped listing, it shall be his duty to list and value the same at the time and in the manner provided in the next succeeding section and such real property shall have back taxes assessed against it for the period during which it would have been liable if assessed from the first in proper course but in no case for more than four years prior to the year of the initial assessment and the taxes thus assessed shall be legal and collectible by all the remedies herein provided, and if the failure of the city assessor to assess such taxes at the time when they should have been assessed was due to any fault or negligence on the part of the owner of such property the penalties shall be added to such back taxes as though they had been assessed at the time when they should have been assessed.\""}},{"id":"PH-H3761-A44","no":44,"noLabel":{"en":"Section 44."},"text":{"en":"Section fifty-two of the same Act is amended to read as follows:\n\"Sec. 52. Time and manner of appealing to City Board of Assessment Appeals and composition thereof .— In case any owner of real estate or his authorized agent shall feel aggrieved by any decision of the city assessor under the preceding sections of this Article, such owner or agent may, within thirty days after the entry of such decision, appeal to the City Board of Assessment Appeals. The appeal shall be perfected by filing a written notice of the same with the city assessor, and it shall be the duty of that officer forthwith to transmit the appeal to the City Board of Assessment Appeals with all the written evidence in his possession relating to such assessment and valuation.\n\"There shall be a City Board of Assessment Appeals which shall be composed of the city auditor as chairman, the city engineer, the city register of deeds, and two property owners in the city to be selected by the three city officials above-mentioned as members. The members of the board who are not officials of the city government shall each receive a compensation of twenty pesos for each day of session actually attended, to be paid from the funds of the city. The chairman of the board shall have the power to designate any assistant city official or ranking employee to serve as secretary of the board without additional compensation.\n\"The members of the board who are not officials of the city government shall hold office for a term of five years, unless sooner removed for cause by a majority vote of the other members of the board.\""}},{"id":"PH-H3761-A45","no":45,"noLabel":{"en":"Section 45."},"text":{"en":"The first paragraph of Section fifty-five of the same Act is amended to read as follows:\n\"Sec. 55. Taxes on real estate—Extension and remission of the tax.— A tax, the rate of which shall not exceed two per centum ad valorem to be determined by the Municipal Board whose duty it shall be on or before the fifteenth day of December of each year to fix by resolution the rate of levy for the succeeding year on the assessed value of all real estate in the city subject to taxation. All taxes on real estate for any year shall be due and payable annually within the first fifteen days of January and from this date such taxes together with all penalties accruing thereto shall constitute a lien on the property subject to such taxation."}},{"id":"PH-H3761-A46","no":46,"noLabel":{"en":"Section 46."},"text":{"en":"Section sixty-one of the same Act is amended to read as follows:\n\"Sec. 61. Vesting title to real estate in the city government.— After the expiration of the year for which the tax is due, and in the event of continued default in the payment of the tax and penalty, all private rights, titles and interest in and to the real estate on which said tax is delinquent shall be indefeasibly vested in the city government, subject only to the rights of redemption and repurchase as hereinafter provided for: Provided, That the title acquired by said city government to the real estate shall not be superior to the title thereto of the original owner prior to the seizure thereof.\""}},{"id":"PH-H3761-A47","no":47,"noLabel":{"en":"Section 47."},"text":{"en":"The same Act is amended by rearranging Sections sixty-four, sixty-five, sixty-six, sixty-seven, sixty-eight, sixty-nine and seventy thereof and inserting therein a new section to be known as Section 67-A, to read as follows:\n\"Sec. 64. Notice of sale of real estate at public auction.— At any time after the forfeiture of any real estate shall have become absolute, the treasurer, pursuant to the rules of procedure to be promulgated by the Department Head, may announce the sale of the real estate seized on account of delinquency on the payment of the taxes thereon, for the redemption of which no application has been filed. Such announcement shall be made by posting a notice for three consecutive weeks at the main entrances of the city hall and all the municipal buildings of the province, in either English or Spanish, and in the dialect commonly used in the locality, and by publishing the same once a week for three consecutive weeks in a newspaper of general circulation in the city. Copies of such notice shall be sent immediately by registered mail to the delinquent taxpayer at the latter’s home address if known. The notice shall state the amount of the taxes and penalties so due, the time and place of sale, the name of the taxpayer against whom the taxes are levied, and the appropriate area, the lot number and the location by district and street and the street number and district or barrio where the real estate to be sold is located.\"\n\"Sec. 65. Sale of real estate, conditions.— At any time during the sale or prior thereto, the taxpayer may stay the proceedings by paying the taxes and penalties due on the property to the city treasurer or his deputy, otherwise the sale shall proceed and shall be held either at the main entrance of the city hall or on the premises of the real estate to be sold as the city treasurer or his deputy may determine. Payment of the sale price shall be in full and for cash and in no case shall such price be less than the taxes and penalties due and the costs of sale.\n\"The city treasurer or his deputy shall make a report of the sale to the Municipal Board within five days after the sale and shall make the same appear on its records. The purchaser at the sale shall receive from the city treasurer or his deputy a certificate showing the proceedings of the sale, describing the property sold, stating the name of the purchaser, the sale price, the conditions of payment the amount paid and the exact amount of the taxes and penalties.\n\"Sec. 66. Redemption of real property before sale.— After the title of the property shall have become vested in the city government in the manner provided for in the preceding sections, and at any time prior to the sale the original owner or his authorized representative or any person having any lien, right or other legal interest or equity in said property, shall have the right to redeem the entire property in question by paying the full amount of the taxes and penalties due thereon at the time of the seizure.\n\"Sec. 67. Redemption of real estate after sale.— Within one year from and after the date of sale, the delinquent taxpayer or any other person in his behalf, shall have the right to redeem the property sold by paying to the city treasurer or his deputy the amount of the taxes, penalties, cost and interest at the rate of twelve per centum on the purchase price, if paid in whole or in any portion thereof as may have been paid by the purchaser, and such payment shall invalidate the certification of sale issued to the purchaser, if any, shall entitle the person making such payment to a certificate to be issued by the city treasurer or his deputy, stating that he has thus redeemed the property, and the city treasurer or his deputy upon the return by the purchaser of the certificate of sale previously issued to him, shall forthwith refund to the purchaser the entire sum paid by him with interest at twelve per centum per annum, as provided for herein, and such property shall thereafter be free from the lien of such taxes or penalties.\n\"Sec. 67-A. Possession and usufruct of real property within one year from date of sale.— After the sale and before repurchase, or before the expiration of one year hereinabove fixed for such repurchase, the real property shall remain the possession of the delinquent taxpayer who shall have the right to the usufruct thereof.\n\"Sec. 68. Taxes and penalties which shall be paid upon redemption on repurchase.— The taxes and penalties to be paid by way of redemption or repurchase, shall comprise in all cases only the original tax by virtue of failure to pay which the seizure was made, and its incidental penalties, up to the date of the forfeiture of the real estate to the government.\n\"Sec. 69. Execution of deed of final sale.— In case the delinquent taxpayer shall not redeem the property sold as herein provided within one year from the date of the sale, and the purchaser shall then have paid the total purchase price, the city treasurer as grantor, shall execute a deed in form and effect sufficient to convey to the purchaser so much of the real estate against which the taxes have been assessed as has been sold, free from all liens or encumbrances, of any kind whatsoever, and said deed shall succinctly recite all the proceedings upon which the validity of the sale depends. Any balance remaining from the proceeds of the sale, after deducting the amount of the taxes and penalties due, and the costs, if any, shall be returned to the original owner or his representatives.\n\"Sec. 70. Ejectment of occupants of seized property.— If after issuance of the final bill or deed of sale hereinabove referred to, the purchaser of the real property shall not be allowed to enter and take possession of the property subject of the deed of final sale, the city treasurer or his deputy shall issue to the Police Department, thru the Mayor, a certificate describing the parcel of real estate covered by the deed of final sale, stating the fact of its having been sold to the purchaser, and requesting the police to eject from said property all the tenants and occupants thereof. Upon receiving such certificate the police shall forthwith have all the tenants and occupants who refuse to recognize the title of the city and of the purchaser, expelled from the property in question and to place in possession the purchaser thereof: Provided, However, That if the property so seized is or includes a residential home, the occupant thereof shall be given sufficient time, not exceeding one month from the date of the notice of ejectment, to vacate the premises.\""}},{"id":"PH-H3761-A48","no":48,"noLabel":{"en":"Section 48."},"text":{"en":"The same Act is amended by inserting between Sections seventy-one and seventy-two thereof the following sections which shall read as follows:\nDepartment of General Services \"Sec. 71-A. The City General Services Officer.— There shall be a city general services officer who shall either be a civil engineer, sanitary engineer or architect and who shall exercise general supervision and control over all the offices and services under this department. He shall have a salary of not less than nine thousand six hundred pesos per annum and shall have the following powers and duties:\n\"(a) He shall issue supplementary regulations not incompatible with laws or general regulations issued by the proper department head of the National Government in accordance with law, for general services.\n\"(b) Subject to the approval of the Mayor, he shall assign the personnel under his office to the various offices and services as the public interest may required in accordance with the ordinance related thereto.\n\"(c) He shall have charge of the care, cleaning and sprinkling of streets, canals and esteros, parks and public buildings, recreation and playground and maintenance of city drainage structures, illumination services, maintenance and repair of public buildings and athletic fields owned by the city; care and to regulate the use of all monuments and parks.\n\"(d) He shall have charge of city cultural services, including the organization and management of the city band, installation of arches and stages in connection with the participation of the city in all social services.\n\"(e) He shall have general supervision and control over the administration and cleanliness of markets, cold storages and slaughterhouses owned and operated by the city, except with respect to fiscal matters which shall be under the exclusive control of the city treasurer. He shall see to it that all the provisions of the market code are strictly complied with by all those concerned.\n\"(f) He shall take charge of the motor pool service to maintain and service all motor vehicles, and/or engines and mechanical devices which belong to the city except those under the fire department and the city engineer.\n\"(g) He shall exercise general supervision over the collection and disposal of all garbage, refuse, the contents of closets, vaults and cesspools, and all other offensive and dangerous substances within the city, including operation and maintenance of a city garbage treatment plan and, in the event the disposal and collection of such garbage, refuse and other offensive substances have been awarded to a private contractor, the disposal and collection thereof shall be under the supervision of the city general services officer.\n\"(h) He shall have charge of the cleaning of sanitary and storm sewers including the management and supervision of sewage treatment plants operated by the city.\n\"(i) He shall have general supervision and control over the sanitary building and plumbing inspection service; care, custody and cleaning of all public buildings rented for city purposes; public toilets; collection and disposal of garbage, refuse, contents of toilets and cesspools, and all other offensive and dangerous substances within the city.\n\"(j) He shall have authority to declare that any lot or ground within the City of Tacloban belonging to any person or corporation or to the National Government or any branch or political subdivision thereof, is so low, excavated or walled, diked or dammed as to admit or cause the formation on the surface thereof of stagnant or foul water, or that it is a nuisance or a menace to public health, unless filled in or its sanitary condition otherwise improved, and shall communicate same to the Mayor.\n\"(k) He shall recommend to the Municipal Board the passage of ordinances as he may deem necessary for the better and more adequate extension of public service.\n\"Sec. 71-B. The Assistant City General Services Officer.— There shall be an assistant city general services officer in the discharge of his official duties. He shall be appointed by the Mayor upon the recommendation of the city general services officer subject to the provisions of the Civil Service Law. He shall receive a salary of not less than seven thousand two hundred pesos per annum. In the absence of the city general services officer, the assistant city general services officer shall assume his duties and powers.\""}},{"id":"PH-H3761-A49","no":49,"noLabel":{"en":"Section 49."},"chapter":{"en":"ARTICLE XIII -A"},"text":{"en":"Section eighty-six of the same Act is amended to read as follows:\n\"Sec. 86. Annual Budget.— At least four months before the beginning of each fiscal year, the city treasurer shall present to the Mayor a certified detailed statement by department of all receipts and expenditures of the city pertaining to the preceding fiscal year, and to the first seven months of the preceding fiscal year, and to the first seven months of the current fiscal year together with an estimate of the receipts and expenditures for the remainder of the current fiscal year; and he shall submit with this statement a detailed estimate of the revenues and receipts of the city from all sources for the ensuring fiscal year. Upon receipt of this statement and estimate and the estimate of department heads as required by Section twenty-one of this Charter, the Mayor shall formulate and submit to the Municipal Board at least two and a half months before the beginning of the ensuing fiscal year, a detailed budget covering the estimated necessary expenditures for the said ensuing fiscal year, which shall be the basis of the annual appropriation ordinance: Provided, However, That in no case shall the aggregate amount of such appropriation exceed the estimate of revenues and receipts submitted by the city treasurer as provided above: And Provided, further, That the expenditure allowed for salaries and wages may exceed the percentage authorized by law if the excess is due to the implementation of a law fixing the salaries of city officials and employees or as a consequence of salary adjustments to conform to or approximate the standards set by the Wage and Position Classification Office.\""}},{"id":"PH-H3761-A50","no":50,"noLabel":{"en":"Section 50."},"chapter":{"en":"ARTICLE XIII -A"},"text":{"en":"The same Act is amended by inserting between Sections eighty-seven and eighty-eight thereof a new section to be known as Section eighty-seven-A to read as follows:\n\"Sec. 87-A. Effectivity.— Any provision of existing law or regulations to the contrary notwithstanding and provided, that the city budget appropriates an aggregate amount not exceeding the estimated tax receipts and/or income for the ensuing year, certified collectible by the city treasurer, and Provided, That provisions have been made for the statutory and/or current contractual obligations of the city: And Provided, further, That no official or employee shall receive a salary higher than the maximum salary provided by existing salary laws the city budget shall be in full force and effect on the date therein fixed for its effectivity by the Municipal Board with the approval of the City Mayor.\n\"Copies of the city budget shall be furnished the Secretary of Finance within ten days after its approval, who shall have the power to review the budget in order to see to it that the above provisions and conditions have been complied with. If within thirty days after submission to the Secretary of Finance, the Secretary takes no action, the said budget shall the deemed to have complied with the above provisions. If within thirty days after submission of the budget, upon examination thereof, the Secretary of Finance shall determine that the provisions of the salary laws have been violated, he shall advise in writing the city treasurer who shall, upon receipt of such advise, make no further disbursements beyond the maximum amounts provided for in the salary laws for the item in question, unless the budget shall have been corrected and revised to meet the objections presented in said advice, and until such corrections or revision shall have been submitted to and approved by the Secretary of Finance, which approval may not be unreasonably withheld.\n\"Upon ascertaining that the city budget has not made provisions for all statutory and/or current contractual obligations of the city or that said budget has appropriated an aggregate amount exceeding the estimated tax receipts or income for the ensuing year, the Secretary of Finance shall, within thirty days after receipt of the city budget, have the power to declare the same as inoperative and to return the budget forthwith to the city mayor for proper adjustment, in which event the city shall operate on the previous year’s budget until such time as a new budget shall have been made meeting the objections presented by the Secretary of Finance.\""}},{"id":"PH-H3761-A51","no":51,"noLabel":{"en":"Section 51."},"chapter":{"en":"ARTICLE XIII -A"},"text":{"en":"The same Act is amended by inserting between Sections eighty-nine and ninety, thereof, a new section to be known as Section eighty-nine-A, to read as follows:\n\"Sec. 89-A. Supervision of District Judges over the City Judges of the City Courts—Annual Report of Judge.— The presiding judge of the Court of First Instance of the City of Tacloban, or if there be none, the executive judge of the court of first instance with permanent station in the City of Tacloban, under Section fifty-two of Republic Act Numbered Two hundred ninety-six, as amended, shall at all times, exercise supervision over city judges of the city courts of Tacloban, and shall keep himself informed of the manner in which they perform their duties, by personal inspection whenever possible, from reports which he may require from them, from cases appealed to his court, and from all other available sources. In proper cases he shall advise and instruct them whenever requested or when the occasion arises, and such city judges shall apply to him and not to the Secretary of Justice for advice and instruction and any such inquiries received by the Secretary of Justice shall be referred by him to the executive judge of the court of first instance.\n\"Every city judge, shall, during the first thirty days of the fiscal year, forward to the presiding and/or district judge a report concerning the business done in his court for the previous year, upon forms to be prescribed by the presiding judge or executive judge. Such report shall be filed in the office of the clerk of court of the presiding judge or the executive judge, as the case may be, and said presiding judge or executive judge shall, with the assistance of his clerk, embody a summary of such reports in his report as prescribed by the Secretary of Justice.\""}},{"id":"PH-H3761-A52","no":52,"noLabel":{"en":"Section 52."},"chapter":{"en":"ARTICLE XIII -A"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Certain Provisions of Republic Act Numbered Thirty Hundred Sixty-Eight, Known as the Revised Charter of the City of Tacloban, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3762"] = {"id":"PH-H3762","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4777_1966.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"修订第3655号共和国法（题为“设立百岛保护与开发管理局、界定其权力、职责与责任并为其他目的”）第2条与第4条","en":"An Act Amending Sections Two and Four of Republic Act Numbered Three Thousand Six Hundred Fifty-Five, Entitled \"An Act to Create the Hundred Islands Conservation and Development Authority, Defining its Powers, Duties and Responsibilities, and for Other Purposes\"","orig":"An Act Amending Sections Two and Four of Republic Act Numbered Three Thousand Six Hundred Fifty-Five, Entitled \"An Act to Create the Hundred Islands Conservation and Development Authority, Defining its Powers, Duties and Responsibilities, and for Other Purposes\"","vi":"Đạo luật sửa đổi các Điều 2 và 4 của Đạo luật Cộng hòa số 3655, và cho các mục đích khác","th":"พระราชบัญญัติแก้ไขเพิ่มเติมมาตรา 2 และ 4 แห่งพระราชบัญญัติแห่งสาธารณรัฐที่ 3655 และเพื่อวัตถุประสงค์อื่น","id":"Undang-Undang mengubah Pasal 2 dan 4 Undang-Undang Republik No. 3655, dan untuk tujuan lain","ms":"Akta meminda Seksyen 2 dan 4 Akta Republik No. 3655, dan untuk tujuan lain"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4777","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4777_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3762-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section two of Republic Act Numbered Three thousand six hundred fifty-five is hereby amended to read as follows:\n\"Sec. 2. The governing body of the Hundred Islands Conservation and Development Authority shall be composed of the Secretary of Public Works and Communications, as chairman, and the Commissioner of Tourism, the Fisheries Commissioner, Director of Plant Industry and the District Engineer of Pangasinan, as members, and the last three shall at the same time serve as Directors of the Park Resources Conservation, Horticulture and Development, respectively. This body shall be entrusted with the administration of the domain of the Authority and empowered to appoint its staff and personnel as well as to provide its own rules for the conduct of its business.\""}},{"id":"PH-H3762-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section four of the same Act is hereby amended to read as follows:\n\"Sec. 4. The sum of five hundred thousand pesos is hereby appropriated, out of the funds of the National Treasury, for the use of the Hundred Islands Conservation and Development Authority, which shall be made available in fiscal year nineteen hundred sixty-three-nineteen hundred sixty-four: Provided, However, That not more than two hundred thousand pesos thereof shall be used to asphalt or pave with concrete portions of the Tarlac-Pangasinan and the Pangasinan-Zambales Roads, including the Poblacion-Lucap Road, leading to Lucap, Alaminos. The same amount shall be appropriated for the same purposes every year during the next succeeding three years. The initial sum may be advanced from any immediately disposable fund of the government to be replaced as soon as the appropriation provided for in this Act is available.\n\"As soon as the Hundred Islands Conservation and Development Authority begins to derive any revenue out of any improvements, establishments or services that it provides or authorizes to operate, such revenue shall be divided as follows: fifty per cent for its own work of maintenance, conservation and development: twenty-five per cent for the provincial government of Pangasinan and the other twenty-five per cent to be distributed among the municipalities bordering the foreshore area in proportion to the length of their respective shorelines included in the area placed under the Authority’s jurisdiction.\""}},{"id":"PH-H3762-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Sections Two and Four of Republic Act Numbered Three Thousand Six Hundred Fifty-Five, Entitled \"An Act to Create the Hundred Islands Conservation and Development Authority, Defining its Powers, Duties and Responsibilities, and for Other Purposes\"","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3763"] = {"id":"PH-H3763","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4778_1966.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Balbalan市","en":"An Act Creating Barrio Balantoy, Municipality of Balbalan, Mountain Province","orig":"An Act Creating Barrio Balantoy, Municipality of Balbalan, Mountain Province"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4778","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4778_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3763-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Sitios Balantoy, Ligayan, Kilayon, Bolo and Nawoy, Municipality of Balbalan, Mountain Province, are constituted into a barrio, to be known as Barrio Balantoy of said municipality."}},{"id":"PH-H3763-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53"};
  FT["PH-H3764"] = {"id":"PH-H3764","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4779_1966.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"为马斯巴特省增设1个Assistant 省立 Fiscal职位，为此修订《行政法典》第1674条（经修正）的法案","en":"An Act Creating One Additional Position of Assistant Provincial Fiscal in the Province of Masbate, Amending for the Purpose Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended","orig":"An Act Creating One Additional Position of Assistant Provincial Fiscal in the Province of Masbate, Amending for the Purpose Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 4779","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4779_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3764-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The provision of Section sixteen hundred seventy-four of the Administrative Code, as amended, relative to the number of assistant provincial fiscals in the Province of Masbate, is amended to read as follows:\n\"Masbate, two assistant provincial fiscals;\""}},{"id":"PH-H3764-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating One Additional Position of Assistant Provincial Fiscal in the Province of Masbate, Amending for the Purpose Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3765"] = {"id":"PH-H3765","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4780_1966.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立制度","en":"An Act Providing for the Establishment, Operation and Maintenance of a Community Hospital in the Municipality of Cataingan, Province of Masbate, to be Known as Cataingan Community Hospital, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Providing for the Establishment, Operation and Maintenance of a Community Hospital in the Municipality of Cataingan, Province of Masbate, to be Known as Cataingan Community Hospital, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 4780","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4780_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3765-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Director of Medical Services, a community hospital in the Municipality of Cataingan, Province of Masbate, to be known as Cataingan Community Hospital. The site shall be determined by the Municipal Council of the Municipality of Cataingan, in consultation with the Director of Medical Services."}},{"id":"PH-H3765-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said hospital during the fiscal year nineteen hundred sixty-seven. Such sums as may be necessary for its operation and maintenance in subsequent years shall be included in the annual General Appropriations Act."}},{"id":"PH-H3765-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53"};
  FT["PH-H3766"] = {"id":"PH-H3766","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4781_1966.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"进一步修订经修正的第186号联邦法的法案","en":"An Act Further Amending Commonwealth Act Numbered One Hundred Eighty-Six, as Amended","orig":"An Act Further Amending Commonwealth Act Numbered One Hundred Eighty-Six, as Amended","vi":"Đạo luật sửa đổi thêm Đạo luật Thịnh vượng chung số 186 như đã được sửa đổi","th":"พระราชบัญญัติแก้ไขเพิ่มเติมอีกพระราชบัญญัติเครือรัฐที่ 186 ซึ่งแก้ไขเพิ่มเติมแล้ว","id":"Undang-Undang mengubah lagi Undang-Undang Persemakmuran No. 186 sebagaimana diubah","ms":"Akta meminda lagi Akta Komanwel No. 186 sebagaimana dipinda"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4781","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4781_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3766-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section ten of Commonwealth Act Numbered One hundred eighty-six, as amended, known as the Government Service Insurance Act, is hereby further amended to read as follows:\n\"Sec. 10. Optional Insurance.— Upon application to the Board and on satisfactory evidence of insurability, each member may obtain, at any time, additional life insurance and/or educational insurance of his minor dependents as he may desire, in multiple of one hundred pesos, subject to such rules and regulations as the Board may prescribe and to the provisions of Section fourteen hereof: Provided, That the full amount of the premiums on such additional life insurance and/or educational insurance shall be paid by said member, and the amount thereof may be deducted from his pay or compensation, when expressly authorized by him.\""}},{"id":"PH-H3766-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Further Amending Commonwealth Act Numbered One Hundred Eighty-Six, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
