  FT["PH-H3772"] = {"id":"PH-H3772","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4787_1966.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"在布基农省设立Lantapan市镇的法案","en":"An Act Creating the Municipality of Lantapan in the Province of Bukidnon","orig":"An Act Creating the Municipality of Lantapan in the Province of Bukidnon","vi":"Đạo luật thành lập Thị trấn Lantapan tại Tỉnh Bukidnon","th":"พระราชบัญญัติจัดตั้งเทศบาล Lantapan ในจังหวัด Bukidnon","id":"Undang-Undang membentuk Kotamadya Lantapan di Provinsi Bukidnon","ms":"Akta mewujudkan Perbandaran Lantapan di Wilayah Bukidnon"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4787","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4787_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3772-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Barrios Bugcaon, Culasihan, Bantuanon, Lantapan, Balila, Baclayon, Alanib, Kaatuan, Songko, Victory, Kibangay, Basak and Kibogtong and the territory west of Cabangahan Creek extending westward up to the present boundary of the Municipalities of Malaybalay and Talakag, all in the Municipality of Malaybalay, Province of Bukidnon, are hereby segregated from said municipality and constituted into a distinct and independent municipality to be known as the Municipality of Lantapan, same province: Provided, That the present barrios Cabangahan and Bangcud will remain with the mother Municipality of Malaybalay, Province of Bukidnon. The seat of government of the new municipality shall be the present site of Barrio Lantapan."}},{"id":"PH-H3772-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The first mayor, vice-mayor and councilors of the new municipality shall be elected in the nineteen hundred sixty-seven general elections for local officials."}},{"id":"PH-H3772-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the Municipality of Lantapan in the Province of Bukidnon","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3773"] = {"id":"PH-H3773","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4788_1966.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"在布基农省设立Kalilangan市镇的法案","en":"An Act Creating the Municipality of Kalilangan in the Province of Bukidnon","orig":"An Act Creating the Municipality of Kalilangan in the Province of Bukidnon","vi":"Đạo luật thành lập Thị trấn Kalilangan tại Tỉnh Bukidnon","th":"พระราชบัญญัติจัดตั้งเทศบาล Kalilangan ในจังหวัด Bukidnon","id":"Undang-Undang membentuk Kotamadya Kalilangan di Provinsi Bukidnon","ms":"Akta mewujudkan Perbandaran Kalilangan di Wilayah Bukidnon"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4788","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4788_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3773-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Barrios Lampanosan, Macatol, Macaopao, Sabang, Kalilangan, Boribod, Pamutohan, Kabaning, Malinoa, Imbariz, Kibaritan and Mayohay in the Municipality of Pangantucan, Province of Bukidnon, are hereby separated from said municipality and constituted into a distinct and independent municipality, with the seat of government in the present site of Barrio Kalilangan. The new municipality shall be known as the Municipality of Kalilangan, same province."}},{"id":"PH-H3773-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The first mayor, vice-mayor and councilors shall be elected in the nineteen hundred sixty-seven general elections for local officials."}},{"id":"PH-H3773-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the Municipality of Kalilangan in the Province of Bukidnon","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3774"] = {"id":"PH-H3774","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4789_1966.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"在布基农省设立San Fernando市镇的法案","en":"An Act Creating the Municipality of San Fernando in the Province of Bukidnon","orig":"An Act Creating the Municipality of San Fernando in the Province of Bukidnon","vi":"Đạo luật thành lập Thị trấn San Fernando tại Tỉnh Bukidnon","th":"พระราชบัญญัติจัดตั้งเทศบาล San Fernando ในจังหวัด Bukidnon","id":"Undang-Undang membentuk Kotamadya San Fernando di Provinsi Bukidnon","ms":"Akta mewujudkan Perbandaran San Fernando di Wilayah Bukidnon"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4789","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4789_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3774-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The barrios and sitios of Abihid, San Alfonso (Tugop), Taga Alas-as, Little Baguio, Halapitan, Kalagutay, Sinanglanganan and Malambago all in the Municipality of Malaybalay, Province of Bukidnon, and the barrios and sitios of Namnam, Iglugsad, Kibungcog, Bonacao, Perino (Plikpakan), Santo Domingo (Dulag), San Jose (Tugda-an) and Ale (Bulalang), all in the Municipality of Maramag, also of the Province of Bukidnon, are hereby segregated from said municipalities and organized into an independent political entity to be known as the Municipality of San Fernando, same province, with the seat of government at the present site of Barrio Halapitan."}},{"id":"PH-H3774-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Municipality of San Fernando shall have the following boundaries:\n\"From the point marked 1 on the plan (Map of Malaybalay and Maramag), showing the proposed Municipality of San Fernando, approved by Civil Engineer Braulio O. Ceniza, (in charge of Office of the District Engineer), to point 2, S. 91° 00 W., 15 kms; thence S. 11° 00 W., 13 kms. to Aga Mountains; thence S. 5° 00 E, 15 kms. to point 4; thence S. 7° 00 E, 14 kms. to point 5; thence N. 75° 00 E, 14 kms. following the provincial boundary of Bukidnon-Cotabato to point 6, thence 38 kms. by following northward through the Kalagangan and Pantaron Mountains to point of beginning.\""}},{"id":"PH-H3774-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The first mayor, vice-mayor and councilors shall be elected in the nineteen hundred sixty-seven general elections for local officials."}},{"id":"PH-H3774-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the Municipality of San Fernando in the Province of Bukidnon","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3775"] = {"id":"PH-H3775","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4790_1966.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"在南拉瑙省设立Dianaton市镇的法案","en":"An Act Creating the Municipality of Dianaton in the Province of Lanao De Sur","orig":"An Act Creating the Municipality of Dianaton in the Province of Lanao De Sur","vi":"Đạo luật thành lập Thị trấn Dianaton tại Tỉnh Lanao De Sur","th":"พระราชบัญญัติจัดตั้งเทศบาล Dianaton ในจังหวัด Lanao De Sur","id":"Undang-Undang membentuk Kotamadya Dianaton di Provinsi Lanao De Sur","ms":"Akta mewujudkan Perbandaran Dianaton di Wilayah Lanao De Sur"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4790","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4790_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3775-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Barrios Togaig, Madalum, Bayanga, Langkong, Sarakan, Kat-bo, Digakapan, Magabo, Tabangao, Tiongko Colodan, Kabamakawan, Kapatagan, Bongabong, Aipang, Dagowan, Bakikis, Bungabung, Losain, Matimos and Magolatung, in the municipalities of Butig and Balabagan, Province of Lanao del Sur, are separated from said municipalities and constituted into a distinct and independent municipality of the same province to be known as the Municipality of Dianaton, Province of Lanao del Sur. The seat of government of the municipality shall be Togaig."}},{"id":"PH-H3775-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The first mayor, vice-mayor and councilors of the new municipality shall be elected in the nineteen hundred sixty-seven general elections for local officials."}},{"id":"PH-H3775-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966"}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the Municipality of Dianaton in the Province of Lanao De Sur","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3776"] = {"id":"PH-H3776","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4791_1966.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Tayug市","en":"An Act Creating a Branch Office of the Register of Deeds of Pangasinan with Permanent Station in the Municipality of Tayug, Province of Pangasinan","orig":"An Act Creating a Branch Office of the Register of Deeds of Pangasinan with Permanent Station in the Municipality of Tayug, Province of Pangasinan","vi":"Đạo luật thành lập Trạm Branch Office of the Register of Deeds of Pangasinan with Permanent tại Thị trấn Tayug, Tỉnh Pangasinan","th":"พระราชบัญญัติจัดตั้งสถานี Branch Office of the Register of Deeds of Pangasinan with Permanent ในเทศบาล Tayug จังหวัด Pangasinan","id":"Undang-Undang membentuk Stasiun Branch Office of the Register of Deeds of Pangasinan with Permanent di Kotamadya Tayug, Provinsi Pangasinan","ms":"Akta menubuhkan Stesen Branch Office of the Register of Deeds of Pangasinan with Permanent di Perbandaran Tayug, Wilayah Pangasinan"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4791","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4791_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3776-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby created a branch office of the Register of Deeds of Pangasinan, with permanent station in the Municipality of Tayug, which shall be under the supervision of a deputy register of deeds who shall perform the duties and functions of the Register of Deeds for the following municipalities, to wit: Asingan, Balungao, San Manuel, Santa Maria, Natividad, San Nicolas, San Quintin, Rosales, Tayug and Umingan."}},{"id":"PH-H3776-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The said branch office shall consist of one deputy register of deeds with a salary of four thousand four hundred four pesos per annum; one senior clerk with a salary of two thousand nine hundred fifty-two pesos per annum; one clerk II with a salary of two thousand six hundred seventy-six pesos per annum; one clerk I with a salary of two thousand four hundred twenty-four pesos per annum; one janitor-messenger with a salary of two thousand one hundred sixty pesos per annum and sundry expenses in the amount of ten thousand pesos."}},{"id":"PH-H3776-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"To carry out the purpose of this Act, twenty-four thousand six hundred sixteen pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the fiscal year nineteen hundred sixty-seven. Thereafter, such sums as may be needed for the same purpose shall be included in the annual General Appropriations Act."}},{"id":"PH-H3776-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53"};
  FT["PH-H3777"] = {"id":"PH-H3777","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4792_1966.html","fetchedAt":"2026-10-06","articleCount":16,"structureMode":"ARTICLE","title":{"zh":"授予 Zoilo Dejaresco，Jr. 在保和省建设、维护和运营电视与无线电广播站的特许经营权法案","en":"An Act Granting Zoilo Dejaresco, Jr., a Franchise to Construct, Maintain and Operate Television and Radio Broadcasting Stations in the Province of Bohol","orig":"An Act Granting Zoilo Dejaresco, Jr., a Franchise to Construct, Maintain and Operate Television and Radio Broadcasting Stations in the Province of Bohol","vi":"Đạo luật cấp quyền khai thác cho Zoilo Dejaresco, Jr. để xây dựng, lắp đặt, vận hành và duy trì hệ thống phát thanh và truyền hình tại tỉnh Bohol","th":"พระราชบัญญัติให้สัมปทานแก่ Zoilo Dejaresco, Jr. เพื่อก่อสร้าง ติดตั้ง ดำเนินการ และบำรุงรักษาระบบวิทยุกระจายเสียงและวิทยุโทรทัศน์ในจังหวัด Bohol","id":"Undang-Undang memberikan waralaba kepada Zoilo Dejaresco, Jr. untuk membangun, memasang, mengoperasikan, dan memelihara sistem penyiaran radio dan televisi di Provinsi Bohol","ms":"Akta memberikan francais kepada Zoilo Dejaresco, Jr. untuk membina, memasang, mengendalikan dan menyelenggara sistem penyiaran radio dan televisyen di Wilayah Bohol"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 4792","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 16 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4792_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3777-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution, Zoilo Dejaresco, Jr. is hereby granted for a period of twenty-five years a franchise to construct, maintain and operate, for commercial purposes and in the public interest, television and radio broadcasting stations in the Province of Bohol: Provided, That this franchise shall be void unless the construction of at least one television station or one radio broadcasting station be begun within four years from the date of approval of this Act, and be completed within five years from said date: Provided, further, That the grantee shall provide adequate public service time to enable the Government, through the said television and radio broadcasting stations, to reach the population on important public issues; shall assist in the functions of public information and education; shall conform to the ethics of honest enterprise; and shall not use his stations for the broadcasting and/or telecasting of obscene or indecent language, speech, act or scene, or for the dissemination of deliberately false information or wilful misrepresentation, or to the detriment of the public health, or the incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H3777-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Such provisions of Act Numbered Thirty-eight hundred forty-six, entitled \"An Act providing for the regulation of radio stations and radio communications in the Philippine Islands, and for other purposes;\" Act Numbered Thirty-nine hundred ninety-seven, known as the Radio Broadcasting Law: Commonwealth Act Numbered One hundred forty-six, known as the Public Service Act, and their amendments, as are applicable to radio broadcasting stations shall be applied, as far as practicable to the television stations referred to in Section one hereof."}},{"id":"PH-H3777-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"As a condition of the granting of this franchise, the grantee shall execute a bond in favor of the Government of the Philippines, in the sum of fifty thousand pesos, in form and with sureties satisfactory to the Secretary of Public Works and Communications, conditioned upon the faithful performance of the grantee’s obligations hereunder during the first three years of the life of this franchise. If, after four years from the date of acceptance of this franchise, the grantee shall have fulfilled said obligations, or as soon thereafter as the grantee shall have fulfilled the same, the bond aforesaid shall be cancelled by the Secretary of Public Works and Communications."}},{"id":"PH-H3777-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Acceptance of this franchise shall be given in writing within six months after the approval of this Act. When so accepted by the grantee and upon approval of the bond aforesaid by the Secretary of Public Works and Communications, the grantee shall be empowered to exercise the privileges granted thereby."}},{"id":"PH-H3777-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The grantee’s radio broadcasting and television station shall not be put in actual operation until the Secretary of Public Works and Communications shall have allotted to the grantee the frequency and wave lengths to be used under this franchise and issued to the grantee a license for such use."}},{"id":"PH-H3777-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"In the event of any competing individual, partnership or corporation receiving from the Congress a similar franchise in which there shall be any term or terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall ipso facto become a part of the terms hereof and shall operate equally in favor of the grantee as in the case of said competing individual, partnership or corporation."}},{"id":"PH-H3777-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"(a) The grantee shall be liable to pay the same taxes on his real estate, buildings and personal property exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay.\n(b) The grantee shall further be liable to pay all other taxes that may be imposed by the National Internal Revenue Code by reason of this franchise."}},{"id":"PH-H3777-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands, or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H3777-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"This franchise hereby granted shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires."}},{"id":"PH-H3777-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"In the event the Government should desire to maintain and operate for itself any or all of the stations herein authorized, the grantee shall turn over such station or stations to the Government with all the serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H3777-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"A special right is reserved to the President of the Philippines in time of war, rebellion, public peril, emergency, calamity, disaster or disturbance of peace and order, to cause the closing of said stations or to authorize the temporary use and operation thereof by any department of the Government upon due compensation to the grantee for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H3777-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The grantee shall not require any previous censorship of any speech play, act or scene or other matter to be broadcast and/or telecast from his stations; but if any such speech, play, act or scene or other matter should constitute a violation of the law or infringement of a private right, the grantee shall be free from any liability, civil or criminal, for such speech, play act or scene or other matter: Provided, That the grantee, during any broadcast and/or telecast, shall cut off from the air the speech, play, act or scene or other matter being broadcast and/or telecast, if the tendency thereof is to propose and/or incite treason, rebellion or sedition, or the language used therein or the theme thereof is indecent or immoral, and wilful failure to do so shall constitute a valid cause for the cancellation of this franchise."}},{"id":"PH-H3777-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise nor the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other company or corporation organized for the purpose, without the previous approval of the Congress of the Philippines. Any corporation to which this franchise is sold, transferred or assigned, shall be subject to all conditions, terms, restrictions and limitations of this franchise as fully and completely and to the same extent as \"if the franchise had been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H3777-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Whenever in this franchise the term \"grantee\" is used, it shall be held and understood to mean Zoilo Dejaresco, Jr., his representatives, successors or assigns, unless the context indicates otherwise."}},{"id":"PH-H3777-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"This franchise shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H3777-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Zoilo Dejaresco, Jr., a Franchise to Construct, Maintain and Operate Television and Radio Broadcasting Stations in the Province of Bohol","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3778"] = {"id":"PH-H3778","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4793_1966.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"修订第406号共和国法（设立矿业特别基金）第1条与第2条的法案","en":"An Act Amending Sections One and Two of Republic Act Numbered Four Hundred and Six, Entitled \"An Act Creating a Mines Special Fund in the Bureau of Mines to be Used for the Canvassing and Evaluation of Mineral Deposits Needed in the Development of Philippine Industries, and the Publication of Mining Statistics and Data, and for Other Purposes\"","orig":"An Act Amending Sections One and Two of Republic Act Numbered Four Hundred and Six, Entitled \"An Act Creating a Mines Special Fund in the Bureau of Mines to be Used for the Canvassing and Evaluation of Mineral Deposits Needed in the Development of Philippine Industries, and the Publication of Mining Statistics and Data, and for Other Purposes\"","vi":"Đạo luật sửa đổi các Điều 1 và 2 của Đạo luật Cộng hòa số 406, và cho các mục đích khác","th":"พระราชบัญญัติแก้ไขเพิ่มเติมมาตรา 1 และ 2 แห่งพระราชบัญญัติแห่งสาธารณรัฐที่ 406 และเพื่อวัตถุประสงค์อื่น","id":"Undang-Undang mengubah Pasal 1 dan 2 Undang-Undang Republik No. 406, dan untuk tujuan lain","ms":"Akta meminda Seksyen 1 dan 2 Akta Republik No. 406, dan untuk tujuan lain"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 4793","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4793_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3778-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one of Republic Act Numbered Four hundred and six is hereby amended to read as follows:\n\"Sec. 1. There is hereby created a \"Mines Special Fund\" in the Bureau of Mines for the purpose of carrying out investigations and surveys to canvass, locate, and evaluate deposits of minerals needed in the development of Philippine industries; geological, geophysical, geochemical, topographical and mineralogical surveys; metallurgical and pilot plant testing of ores, investigation and evaluation of geothermal fields and the dissemination and publication of the results thereof and of information, statistics and data regarding mineral production and utilization, mining practices and methods, geologic investigations relative to mining engineering, construction and planning, and operation; training of technical personnel of the Bureau of Mines in specialized fields, and the construction of buildings, metallurgical laboratories including the University of the Philippines, pilot plants, and other facilities and the purchase and maintenance of motor vehicles, equipment, apparatus, furniture and supplies necessary to carry out the purposes aforesaid.\""}},{"id":"PH-H3778-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section two of the same Act is hereby amended to read as follows:\n\"Sec. 2. This fund shall consist of ten per centum of the total mining taxes paid to the Government and all royalties or participation except ad valorem tax received by the Government in the exploitation, processing and disposition of minerals in government mineral reservations administered by the Secretary of Agriculture and Natural Resources and/or the Director of Mines, which fund shall be set aside at the beginning of each fiscal year and shall be placed at the disposal of the Secretary of Agriculture and Natural Resources for the purpose enumerated in Section one hereof.\""}},{"id":"PH-H3778-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Sections One and Two of Republic Act Numbered Four Hundred and Six, Entitled \"An Act Creating a Mines Special Fund in the Bureau of Mines to be Used for the Canvassing and Evaluation of Mineral Deposits Needed in the Development of Philippine Industries, and the Publication of Mining Statistics and Data, and for Other Purposes\"","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3779"] = {"id":"PH-H3779","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4794_1966.html","fetchedAt":"2026-10-06","articleCount":13,"structureMode":"ARTICLE","title":{"zh":"授予 Edmundo I. Perez 在南甘马粦省建设、维护和运营无线电广播与电视站的特许经营权法案","en":"An Act Granting Edmundo I. Perez a Franchise to Construct, Maintain and Operate Radio Broadcasting and Television Stations in the Province of Camarines Sur","orig":"An Act Granting Edmundo I. Perez a Franchise to Construct, Maintain and Operate Radio Broadcasting and Television Stations in the Province of Camarines Sur","vi":"Đạo luật cấp quyền khai thác cho Edmundo I. Perez để xây dựng, lắp đặt, vận hành và duy trì hệ thống phát thanh và truyền hình tại tỉnh Camarines Sur","th":"พระราชบัญญัติให้สัมปทานแก่ Edmundo I. Perez เพื่อก่อสร้าง ติดตั้ง ดำเนินการ และบำรุงรักษาระบบวิทยุกระจายเสียงและวิทยุโทรทัศน์ในจังหวัด Camarines Sur","id":"Undang-Undang memberikan waralaba kepada Edmundo I. Perez untuk membangun, memasang, mengoperasikan, dan memelihara sistem penyiaran radio dan televisi di Provinsi Camarines Sur","ms":"Akta memberikan francais kepada Edmundo I. Perez untuk membina, memasang, mengendalikan dan menyelenggara sistem penyiaran radio dan televisyen di Wilayah Camarines Sur"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 4794","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 13 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4794_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3779-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution, Act Numbered Three thousand eight hundred forty-six, entitled \"An Act providing for the regulation of radio stations and radio communications in the Philippine Islands, and for other purposes;\" Act Numbered Three thousand nine hundred ninety-seven, known as the Radio Broadcasting Law, Commonwealth Act Numbered One hundred forty-six, known as the Public Service Act, and their amendments, and other applicable laws not inconsistent with this Act, Edmundo I. Perez is hereby granted a franchise to establish, maintain and operate radio broadcasting and television stations in the Province of Camarines Sur, with principal station in the City of Naga."}},{"id":"PH-H3779-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This franchise shall continue for a period of twenty-five years from the date said stations shall be put in operation."}},{"id":"PH-H3779-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This franchise is likewise made upon the express condition that the grantee shall provide adequate public service time to enable the Government, through his stations, to reach the population on important issues, shall assist in the function of public information and education, shall conform to the ethics of honest enterprise, and shall not use his stations for the dissemination of deliberately false information or willful misrepresentations, or to the detriment of the public health and morals, or incite, encourage or assist in subversive or treasonable acts."}},{"id":"PH-H3779-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The grantee’s radio broadcasting and television stations shall not be put in actual operation until the Secretary of Public Works and Communications shall have allotted to the grantee the frequency and wave length and channel to be used under this franchise and issued to the grantee a license for such use."}},{"id":"PH-H3779-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The radio broadcasting and television stations of the grantee shall be so constructed and its wave length and channel so selected as to avoid interference with existing radio and television stations and to further afford the expansion of the grantee’s service."}},{"id":"PH-H3779-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"A special right is reserved to the President of the Philippines in time of war, rebellion, public peril, calamity, disaster or disturbance of peace and order, to cause the closing of said stations or to authorize the temporary use and operation thereof by any department of the Government without compensating the grantee for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H3779-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee shall be liable to pay the same taxes, unless exempted therefrom, on his real estate, buildings and personal property, exclusive of the franchise, as other persons or corporations are now or hereafter may be required by law to pay. He shall be liable further to pay all other taxes as provided for in the National Internal Revenue Code by reason of this franchise."}},{"id":"PH-H3779-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Acceptance of this franchise shall be given in writing by the grantee within six months from the approval of this Act; when so accepted, the grantee shall be empowered to exercise the privilege granted thereby."}},{"id":"PH-H3779-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee shall post a bond in the amount of ten thousand pesos to answer for the fulfillment of the terms embodied in the franchise. If after two years from the date of the acceptance of the franchise the grantee shall have complied with the terms thereof, the Secretary of Public Works and Communications shall cause the cancellation of the aforesaid bond."}},{"id":"PH-H3779-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The grantee shall not require any previous censorship of any speech, play, act, or scene or other matter for broadcast or telecast, from his stations; but if any speech, play, act or scene or other matter should constitute a violation of any law or infringement of a private right, the grantee shall be free from any criminal or civil liability whatsoever which might arise by reason of such speech, play, act or scene or other matter. The grantee, however, reserves the right to cut off from the air any broadcast or telecast which in any manner tends to incite treason, rebellion or sedition, or the theme or language used therein is indecent or immoral."}},{"id":"PH-H3779-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise nor the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other company or corporation organized for the same purpose, without the approval of the Congress of the Philippines first had. Any corporation to which this franchise may be sold, transferred or assigned shall be subject to the corporation laws of the Philippines now existing or hereafter enacted; and any person, firm, company, corporation or other commercial or legal entity, to which this franchise is sold, transferred or assigned shall be subject to all conditions, terms, restrictions and limitations of this franchise as fully and completely and to the same extent as if the franchise had been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H3779-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The franchise hereby granted shall be subject to amendment, alteration or repeal by the Congress of the Philippines when public interest so requires, and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H3779-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Edmundo I. Perez a Franchise to Construct, Maintain and Operate Radio Broadcasting and Television Stations in the Province of Camarines Sur","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3780"] = {"id":"PH-H3780","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4795_1966.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"为南莱特省增设两名助理省检察官，并进一步修订《行政法典》第1674条的法案","en":"An Act Providing for Two Additional Assistant Provincial Fiscals for the Province of Southern Leyte, by Further Amending Section Sixteen Hundred Seventy-Four of the Administrative Code","orig":"An Act Providing for Two Additional Assistant Provincial Fiscals for the Province of Southern Leyte, by Further Amending Section Sixteen Hundred Seventy-Four of the Administrative Code"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 4795","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4795_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3780-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section sixteen hundred seventy-four of the Administrative Code, as amended, is further amended by inserting after the subparagraph relative to the number of assistant provincial fiscals in the Province of Leyte, the following new subparagraph to read as follows:\n\"Southern Leyte, four assistant provincial fiscals;\""}},{"id":"PH-H3780-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for Two Additional Assistant Provincial Fiscals for the Province of Southern Leyte, by Further Amending Section Sixteen Hundred Seventy-Four of the Administrative Code","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3781"] = {"id":"PH-H3781","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4796_1966.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"增加邦阿西楠省助理省检察官人数，并为此修订《行政法典》第1674条（经修正）的法案","en":"An Act Increasing the Number of Assistant Provincial Fiscals for the Province of Pangasinan, Amending for the Purpose Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended","orig":"An Act Increasing the Number of Assistant Provincial Fiscals for the Province of Pangasinan, Amending for the Purpose Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 4796","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4796_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3781-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The provision of Section sixteen hundred seventy-four of the Administrative Code, as amended, relative to the number of assistant provincial fiscals in the Province of Pangasinan, is further amended to read as follows:\n\"Pangasinan, twenty assistant provincial fiscal;\""}},{"id":"PH-H3781-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Increasing the Number of Assistant Provincial Fiscals for the Province of Pangasinan, Amending for the Purpose Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3782"] = {"id":"PH-H3782","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4797_1966.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"在伊洛伊洛市设立医院，名称为Iloilo City Hospital，并授权为此拨款的法案","en":"An Act Establishing a Hospital in Iloilo City, to be Known as Iloilo City Hospital, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Establishing a Hospital in Iloilo City, to be Known as Iloilo City Hospital, and Authorizing the Appropriation of Funds Therefor","vi":"Đạo luật thành lập Bệnh viện tại Thành phố Iloilo với tên gọi Bệnh viện Thành phố Iloilo, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติจัดตั้งโรงพยาบาล ในเมือง Iloilo ในชื่อ โรงพยาบาลเมือง Iloilo และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang membentuk Rumah Sakit di Kota Iloilo dengan nama Rumah Sakit Kota Iloilo, dan mengalokasikan dana untuk itu","ms":"Akta menubuhkan Hospital di Bandar Iloilo dengan nama Hospital Bandar Iloilo, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 4797","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4797_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3782-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Director of Medical Services, a hospital in Iloilo City, to be known as Iloilo City Hospital."}},{"id":"PH-H3782-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of five hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the construction of the building. The operation and maintenance of the hospital shall be in accordance with the provisions of Republic Act Numbered Nineteen hundred thirty-nine, otherwise known as Hospital Financing Act."}},{"id":"PH-H3782-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Establishing a Hospital in Iloilo City, to be Known as Iloilo City Hospital, and Authorizing the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3783"] = {"id":"PH-H3783","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4798_1966.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"为第三司法区增设一名法官主持邦阿西楠初审法院，常设于邦阿西楠省Alaminos市镇，为此修订1948年《司法法》第50条与第52条的法案","en":"An Act Providing One Additional Judge for the Third Judicial District to Preside Over the Court of First Instance of Pangasinan, with Permanent Station in the Municipality of Alaminos, Province of Pangasinan, Amending for the Purpose Sections Fifty and Fifty-Two of the Judiciary Act of 1948","orig":"An Act Providing One Additional Judge for the Third Judicial District to Preside Over the Court of First Instance of Pangasinan, with Permanent Station in the Municipality of Alaminos, Province of Pangasinan, Amending for the Purpose Sections Fifty and Fifty-Two of the Judiciary Act of 1948"},"level":"law","status":"active","topics":["judiciary"],"docNumber":"Republic Act No. 4798","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4798_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3783-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The third paragraph of Section fifty of Republic Act Numbered Two hundred ninety-six, otherwise known as the Judiciary Act of 1948, as amended, is further amended to read as follows:\n\"Thirteen judges shall be commissioned for the Third Judicial District. Eleven judges shall preside over the Court of First Instance of Pangasinan and shall be known as judges of the first, second, third, fourth, fifth, sixth, seventh, eighth, ninth, tenth, and eleventh branches thereof, respectively. Two judges shall preside over the Court of First Instance of Zambales, and shall be known as judges of the first and second branches thereof, respectively.\""}},{"id":"PH-H3783-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The third subparagraph of the second paragraph of Section fifty-two of the same Act, as amended, is further amended to read as follows:\n\"For the Third Judicial District, two judges shall be stationed in the Municipality of Lingayen, Province of Pangasinan; three judges shall be stationed in the City of Dagupan; two judges, in the Municipality of Urdaneta, Province of Pangasinan; one judge, in the Municipality of Tayug, same province; two judges, in the Municipality of Alaminos, and another in the City of San Carlos, same, province; the judge of the first branch of the Court of First Instance of Zambales shall be stationed in the Municipality of Olongapo, Province of Zambales, and the judge of the second branch, in the Municipality of Iba, same province.\""}},{"id":"PH-H3783-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"There is hereby appropriated out of any funds in the National Treasury not otherwise appropriated, the sum of sixty thousand pesos or so much thereof as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H3783-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing One Additional Judge for the Third Judicial District to Preside Over the Court of First Instance of Pangasinan, with Permanent Station in the Municipality of Alaminos, Province of Pangasinan, Amending for the Purpose Sections Fifty and Fifty-Two of the Judiciary Act of 1948","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3784"] = {"id":"PH-H3784","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4799_1966.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Alaminos市","en":"An Act Creating a Branch Office of the Register of Deeds of the Province of Pangasinan, with Permanent Station at the Municipality of Alaminos, Same Province, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Creating a Branch Office of the Register of Deeds of the Province of Pangasinan, with Permanent Station at the Municipality of Alaminos, Same Province, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4799","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4799_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3784-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby created a branch office of the Register of Deeds of the Province of Pangasinan, with permanent station at the Municipality of Alaminos, same province, which shall perform all the duties and function of the register of deeds for the municipalities of Alaminos, Infanta, Burgos, Dasol, Agno, Bani, Balinao, Anda and Sual, all in the Province of Pangasinan."}},{"id":"PH-H3784-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"To carry out the provisions of this, Act, there is hereby authorized to be appropriated for the fiscal year nineteen hundred sixty-eight, out of any funds in the National Treasury not otherwise appropriated, the sum of twenty thousand seven hundred eighty-four pesos to be spent for the following:\n(a) Deputy Register of Deeds ₱5,112.00\n(b) One supervising clerk 3,300.00\n(c) One senior cash clerk 2,424.00\n(d) One clerk 2,196.00\n(e) One messenger 1,800.00\n(f) One janitor 1,476.00\n(g) One laborer 1,476.00\n(h) Sundry expenses 3,000.00 Such sums as may be necessary for the same purpose in subsequent years shall be included in the annual General Appropriations Act."}},{"id":"PH-H3784-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53"};
  FT["PH-H3785"] = {"id":"PH-H3785","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4800_1966.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"在布基农省设立Don Carlos市镇的法案","en":"An Act Creating the Municipality of Don Carlos in the Province of Bukidnon","orig":"An Act Creating the Municipality of Don Carlos in the Province of Bukidnon","vi":"Đạo luật thành lập Thị trấn Don Carlos tại Tỉnh Bukidnon","th":"พระราชบัญญัติจัดตั้งเทศบาล Don Carlos ในจังหวัด Bukidnon","id":"Undang-Undang membentuk Kotamadya Don Carlos di Provinsi Bukidnon","ms":"Akta mewujudkan Perbandaran Don Carlos di Wilayah Bukidnon"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4800","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4800_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3785-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The barrios of Sinanguyan, Don Carlos del Norte, Don Carlos del Sur, Kalao-kalao, New Nongnongan (Masimag), Upper Bokbok, Kalubihon, Kiara, Kawilihan, Old Nongnongan, Pualas, Pinamaloy, Manlamunay, Minsalagan and Kibatang, all of the Municipality of Maramag, Province of Bukidnon, are hereby segregated from said municipality and constituted into a new and distinct political entity to be known as the Municipality of Don Carlos, same province, with the seat of government in the present site of Barrio Don Carlos del Sur."}},{"id":"PH-H3785-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The first mayor, vice-mayor and councilors of the new municipality shall be elected in the nineteen hundred sixty-seven general elections for local officials."}},{"id":"PH-H3785-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the Municipality of Don Carlos in the Province of Bukidnon","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3786"] = {"id":"PH-H3786","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4801_1966.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"在布基农省设立Kitao-Tao市镇的法案","en":"An Act Creating the Municipality of Kitao-Tao in the Province of Bukidnon","orig":"An Act Creating the Municipality of Kitao-Tao in the Province of Bukidnon","vi":"Đạo luật thành lập Thị trấn Kitao-Tao tại Tỉnh Bukidnon","th":"พระราชบัญญัติจัดตั้งเทศบาล Kitao-Tao ในจังหวัด Bukidnon","id":"Undang-Undang membentuk Kotamadya Kitao-Tao di Provinsi Bukidnon","ms":"Akta mewujudkan Perbandaran Kitao-Tao di Wilayah Bukidnon"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4801","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4801_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3786-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The barrios of San Isidro, Bolocaon, Kimolong, Kitaihon, Kitaotao, Magsaysay, Santo Rosario, Kauyonan, Malobalo, Bobong, Simod, Balangigay, Kitobo and Dalorong, all of the Municipality of Kibawe (subsequently annexed by the Municipality of Dangcagan), Province of Bukidnon, and the barrio of Berehiba of the Municipality of Maramag, also of the Province of Bukidnon, are hereby separated from said municipalities and constituted into a new and separate municipality to be known as the Municipality of Kitaotao, same province, with the seat of government at the present site of Barrio Kitaotao."}},{"id":"PH-H3786-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The first mayor, vice-mayor and councilors of the new municipality, shall be elected in the nineteen hundred sixty-seven general elections for local officials."}},{"id":"PH-H3786-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the Municipality of Kitao-Tao in the Province of Bukidnon","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3787"] = {"id":"PH-H3787","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4802_1966.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"在布基农省设立Quezon市镇的法案","en":"An Act Creating the Municipality of Quezon in the Province of Bukidnon","orig":"An Act Creating the Municipality of Quezon in the Province of Bukidnon","vi":"Đạo luật thành lập Thị trấn Quezon tại Tỉnh Bukidnon","th":"พระราชบัญญัติจัดตั้งเทศบาล Quezon ในจังหวัด Bukidnon","id":"Undang-Undang membentuk Kotamadya Quezon di Provinsi Bukidnon","ms":"Akta mewujudkan Perbandaran Quezon di Wilayah Bukidnon"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4802","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4802_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3787-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The barrios and sitios of Nanapan (Pontian), Sta. Cruz, Dilapa, Kiburiao, Mibantang and Cebole in the Municipality of Maramag (subsequently annexed by the Municipality of Dangcagan), Province of Bukidnon, and the barrios of Salwagan, Manoto, San Jose, Kiokong, Paitan, Lumintao and Kulaman in the Municipality of Maramag, Province of Bukidnon, are hereby separated from their respective mother municipalities and constituted into a new and separate municipality of said province to be known as the Municipality of Quezon, with the seat of government at the present site of Barrio Kiokong."}},{"id":"PH-H3787-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The first mayor, vice-mayor and councilors shall be elected in the nineteen hundred and sixty-seven general elections for local officials."}},{"id":"PH-H3787-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the Municipality of Quezon in the Province of Bukidnon","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3788"] = {"id":"PH-H3788","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4803_1966.html","fetchedAt":"2026-10-06","articleCount":11,"structureMode":"ARTICLE","title":{"zh":"授予 Tayabas Ice Plant and Cold Storage 在奎松省 Tayabas 市镇建设、运营制冰厂与冷库并在该市镇及邻近市镇售冰及供应冷库的特许经营权法案","en":"An Act Granting Tayabas Ice Plant and Cold Storage a Franchise to Construct, Operate and Maintain an Ice Plant and Cold Storage in the Municipality of Tayabas, Province of Quezon, and to Sell Ice and to Supply Cold Storage Therein and in its Neighboring Municipalities","orig":"An Act Granting Tayabas Ice Plant and Cold Storage a Franchise to Construct, Operate and Maintain an Ice Plant and Cold Storage in the Municipality of Tayabas, Province of Quezon, and to Sell Ice and to Supply Cold Storage Therein and in its Neighboring Municipalities"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 4803","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 11 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4803_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3788-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the conditions imposed by this Act, there is hereby granted for a period of twenty-five years to Tayabas Ice Plant and Cold Storage, hereinafter referred to as the grantee, a franchise to construct, operate and maintain an ice plant and cold storage in the Municipality of Tayabas, Province of Quezon, for the purpose of manufacturing and distributing ice and supplying cold storage therein and in its neighboring municipalities, and to charge and collect a schedule of prices and rates for the ice and cold storage so furnished, which shall at all times be subject to the regulations of the Public Service Commission or its legal successor."}},{"id":"PH-H3788-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Said grantee shall manufacture and supply ice up to the limit of the capacity of its plant, said limit to be determined by the Public Service Commission or its legal successor in such certificate of convenience and public necessity as may be issued by it, as provided by Section four of this Act."}},{"id":"PH-H3788-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All the apparatus and appurtenances to be used by the grantee shall be modern, safe, and first class in every respect, and the grantee shall, whenever the Public Service Commission or its legal successor determines that public interest reasonably require it, change or alter any of its apparatus and appurtenances at grantee’s expense."}},{"id":"PH-H3788-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The grantee shall not exercise any right or privilege under this franchise nor commence any construction thereunder, unless and until the grantee shall first file with the Public Service Commission within six months from the date of approval of this Act:\n(1) Its written acceptance of the terms and provisions of this Act;\n(2) Its written acceptance of the terms and conditions of the certificate of convenience and public necessity required by law for the granting of this franchise and issued by the Public Service Commission in the form and character provided for in Commonwealth Act Numbered One hundred and forty-six, as amended; and\n(3) A document or documents evidencing receipt by the Treasurer of the Philippines of the deposit or deposits required by law for such certificate of convenience and public necessity as an earnest proof of good faith and guaranty that the grantee shall complete the work within the period to be fixed by the Commission.\nIf the grantee shall not commence the manufacture and distribution of ice and the supplying of cold storage in the places referred to in the certificate of convenience and public necessity, obtained and filed as herein provided, within such period as the Public Service Commission or its legal successor shall have fixed, unless prevented by an act of God or force majeure, martial law, riot, civil commotion, usurpation by a military power or any other cause beyond the grantee’s control, said commission or its legal successor may, in its discretion, declare such certificate null and void, and the deposit or deposits made by the grantee forfeited in favor of the National Government."}},{"id":"PH-H3788-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"After grantee’s compliance with the requirements of the next preceding section, the Public Service Commission or its legal successor, by proper order or writ, shall authorize the construction of necessary work for the purposes of this franchise within a reasonable time to be determined by the said Commission.\nUpon determination by the Public Service Commission or its legal successor, after a reasonable written notice to the grantee and a hearing, that the grantee has violated any of the provision of this section as to the commencement and/or completion of work authorized by the certificate of convenience and public necessity, the said Commission or its legal successor shall declare the bond or bonds forfeited not as a penalty but as liquidated damages to the National Government. The said Commission or its legal successor shall order return of the deposit as aforestated, together with any work authorized by its certificate of convenience and public necessity, in accordance with the terms and conditions of said certificate, and the Treasurer of the Philippines shall return said deposit to the grantee together with said interest and/or dividends immediately upon presentation to him of a certified copy of such order of the Public Service Commission or its legal successor."}},{"id":"PH-H3788-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This franchise is granted subject to the provisions of the Constitution, Commonwealth Act Numbered One hundred forty-six as amended, and Act Numbered Fourteen hundred and fifty-nine, as amended; and with the understanding and upon the condition that it shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when public interest so requires.\nThe Public Service Commission shall provide, as a condition for the issuance of the certificate of convenience and public necessity, that the certificate shall be valid only for a definite period of time and that violation of any of these conditions shall cause the immediate cancellation of the certificate without the necessity of any express action on the part of the Commission."}},{"id":"PH-H3788-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The books, records and accounts of the grantee shall always be open for the inspection of the municipal treasurer of the Municipality of Tayabas, Province of Quezon, or his authorized representatives, and it shall be the duty of the grantee to submit to the municipal treasurer quarterly reports in duplicate showing the gross receipts for the quarter past, one of which shall be forwarded by the municipal treasurer to the Auditor General who shall keep the same on file."}},{"id":"PH-H3788-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee, upon prior approval of the Congress of the Philippines, may sell, lease, grant, convey, assign, give in usufruct, or transfer this franchise and all properties and rights acquired thereunder to any individual, co-partnership, private public or quasi-public association, corporation, or joint stock company qualified under the Constitution and competent to operate the business hereby authorized, but transfer of title to the franchise or any right of ownership or interest acquired under such sale, lease, grant, conveyance, assignment, gift in usufruct, or transfer shall not be effective even after such approval shall have been obtained until there shall have been filed with the Public Service Commission or its legal successor an agreement in writing by which the individual, co-partnership, private, public or quasi-public association, corporation, or joint stock company in whose favor such sale, lease, grant, conveyance, assignment, gift in usufruct or transfer, is made, shall be firmly bound to comply with all the terms and conditions imposed upon the grantee by this franchise and by any and all certificates of convenience and public necessity heretofore issued by the Public Service Commission or its legal successor, and to accept the same subject to all existing terms and conditions."}},{"id":"PH-H3788-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The Public Service Commission or its legal successor shall have the power, after a reasonable written notice to the grantee and of hearing of the interested parties, to declare the forfeiture of this franchise and all rights inherent in the same for failure on the part of the grantee to comply with any of the terms and conditions hereof, unless such failure shall have been directly and primarily caused by an act of God, force majeure, usurped right, uprising or other cause beyond the control of the grantee. Against such declaration or forfeiture by the Public Service Commission or its legal successor, the grantee may apply for the remedies provided in Sections thirty-four and thirty-six of Commonwealth Act Numbered One hundred forty-six, as amended. The remedy provided herein shall not be a bar to any other remedy provided by existing laws for the forfeiture of this franchise."}},{"id":"PH-H3788-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"In the event of any competing individual, association of persons, or corporations receiving from the Congress of the Philippines a similar franchise in which there shall be any term or terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall ipso facto become a part of the terms hereof and shall operate equally in favor of the grantee as in the case of said competing individual, association of persons, or corporation."}},{"id":"PH-H3788-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Tayabas Ice Plant and Cold Storage a Franchise to Construct, Operate and Maintain an Ice Plant and Cold Storage in the Municipality of Tayabas, Province of Quezon, and to Sell Ice and to Supply Cold Storage Therein and in its Neighboring Municipalities","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3789"] = {"id":"PH-H3789","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4804_1966.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将萨马省Catbalogan设为入境口岸并授权为此拨付所需经费的法案","en":"An Act Making Catbalogan, Samar, a Port of Entry, and Authorizing the Appropriation of Necessary Funds for the Purpose","orig":"An Act Making Catbalogan, Samar, a Port of Entry, and Authorizing the Appropriation of Necessary Funds for the Purpose"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4804","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4804_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3789-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section seven hundred one of Republic Act Numbered Nineteen hundred thirty-seven, otherwise known as the Tariff and Customs Code of the Philippines, as amended by Republic Act Numbered Thirty-seven hundred fifty-seven, is further amended to read as follows:\n\"Sec. 701. Collection districts and port of entry thereof.— For administrative purposes, the Philippines shall be divided into as many collection districts as there are at present existing, the respective limits of which may be changed from time to time by the Commissioner, upon the approval of the department head. The principal ports of entry for the respective collection districts shall be Manila, Sual, Tabaco, Cebu, Pulupandan, Sia-in, Iloilo, Davao, Legaspi, Zamboanga, Jolo, Aparri, Jose Panganiban, Cagayan, Tacloban, San Fernando, Hinigaran, Dumaguete City, Maasin, Masao, Catbalogan, and Batangas.\""}},{"id":"PH-H3789-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of two hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment and operation of the customs services at the port of Catbalogan in the Province of Samar for the fiscal year nineteen hundred sixty-seven. Thereafter, such sums necessary for the same purpose shall be included in the annual general Appropriations Act."}},{"id":"PH-H3789-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Making Catbalogan, Samar, a Port of Entry, and Authorizing the Appropriation of Necessary Funds for the Purpose","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3790"] = {"id":"PH-H3790","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4805_1966.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"增加阿布拉省Bangued市镇阿布拉省立医院床位并授权为此拨款的法案","en":"An Act Increasing the Bed Capacity of the Abra Provincial Hospital in the Municipality of Bangued, Province of Abra, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Increasing the Bed Capacity of the Abra Provincial Hospital in the Municipality of Bangued, Province of Abra, and Authorizing the Appropriation of Funds Therefor","vi":"Đạo luật tăng sức chứa giường bệnh của Bệnh viện Tỉnh Abra tại Đô thị Bangued, Tỉnh Abra, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติเพิ่มจำนวนเตียงของโรงพยาบาลจังหวัด Abra ในเทศบาล Bangued จังหวัด Abra และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang meningkatkan kapasitas tempat tidur Rumah Sakit Provinsi Abra di Kotamadya Bangued, Provinsi Abra, dan mengalokasikan dana untuk itu","ms":"Akta meningkatkan kapasiti katil Hospital Wilayah Abra di Perbandaran Bangued, Wilayah Abra, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 4805","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4805_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3790-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The bed capacity of the Abra Provincial Hospital in the Municipality of Bangued, Province of Abra, is hereby increased to fifty beds."}},{"id":"PH-H3790-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the operation and maintenance of said hospital during the fiscal year nineteen hundred sixty-seven. Thereafter, such sums as may be needed for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H3790-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Increasing the Bed Capacity of the Abra Provincial Hospital in the Municipality of Bangued, Province of Abra, and Authorizing the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3791"] = {"id":"PH-H3791","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4806_1966.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"规定在黎刹省Tanay市镇设立水土保持示范站，名称为黎刹水土保持示范站，并授权为此拨款的法案","en":"An Act Providing for the Establishment of a Soil Conservation Demonstration Station in the Municipality of Tanay, Province of Rizal, to be Known as Rizal Soil Conservation Demonstration Station, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Providing for the Establishment of a Soil Conservation Demonstration Station in the Municipality of Tanay, Province of Rizal, to be Known as Rizal Soil Conservation Demonstration Station, and Authorizing the Appropriation of Funds Therefor","vi":"Đạo luật thành lập Trạm Trình diễn Soil Conservation tại Thị trấn Tanay, Tỉnh Rizal với tên gọi Trạm Trình diễn Rizal Soil Conservation, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติจัดตั้งสถานีสาธิต Soil Conservation ในเทศบาล Tanay จังหวัด Rizal ในชื่อสถานีสาธิต Rizal Soil Conservation และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang membentuk Stasiun Percontohan Soil Conservation di Kotamadya Tanay, Provinsi Rizal dengan nama Stasiun Percontohan Rizal Soil Conservation, dan mengalokasikan dana untuk itu","ms":"Akta menubuhkan Stesen Demonstrasi Soil Conservation di Perbandaran Tanay, Wilayah Rizal dengan nama Stesen Demonstrasi Rizal Soil Conservation, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4806","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4806_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3791-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a soil conservation demonstration stations in Barrio Sampaloc, Municipality of Tanay, Province of Rizal. The said station shall be under the supervision of the Director of Soils and shall be subject to the provisions of Republic Act Numbered Six hundred twenty-two."}},{"id":"PH-H3791-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of the soil conservation demonstration station for the fiscal year nineteen hundred and sixty-seven. Thereafter, such sum as may be necessary for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H3791-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Establishment of a Soil Conservation Demonstration Station in the Municipality of Tanay, Province of Rizal, to be Known as Rizal Soil Conservation Demonstration Station, and Authorizing the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3792"] = {"id":"PH-H3792","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4807_1966.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Bay市","en":"An Act Establishing a Fresh-Water Demonstration Fish Farm and Nursery at Barrio Santo Domingo, Municipality of Bay, Province of Laguna, and Appropriating Funds Therefor","orig":"An Act Establishing a Fresh-Water Demonstration Fish Farm and Nursery at Barrio Santo Domingo, Municipality of Bay, Province of Laguna, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 4807","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4807_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3792-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established and maintained, under the supervision of the Commissioner of Fisheries, a fresh-water demonstration fish farm and nursery at Barrio Santo Domingo, Municipality of Bay, Province of Laguna."}},{"id":"PH-H3792-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of eighty thousand pesos is hereby appropriated, out of any funds in the National Treasury not otherwise appropriated, to carry out the purpose of this Act during the fiscal year nineteen hundred and sixty-seven. Thereafter, such sums as may be necessary for the same purpose shall be included in the annual General Appropriations Act."}},{"id":"PH-H3792-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53"};
  FT["PH-H3793"] = {"id":"PH-H3793","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4808_1966.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"在达沃省设立Montevista市镇的法案","en":"An Act Creating the Municipality of Montevista in the Province of Davao","orig":"An Act Creating the Municipality of Montevista in the Province of Davao","vi":"Đạo luật thành lập Thị trấn Montevista tại Tỉnh Davao","th":"พระราชบัญญัติจัดตั้งเทศบาล Montevista ในจังหวัด Davao","id":"Undang-Undang membentuk Kotamadya Montevista di Provinsi Davao","ms":"Akta mewujudkan Perbandaran Montevista di Wilayah Davao"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4808","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4808_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3793-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"(a) Barrios San Jose and Bankerohan and part of Barrio Lino-an of the Municipality of Nabunturan; Barrio New Visayas and part of Barrio Siocon of the Municipality of Compostela; Barrio Bankerohan and part of Barrio Olaycon of the Municipality of Monkayo; part of Barrio Camansa of the Municipality of Asuncion; and part of Barrio Camansi of the Municipality of New Corella, including the sitios of New Tibungco, New Dalaguete, Camantangan, Mayaon, Maputi, Sambayon, Sayoro, San Vicente, Inabatan, Tapia, New Calape, Canidkid, Baguinonan, Daoman, Alimadmad, Tandawan and New Tubigon, are separated from their mother municipalities and constituted into an independent and distinct municipality in the same province which shall be known as the Municipality of Montevista with the seat of government in the present site of Barrio San Jose.\n(b) The boundary which shall separate the Municipality of Montevista from the mother municipalities of Nabunturan, Compostela, Monkayo, Asuncion and New Corella shall be: beginning from Casangay Bridge in Barrio Linoan, Municipality of Nabunturan, at Km. 96 along the Davao-Agusan Highway, running west up to the intersection of Saug River and Pongtod Creek at Barrio Camansa, Municipality of Asuncion; thence running northward along the east side of the Saug River up to Barrio Camansi, Municipality of New Corella; thence running through a straight imaginary line to Sitio Monte Alto, Barrio Camansi; thence to the Concrete Box Culvert of Small Olaycon Creek, Barrio Olayco, Municipality of Monkayo, at Km. 111 along the Davao-Agusan Highway; thence to Sitio Tandawan, Barrio New Visayas, Municipality of Compostela, where it intersects the Compostela-Monkayo boundary line; thence running southward up to the Point where it intersects the Compostela-Nabunturan boundary line in Barrio Siocon opposite the mouth of the Casangay Creek at Manat River; and then running west up to Casangay Bridge at Km. 96 along the Davao-Agusan Highway, Municipality of Nabunturan."}},{"id":"PH-H3793-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The municipal mayor, vice-mayor, and councilors of the newly created Municipality of Montevista shall be elected in the next general elections for local officials."}},{"id":"PH-H3793-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the Municipality of Montevista in the Province of Davao","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3794"] = {"id":"PH-H3794","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4809_1966.html","fetchedAt":"2026-10-06","articleCount":8,"structureMode":"ARTICLE","title":{"zh":"在奎松省 Dipaculao 与 San Luis 市镇及 Dilasag 市镇区分别设立若干新村社的法案","en":"An Act Creating Certain Barrios in the Municipalities of Dipaculao and San Luis and the Municipal District of Dilasag, Province of Quezon","orig":"An Act Creating Certain Barrios in the Municipalities of Dipaculao and San Luis and the Municipal District of Dilasag, Province of Quezon"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4809","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 8 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4809_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3794-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Bullongan, Detale, Dibotunan, Diarabasin and Dimawiwit are hereby separated from Barrio Mijares in the Municipality of Dipaculao, Province of Quezon, and are converted into distinct and independent barrios to be known as Barrios Bullongan, Detale, Dibotunan, Diarabasin and Dimawiwit, respectively."}},{"id":"PH-H3794-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sitio of Dianed is hereby separated from Barrio Dinadiawan in the same municipality, and is converted into a distinct and independent barrio to be known as Barrio Dianed."}},{"id":"PH-H3794-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sitio of Lipit is hereby separated from Barrio Ipil in the same municipality, and is converted into a distinct and independent barrio to be known as Barrio Lipit."}},{"id":"PH-H3794-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The sitio of Sapang Kawayan is hereby separated from Barrio Silay in the same municipality, and is converted into a distinct and independent barrio to be known as Barrio Sapang Kawayan."}},{"id":"PH-H3794-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The sitios of Dibay-abay, Diotorin, Salaysay, Dibulalan, Cultiv, Calipaket, Calapnit and Dibuwan in the Municipality of San Luis, same province, are hereby converted into a distinct and independent barrio to be known as Barrio Dibut."}},{"id":"PH-H3794-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The sitios of Labgan, Alasanay, Dimanayat, Dikapanikihan, Pulo and Cabusan in the same municipality are hereby converted into a distinct and independent barrio to be known as Barrio Dikapinisan."}},{"id":"PH-H3794-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The sitios of Lawang and Ura in the Municipal District of Dilasag, same province, are hereby converted into distinct and independent barrios to be known as barrios Lawang and Ura, respectively."}},{"id":"PH-H3794-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating Certain Barrios in the Municipalities of Dipaculao and San Luis and the Municipal District of Dilasag, Province of Quezon","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3795"] = {"id":"PH-H3795","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1966/ra_4810_1966.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"修订第4025号共和国法（题为“授予Dagupan Electric Corporation在Dagupan市建设、设立与运营私人固定陆地对陆地移动无线电台的许可”）","en":"An Act Amending Republic Act Numbered Four Thousand Twenty-Five, Entitled \"An Act Granting the Dagupan Electric Corporation a Permit to Construct, Establish, and Operate Private Fixed Land-Based to Land-Mobile Radio Stations for the Reception and Transmission of Radio Communications in Dagupan City\"","orig":"An Act Amending Republic Act Numbered Four Thousand Twenty-Five, Entitled \"An Act Granting the Dagupan Electric Corporation a Permit to Construct, Establish, and Operate Private Fixed Land-Based to Land-Mobile Radio Stations for the Reception and Transmission of Radio Communications in Dagupan City\"","vi":"Đạo luật sửa đổi Đạo luật Cộng hòa số 4025","th":"พระราชบัญญัติแก้ไขเพิ่มเติมพระราชบัญญัติแห่งสาธารณรัฐที่ 4025","id":"Undang-Undang mengubah Undang-Undang Republik No. 4025","ms":"Akta meminda Akta Republik No. 4025"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4810","issuingBody":"Congress of the Philippines","promulgatedDate":"1966-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1966/ra_4810_1966.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3795-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one of Republic Act Numbered Four thousand twenty-five is hereby amended to read as follows:\n\"Sec. 1. There is hereby granted to Dagupan Electric Corporation a permit to construct, maintain, and operate, subject to the approval of the Secretary of Public Works and Communications, a private fixed point-to-point land-based and land-mobile radio stations in the Philippines for the reception and transmission of wireless messages on radiotelephony, each to be provided with radio transmitting apparatus and radio receiving apparatus.\""}},{"id":"PH-H3795-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The title of the same Act is amended to read as follows:\n\"An Act granting the Dagupan Electric Corporation a permit to construct, establish and operate private fixed point-to-point land-based and land-mobile radio stations for the reception and transmission of radio communications in the Philippines.\""}},{"id":"PH-H3795-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1966."}}],"pack":"ph-p53","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Republic Act Numbered Four Thousand Twenty-Five, Entitled \"An Act Granting the Dagupan Electric Corporation a Permit to Construct, Establish, and Operate Private Fixed Land-Based to Land-Mobile Radio Stations for the Reception and Transmission of Radio Communications in Dagupan City\"","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
